package com.efficientskilling;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class EfficientSkillingPluginTest
{
	public static void main(String[] args) throws Exception
	{
		loadPlugin();
		RuneLite.main(args);
	}

	@SuppressWarnings("unchecked")
	private static void loadPlugin()
	{
		ExternalPluginManager.loadBuiltin(EfficientSkillingPlugin.class);
	}
}

package com.efficientskilling;

import net.runelite.api.Experience;

public final class GuideStep
{
	private final int fromLevel;
	private final int toLevel;
	private final TrainingMethod method;

	GuideStep(int fromLevel, int toLevel, TrainingMethod method)
	{
		this.fromLevel = fromLevel;
		this.toLevel = toLevel;
		this.method = method;
	}

	public int getFromLevel()
	{
		return fromLevel;
	}

	public int getToLevel()
	{
		return toLevel;
	}

	public TrainingMethod getMethod()
	{
		return method;
	}

	public int getExperienceRequired()
	{
		return Experience.getXpForLevel(toLevel) - Experience.getXpForLevel(fromLevel);
	}

	public Double getMinimumHours()
	{
		Integer high = method.getXpPerHourHigh();
		return high == null || high <= 0 ? null : (double) getExperienceRequired() / high;
	}

	public Double getMaximumHours()
	{
		Integer low = method.getXpPerHourLow();
		return low == null || low <= 0 ? null : (double) getExperienceRequired() / low;
	}
}

package com.efficientskilling;

import java.awt.Dimension;
import javax.swing.JComponent;

/** Shared width and intrinsic-height contract for cards on the companion Settings page. */
final class SettingsPanelLayout
{
	static final int MAX_WIDTH = 960;

	private SettingsPanelLayout() { }

	static void bind(JComponent panel)
	{
		panel.putClientProperty("pathToMax.maxWidth", MAX_WIDTH);
		panel.putClientProperty("pathToMax.intrinsicHeight", Boolean.TRUE);
		refresh(panel);
	}

	static void refresh(JComponent panel)
	{
		Dimension preferred = panel.getPreferredSize();
		panel.setMaximumSize(new Dimension(MAX_WIDTH, preferred.height));
		panel.revalidate();
	}
}

package com.efficientskilling;

import net.runelite.api.Skill;
import net.runelite.api.Quest;

/** A validated, machine-readable prerequisite used by detail state and Timeline ordering. */
public final class MethodDependency
{
	private MethodDependencyType type;
	private String label;
	private String skill;
	private Integer level;
	private String id;
	private String quest;
	private String item;
	private Integer quantity;
	private Boolean mandatory;

	public MethodDependencyType getType() { return type; }
	public String getLabel() { return label; }
	public Skill getSkill() { return skill == null ? null : Skill.valueOf(skill); }
	public Integer getLevel() { return level; }
	public String getId() { return id; }
	public Quest getQuest() { return quest == null ? null : Quest.valueOf(quest); }
	public RequirementItem getItem() { return item == null ? null : RequirementItem.valueOf(item); }
	public int getQuantity() { return quantity == null ? 1 : quantity; }
	public boolean isMandatory() { return mandatory == null || mandatory; }
}

