package com.efficientskilling;

public enum GuideStrategy
{
	FASTEST("Fastest"),
	BALANCED("Balanced"),
	LOWEST_COST("Lowest cost"),
	AFK("AFK");

	private final String displayName;

	GuideStrategy(String displayName)
	{
		this.displayName = displayName;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.efficientskilling;

public enum AccountProfile
{
	MAIN("Main"),
	IRONMAN("Ironman"),
	HARDCORE_IRONMAN("Hardcore Ironman"),
	ULTIMATE_IRONMAN("Ultimate Ironman"),
	GROUP_IRONMAN("Group Ironman"),
	HARDCORE_GROUP_IRONMAN("Hardcore Group Ironman");
	private static final int NORMAL_TYPE = 0;
	private static final int IRONMAN_TYPE = 1;
	private static final int ULTIMATE_IRONMAN_TYPE = 2;
	private static final int HARDCORE_IRONMAN_TYPE = 3;
	private static final int GROUP_IRONMAN_TYPE = 4;
	private static final int HARDCORE_GROUP_IRONMAN_TYPE = 5;
	private static final int UNRANKED_GROUP_IRONMAN_TYPE = 6;

	private final String displayName;

	AccountProfile(String displayName)
	{
		this.displayName = displayName;
	}

	public static AccountProfile fromVarbit(int accountType)
	{
		switch (accountType)
		{
			case IRONMAN_TYPE:
				return IRONMAN;
			case ULTIMATE_IRONMAN_TYPE:
				return ULTIMATE_IRONMAN;
			case HARDCORE_IRONMAN_TYPE:
				return HARDCORE_IRONMAN;
			case GROUP_IRONMAN_TYPE:
			case UNRANKED_GROUP_IRONMAN_TYPE:
				return GROUP_IRONMAN;
			case HARDCORE_GROUP_IRONMAN_TYPE:
				return HARDCORE_GROUP_IRONMAN;
			case NORMAL_TYPE:
				return MAIN;
			default:
				return null;
		}
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

