public class EfficientSkillingPanel extends PluginPanel
{
	private static final int PAGE_MODE = 0;
	private static final int PAGE_ACCOUNT = 1;
	private static final int PAGE_SKILL = 2;
	private static final int PAGE_APPROACH = 3;
	private static final int PAGE_GOAL = 4;
	private static final int PAGE_PLAN = 5;
	private static final int TEXT_WIDTH = 174;
	private static final int CHOICE_TEXT_WIDTH = 132;
	private static final int ROUTE_TEXT_WIDTH = 148;
	private static final Color ACCENT = new Color(255, 152, 31);
	private static final Color SELECTED = new Color(72, 61, 48);
	private static final Color MUTED = new Color(178, 178, 178);
	private static final Color ERROR = new Color(255, 115, 115);
	private static final String[] PAGE_TITLES =
		{"Choose planner", "Account", "Skill", "Approach", "Goal", "Plan"};

	private final GuideService guideService;
	private final SkillIconManager skillIconManager;
	private final Runnable openPathToMax;
	private final int targetOffset;
	private final Map<Skill, Integer> liveLevels = new EnumMap<>(Skill.class);
	private final Map<AccountProfile, JToggleButton> accountButtons =
		new EnumMap<>(AccountProfile.class);
	private final Map<Skill, JToggleButton> skillButtons = new EnumMap<>(Skill.class);
	private final Map<GuideStrategy, JToggleButton> approachButtons =
		new EnumMap<>(GuideStrategy.class);
	private final CardLayout pageLayout = new CardLayout();
	private final JPanel pages = new JPanel(pageLayout);
	private final JButton backButton = new JButton("<");
	private final JLabel pageTitle = new JLabel();
	private final JLabel progress = new JLabel();
	private final JLabel accountDetection = new JLabel();
	private final JButton useDetectedAccount = new JButton("Use detected account");
	private final JTextField currentLevel = levelField();
	private final JTextField targetLevel = levelField();
	private final JLabel goalIcon = new JLabel();
	private final JLabel goalSkill = new JLabel();
	private final JLabel goalMeta = new JLabel();
	private final JLabel liveHint = new JLabel();
	private final JLabel goalError = new JLabel(" ");
	private final JLabel planIcon = new JLabel();
	private final JLabel planSkill = new JLabel();
	private final JLabel planMeta = new JLabel();
	private final JLabel planLevels = new JLabel();
	private final JLabel planTime = new JLabel();
	private final JPanel guideContainer = verticalPanel();

	private AccountProfile detectedAccount;
	private AccountProfile selectedAccount;
	private Skill selectedSkill;
	private GuideStrategy selectedApproach;
	private int currentPage;
	private boolean currentLevelEdited;
	private boolean updatingLevels;
	private boolean choosingMaxPlan;

	EfficientSkillingPanel(GuideService guideService, EfficientSkillingConfig config)
	{
		this(guideService, config, null);
	}

	EfficientSkillingPanel(GuideService guideService, EfficientSkillingConfig config,
		SkillIconManager skillIconManager)
	{
		this(guideService, config, skillIconManager, () -> { });
	}

	EfficientSkillingPanel(GuideService guideService, EfficientSkillingConfig config,
		SkillIconManager skillIconManager, Runnable openPathToMax)
	{
		super(false);
		this.guideService = guideService;
		this.skillIconManager = skillIconManager;
		this.openPathToMax = openPathToMax;
		targetOffset = Math.max(1, config.targetLevelOffset());

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setBorder(BorderFactory.createEmptyBorder());
		add(buildHeader(), BorderLayout.NORTH);

		pages.setBackground(ColorScheme.DARK_GRAY_COLOR);
		pages.add(scrollPage(buildModePage()), pageName(PAGE_MODE));
		pages.add(scrollPage(buildAccountPage()), pageName(PAGE_ACCOUNT));
		pages.add(scrollPage(buildSkillPage()), pageName(PAGE_SKILL));
		pages.add(scrollPage(buildApproachPage()), pageName(PAGE_APPROACH));
		pages.add(scrollPage(buildGoalPage()), pageName(PAGE_GOAL));
		pages.add(scrollPage(buildPlanPage()), pageName(PAGE_PLAN));
		add(pages, BorderLayout.CENTER);

		installLevelListeners();
		showPage(PAGE_MODE);
	}

	private JPanel buildHeader()
	{
		JPanel header = new JPanel(new BorderLayout(8, 0));
		header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		header.setBorder(BorderFactory.createEmptyBorder(9, 8, 9, 8));

		backButton.setFont(backButton.getFont().deriveFont(Font.BOLD, 22f));
		backButton.setUI(new BasicButtonUI());
		backButton.setForeground(ACCENT);
		backButton.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		backButton.setBorder(BorderFactory.createEmptyBorder(0, 5, 2, 8));
		backButton.setContentAreaFilled(false);
		backButton.setFocusPainted(false);
		backButton.setPreferredSize(new Dimension(28, 34));
		backButton.setToolTipText("Previous page");
		backButton.addActionListener(event ->
		{
			if (choosingMaxPlan && currentPage == PAGE_APPROACH)
			{
				showPage(PAGE_ACCOUNT);
			}
			else
			{
				showPage(Math.max(PAGE_MODE, currentPage - 1));
			}
		});
		header.add(backButton, BorderLayout.WEST);

		JPanel labels = verticalPanel();
		pageTitle.setForeground(Color.WHITE);
		pageTitle.setFont(pageTitle.getFont().deriveFont(Font.BOLD, 15f));
		pageTitle.setPreferredSize(new Dimension(120, 20));
		pageTitle.setMaximumSize(new Dimension(120, 20));
		progress.setForeground(MUTED);
		progress.setFont(progress.getFont().deriveFont(11f));
		labels.add(pageTitle);
		labels.add(progress);
		header.add(labels, BorderLayout.CENTER);

		return header;
	}

	private JPanel buildModePage()
	{
		JPanel page = pageBody("What are you planning?",
			"Choose a focused skill route or a whole-account path to max.");
		JToggleButton efficient = choiceCard(approachIcon(GuideStrategy.BALANCED),
			"Single Skill Plan", "Plan one skill from its current level to your chosen goal.");
		efficient.addActionListener(event -> chooseEfficientSkillingMode());
		page.add(efficient);
		page.add(Box.createVerticalStrut(10));
		JToggleButton max = choiceCard(new LineIcon(LineIcon.ROUTE),
			"Path to Max", "Build a whole-account plan, then continue in a separate resizable companion window.");
		max.addActionListener(event -> choosePathToMaxMode());
		page.add(max);
		return page;
	}

	private JPanel buildAccountPage()
	{
		JPanel page = pageBody("Choose your account",
			"Routes change when supplies, trading, storage, or status risk change.");
		accountDetection.setForeground(MUTED);
		accountDetection.setFont(accountDetection.getFont().deriveFont(Font.BOLD, 11f));
		accountDetection.setAlignmentX(Component.LEFT_ALIGNMENT);
		page.add(accountDetection);
		page.add(Box.createVerticalStrut(6));
		useDetectedAccount.setAlignmentX(Component.LEFT_ALIGNMENT);
		useDetectedAccount.setEnabled(false);
		useDetectedAccount.setToolTipText("Select the account type detected from the logged-in character");
		useDetectedAccount.getAccessibleContext().setAccessibleName("Use detected account type");
		useDetectedAccount.addActionListener(event ->
		{
			if (detectedAccount != null) chooseAccount(detectedAccount);
		});
		page.add(useDetectedAccount);
		page.add(Box.createVerticalStrut(10));
		updateDetectedAccountLabels();
		ButtonGroup group = new ButtonGroup();
		for (AccountProfile profile : AccountProfile.values())
		{
			JToggleButton button = choiceCard(accountIcon(profile), profile.toString(),
				accountDescription(profile));
			button.addActionListener(event -> chooseAccount(profile));
			accountButtons.put(profile, button);
			group.add(button);
			page.add(button);
			page.add(Box.createVerticalStrut(7));
		}
		return page;
	}

	private JPanel buildSkillPage()
	{
		JPanel page = pageBody("Choose a skill",
			"Tap an icon to use its live level and continue.");
		JPanel grid = new JPanel(new GridLayout(0, 4, 7, 7));
		grid.setOpaque(false);
		grid.setAlignmentX(Component.LEFT_ALIGNMENT);
		grid.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));
		ButtonGroup group = new ButtonGroup();
		for (Skill skill : Skill.values())
		{
			if (!guideService.hasData(skill))
			{
				continue;
			}
			JToggleButton button = skillButton(skill);
			button.addActionListener(event -> chooseSkill(skill));
			skillButtons.put(skill, button);
			group.add(button);
			grid.add(button);
		}
		page.add(grid);
		return page;
	}

	private JPanel buildApproachPage()
	{
		JPanel page = pageBody("Choose an approach",
			"Tap the trade-off you want this plan to optimise.");
		ButtonGroup group = new ButtonGroup();
		for (GuideStrategy approach : GuideStrategy.values())
		{
			JToggleButton button = choiceCard(approachIcon(approach), approachTitle(approach),
				approachDescription(approach));
			button.addActionListener(event -> chooseApproach(approach));
			approachButtons.put(approach, button);
			group.add(button);
			page.add(button);
			page.add(Box.createVerticalStrut(8));
		}
		return page;
	}

	private JPanel buildGoalPage()
	{
		JPanel page = pageBody("Set the level range",
			"Your current level is detected automatically. Type either value to plan something else.");

		page.add(buildGoalIdentity());
		page.add(Box.createVerticalStrut(14));

		JPanel inputs = new JPanel(new GridLayout(1, 2, 9, 0));
		inputs.setOpaque(false);
		inputs.setAlignmentX(Component.LEFT_ALIGNMENT);
		inputs.setMaximumSize(new Dimension(Integer.MAX_VALUE, 102));
		inputs.add(levelCard("CURRENT", currentLevel));
		inputs.add(levelCard("TARGET", targetLevel));
		page.add(inputs);

		liveHint.setForeground(ACCENT);
		liveHint.setFont(liveHint.getFont().deriveFont(11f));
		liveHint.setAlignmentX(Component.LEFT_ALIGNMENT);
		liveHint.setCursor(new java.awt.Cursor(java.awt.Cursor.HAND_CURSOR));
		liveHint.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent event)
			{
				resetToLiveLevel();
			}
		});
		page.add(Box.createVerticalStrut(8));
		page.add(liveHint);

		goalError.setForeground(ERROR);
		goalError.setAlignmentX(Component.LEFT_ALIGNMENT);
		page.add(Box.createVerticalStrut(7));
		page.add(goalError);
		page.add(Box.createVerticalStrut(12));

		JButton build = new PrimaryButton("Create training plan");
		build.setFont(build.getFont().deriveFont(Font.BOLD, 13f));
		build.setForeground(new Color(32, 27, 20));
		build.setAlignmentX(Component.LEFT_ALIGNMENT);
		build.setMaximumSize(new Dimension(Integer.MAX_VALUE, 40));
		build.setPreferredSize(new Dimension(190, 40));
		build.addActionListener(event -> buildPlan());
		page.add(build);
		page.add(Box.createVerticalStrut(12));
		page.add(wrapped("You can use the back arrow at any time to change the skill, account, or approach."));
		return page;
	}

	private JPanel buildGoalIdentity()
	{
		JPanel hero = fullWidthCard();
		JPanel row = new JPanel(new BorderLayout(10, 0));
		row.setOpaque(false);
		goalIcon.setHorizontalAlignment(SwingConstants.CENTER);
		goalIcon.setPreferredSize(new Dimension(38, 38));
		row.add(goalIcon, BorderLayout.WEST);

		JPanel text = verticalPanel();
		goalSkill.setForeground(Color.WHITE);
		goalSkill.setFont(goalSkill.getFont().deriveFont(Font.BOLD, 16f));
		goalMeta.setForeground(MUTED);
		text.add(goalSkill);
		text.add(Box.createVerticalStrut(2));
		text.add(goalMeta);
		row.add(text, BorderLayout.CENTER);
		hero.add(row);
		return hero;
	}

	private JPanel levelCard(String label, JTextField field)
	{
		JPanel card = fullWidthCard();
		JLabel caption = new JLabel(label);
		caption.setForeground(MUTED);
		caption.setFont(caption.getFont().deriveFont(Font.BOLD, 10f));
		caption.setAlignmentX(Component.LEFT_ALIGNMENT);
		field.setAlignmentX(Component.LEFT_ALIGNMENT);
		field.setMaximumSize(new Dimension(Integer.MAX_VALUE, 48));
		card.add(caption);
		card.add(Box.createVerticalStrut(5));
		card.add(field);
		return card;
	}

	private JPanel buildPlanPage()
	{
		JPanel page = pageBody("Your training plan",
			"Follow the methods in order. Use the back arrow to adjust the goal.");
		page.add(buildPlanHero());
		page.add(Box.createVerticalStrut(12));
		guideContainer.add(wrapped("Create a goal to see its training plan."));
		page.add(guideContainer);
		return page;
	}

	private JPanel buildPlanHero()
	{
		JPanel hero = fullWidthCard();
		hero.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 3, 0, 0, ACCENT),
			BorderFactory.createEmptyBorder(12, 12, 12, 12)));

		JPanel top = new JPanel(new BorderLayout(10, 0));
		top.setOpaque(false);
		planIcon.setPreferredSize(new Dimension(38, 38));
		planIcon.setHorizontalAlignment(SwingConstants.CENTER);
		top.add(planIcon, BorderLayout.WEST);
		JPanel identity = verticalPanel();
		planSkill.setForeground(Color.WHITE);
		planSkill.setFont(planSkill.getFont().deriveFont(Font.BOLD, 16f));
		planMeta.setForeground(MUTED);
		identity.add(planSkill);
		identity.add(Box.createVerticalStrut(2));
		identity.add(planMeta);
		top.add(identity, BorderLayout.CENTER);
		hero.add(top);
		hero.add(Box.createVerticalStrut(12));

		JPanel summary = verticalPanel();
		summary.setAlignmentX(Component.CENTER_ALIGNMENT);
		summary.setMaximumSize(new Dimension(Integer.MAX_VALUE, 84));

		planLevels.setForeground(Color.WHITE);
		planLevels.setFont(planLevels.getFont().deriveFont(Font.BOLD, 24f));
		planLevels.setHorizontalAlignment(SwingConstants.CENTER);
		JPanel levelsRow = new JPanel(new BorderLayout());
		levelsRow.setOpaque(false);
		levelsRow.setAlignmentX(Component.CENTER_ALIGNMENT);
		levelsRow.setPreferredSize(new Dimension(TEXT_WIDTH, 32));
		levelsRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 32));
		levelsRow.add(planLevels, BorderLayout.CENTER);
		summary.add(levelsRow);
		planTime.setForeground(MUTED);
		planTime.setHorizontalAlignment(SwingConstants.LEFT);
		planTime.setAlignmentX(Component.LEFT_ALIGNMENT);
		summary.add(Box.createVerticalStrut(3));
		JPanel timeRow = new JPanel(new BorderLayout());
		timeRow.setOpaque(false);
		timeRow.setAlignmentX(Component.CENTER_ALIGNMENT);
		timeRow.setPreferredSize(new Dimension(TEXT_WIDTH, 48));
		timeRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 48));
		timeRow.add(planTime, BorderLayout.WEST);
		summary.add(timeRow);
		hero.add(summary);
		return hero;
	}

	private JPanel pageBody(String heading, String description)
	{
		JPanel page = new ScrollablePage();
		page.setBorder(BorderFactory.createEmptyBorder(13, 8, 18, 8));
		page.setBackground(ColorScheme.DARK_GRAY_COLOR);
		JLabel title = wrapped(heading);
		title.setForeground(Color.WHITE);
		title.setFont(title.getFont().deriveFont(Font.BOLD, 17f));
		page.add(title);
		page.add(Box.createVerticalStrut(4));
		page.add(wrapped(description));
		page.add(Box.createVerticalStrut(14));
		return page;
	}

	private JScrollPane scrollPage(JPanel page)
	{
		JScrollPane scroll = new JScrollPane(page);
		scroll.setBorder(null);
		scroll.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setVerticalScrollBarPolicy(JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED);
		scroll.setWheelScrollingEnabled(true);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		scroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
		return scroll;
	}

	private JToggleButton choiceCard(Icon icon, String title, String description)
	{
		JToggleButton button = new ChoiceButton(choiceHtml(title, description), icon);
		button.setHorizontalAlignment(SwingConstants.LEFT);
		button.setIconTextGap(11);
		button.setForeground(Color.LIGHT_GRAY);
		button.setAlignmentX(Component.LEFT_ALIGNMENT);
		button.setMaximumSize(new Dimension(Integer.MAX_VALUE, 110));
		return button;
	}

	private JToggleButton skillButton(Skill skill)
	{
		ImageIcon icon = skillIcon(skill, 27);
		JToggleButton button = new ChoiceButton(icon == null ? skill.getName() : "", icon);
		button.putClientProperty("compactSkill", Boolean.TRUE);
		button.setHorizontalAlignment(SwingConstants.CENTER);
		button.setForeground(Color.LIGHT_GRAY);
		button.setPreferredSize(new Dimension(42, 48));
		button.setToolTipText(skill.getName());
		return button;
	}

	private JPanel fullWidthCard()
	{
		JPanel card = new RoundedPanel();
		card.setBorder(BorderFactory.createEmptyBorder(11, 11, 11, 11));
		card.setAlignmentX(Component.LEFT_ALIGNMENT);
		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, card.getPreferredSize().height));
		return card;
	}

	private void installLevelListeners()
	{
		currentLevel.setText("1");
		targetLevel.setText(String.valueOf(Math.min(99, 1 + targetOffset)));
		currentLevel.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent event)
			{
				markCurrentEdited();
			}

			@Override
			public void removeUpdate(DocumentEvent event)
			{
				markCurrentEdited();
			}

			@Override
			public void changedUpdate(DocumentEvent event)
			{
				markCurrentEdited();
			}
		});
	}

