	public void setDetectedAccount(AccountProfile account)
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(() -> setDetectedAccount(account));
			return;
		}
		detectedAccount = account;
		updateDetectedAccountLabels();
	}

	private void updateDetectedAccountLabels()
	{
		accountDetection.setText(detectedAccount == null
			? "Detected account: Undetected"
			: "Detected account: " + detectedAccount);
		useDetectedAccount.setEnabled(detectedAccount != null);
		for (Map.Entry<AccountProfile, JToggleButton> entry : accountButtons.entrySet())
		{
			String title = entry.getKey().toString();
			if (entry.getKey() == detectedAccount)
			{
				title += "  |  Detected";
			}
			entry.getValue().setText(choiceHtml(title, accountDescription(entry.getKey())));
		}
	}

	public void setLiveLevel(Skill skill, int level)
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(() -> setLiveLevel(skill, level));
			return;
		}
		liveLevels.put(skill, clampLevel(level));
		if (skill == selectedSkill && !currentLevelEdited)
		{
			updatingLevels = true;
			try
			{
				setLevel(currentLevel, level);
			}
			finally
			{
				updatingLevels = false;
			}
			updateLiveHint();
		}
	}

	void resetToLiveLevel()
	{
		if (selectedSkill == null)
		{
			return;
		}
		int level = liveLevels.getOrDefault(selectedSkill, 1);
		updatingLevels = true;
		try
		{
			setLevel(currentLevel, level);
			setLevel(targetLevel, level >= 99 ? 99 : Math.min(99, level + targetOffset));
		}
		finally
		{
			updatingLevels = false;
		}
		currentLevelEdited = false;
		goalError.setText(" ");
		updateLiveHint();
	}

	private void updateLiveHint()
	{
		int live = selectedSkill == null ? 1 : liveLevels.getOrDefault(selectedSkill, 1);
		liveHint.setText("Reset current level to live level " + live);
	}

	private void updateGoalIdentity()
	{
		if (selectedSkill == null || selectedAccount == null || selectedApproach == null)
		{
			return;
		}
		goalIcon.setIcon(skillIcon(selectedSkill, 34));
		goalSkill.setText(selectedSkill.getName());
		goalMeta.setText(selectedAccount + "  |  " + approachTitle(selectedApproach));
		updateLiveHint();
		invalidateLayoutToPages(goalSkill);
	}

	private void normalizeLevelFields()
	{
		setLevel(currentLevel, parseLevel(currentLevel, 1));
		setLevel(targetLevel, parseLevel(targetLevel, Math.min(99, getCurrentLevel() + targetOffset)));
	}

	private void buildPlan()
	{
		normalizeLevelFields();
		int current = getCurrentLevel();
		int target = getTargetLevel();
		if (target <= current)
		{
			goalError.setText("Target level must be higher than current level.");
			return;
		}
		goalError.setText(" ");

		Guide guide = guideService.buildGuide(selectedSkill, current, target,
			selectedAccount, selectedApproach);
		updatePlanHero(guide, current, target);
		renderGuideSteps(guide, current, target);
		showPage(PAGE_PLAN);
	}

	private void updatePlanHero(Guide guide, int current, int target)
	{
		planIcon.setIcon(skillIcon(selectedSkill, 34));
		planSkill.setText(selectedSkill.getName());
		planMeta.setText(selectedAccount + "  |  " + approachTitle(selectedApproach));
		planLevels.setText(current + "  to  " + target);
		if (guide.getMinimumHours() != null && guide.getMaximumHours() != null)
		{
			setWrappedText(planTime, "Estimated "
				+ formatHours(guide.getMinimumHours(), guide.getMaximumHours()), ROUTE_TEXT_WIDTH);
		}
		else
		{
			setWrappedText(planTime, "Time varies by method, gear, and execution",
				ROUTE_TEXT_WIDTH);
		}
		invalidateLayoutToPages(planSkill);
	}

	private void renderGuideSteps(Guide guide, int current, int target)
	{
		guideContainer.removeAll();
		if (guide.getSteps().isEmpty())
		{
			guideContainer.add(wrapped(current >= target
				? "You are already at this target. Go back and choose a higher level."
				: "No route is available for these settings."));
		}
		else
		{
			for (int index = 0; index < guide.getSteps().size(); index++)
			{
				guideContainer.add(stepCard(guide.getSteps().get(index), index + 1));
				guideContainer.add(Box.createVerticalStrut(10));
			}
			if (!guide.isComplete())
			{
				guideContainer.add(wrapped("Catalogue gap begins at level "
					+ guide.getUncoveredLevel() + "."));
			}
			addAlternativeCards(guide);
		}
		guideContainer.revalidate();
		guideContainer.repaint();
		invalidateLayoutToPages(guideContainer);
	}

	private JPanel stepCard(GuideStep step, int number)
	{
		TrainingMethod method = step.getMethod();
		JPanel card = fullWidthCard();
		card.putClientProperty("routeStep", number);
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 2, 0, 0, ACCENT),
			BorderFactory.createEmptyBorder(11, 11, 11, 11)));

		JLabel eyebrow = new JLabel("STEP " + number + "  |  "
			+ step.getFromLevel() + " to " + step.getToLevel());
		eyebrow.setForeground(ACCENT);
		eyebrow.setFont(eyebrow.getFont().deriveFont(Font.BOLD, 14f));
		eyebrow.setAlignmentX(Component.LEFT_ALIGNMENT);
		card.add(eyebrow);
		card.add(Box.createVerticalStrut(8));

		JLabel heading = wrapped(method.getName(), ROUTE_TEXT_WIDTH);
		heading.setForeground(Color.WHITE);
		heading.setFont(heading.getFont().deriveFont(Font.BOLD, 14f));
		card.add(heading);
		card.add(Box.createVerticalStrut(5));
		card.add(wrapped(method.getDescription(), ROUTE_TEXT_WIDTH));
		addDetail(card, "Rate", method.getXpRate());
		if (step.getMinimumHours() != null && step.getMaximumHours() != null)
		{
			addDetail(card, "Time", formatHours(step.getMinimumHours(), step.getMaximumHours()));
		}
		addDetail(card, "Cost", method.getCost());
		addDetail(card, "Effort", method.getIntensity());
		addDetail(card, "Risk", method.getRisk());
		if (!method.getRequirements().isEmpty())
		{
			addDetail(card, "Needs", String.join(", ", method.getRequirements()));
		}

		card.add(Box.createVerticalStrut(6));
		card.add(sourceButton("Open source", method.getSource()));
		return card;
	}

	private void addAlternativeCards(Guide guide)
	{
		Map<String, AlternativeRoute> alternatives = new LinkedHashMap<>();
		for (GuideStep step : guide.getSteps())
		{
			for (TrainingAlternative alternative : step.getMethod().getAlternatives())
			{
				AlternativeRoute existing = alternatives.get(alternative.getName());
				if (existing == null)
				{
					alternatives.put(alternative.getName(), new AlternativeRoute(
						alternative, step.getFromLevel(), step.getToLevel()));
				}
				else
				{
					existing.include(step);
				}
			}
		}

		for (AlternativeRoute alternative : alternatives.values())
		{
			guideContainer.add(alternativeCard(alternative));
			guideContainer.add(Box.createVerticalStrut(10));
		}
	}

	private JPanel alternativeCard(AlternativeRoute route)
	{
		TrainingAlternative alternative = route.alternative;
		JPanel card = fullWidthCard();
		card.putClientProperty("trainingAlternative", alternative.getName());
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 2, 0, 0, ACCENT),
			BorderFactory.createEmptyBorder(11, 11, 11, 11)));

		JLabel eyebrow = new JLabel("ALSO CONSIDER");
		eyebrow.setForeground(ACCENT);
		eyebrow.setFont(eyebrow.getFont().deriveFont(Font.BOLD, 14f));
		eyebrow.setAlignmentX(Component.LEFT_ALIGNMENT);
		card.add(eyebrow);
		card.add(Box.createVerticalStrut(2));
		JLabel levels = new JLabel("Levels " + route.fromLevel + " to " + route.toLevel);
		levels.setForeground(MUTED);
		levels.setFont(levels.getFont().deriveFont(Font.BOLD, 11f));
		levels.setAlignmentX(Component.LEFT_ALIGNMENT);
		card.add(levels);
		card.add(Box.createVerticalStrut(8));

		JLabel heading = wrapped(alternative.getName(), ROUTE_TEXT_WIDTH);
		heading.setForeground(Color.WHITE);
		heading.setFont(heading.getFont().deriveFont(Font.BOLD, 14f));
		card.add(heading);
		card.add(Box.createVerticalStrut(5));
		card.add(wrapped("Optional route context; this does not change the plan's time estimate.",
			ROUTE_TEXT_WIDTH));
		addAlternativeFacts(card, "Needs", alternative.getRequirements());
		addAlternativeFacts(card, "Benefits", alternative.getBenefits());
		addAlternativeFacts(card, "Keep in mind", alternative.getConsiderations());
