	private void addAlternativeFacts(JPanel details, String label,
		List<SourcedFact> facts)
	{
		if (facts.isEmpty())
		{
			return;
		}
		details.add(Box.createVerticalStrut(10));
		JLabel heading = new JLabel(label.toUpperCase(Locale.ROOT));
		heading.setForeground(ACCENT);
		heading.setFont(heading.getFont().deriveFont(Font.BOLD, 11f));
		heading.setAlignmentX(Component.LEFT_ALIGNMENT);
		details.add(heading);
		for (SourcedFact fact : facts)
		{
			details.add(Box.createVerticalStrut(4));
			details.add(wrapped("- " + fact.getText(), ROUTE_TEXT_WIDTH));
			details.add(sourceButton("Open fact source", fact.getSource()));
		}
	}

	private static JButton sourceButton(String label, String url)
	{
		JButton source = new JButton(label);
		source.setForeground(ACCENT);
		source.setFont(source.getFont().deriveFont(Font.BOLD));
		source.setBorder(BorderFactory.createEmptyBorder(5, 0, 0, 0));
		source.setContentAreaFilled(false);
		source.setFocusPainted(false);
		source.setCursor(new java.awt.Cursor(java.awt.Cursor.HAND_CURSOR));
		source.setToolTipText(url);
