		card.add(wrapped(value, ROUTE_TEXT_WIDTH));
	}

	private void invalidateLayoutToPages(Component component)
	{
		Component current = component;
		while (current != null && current != pages)
		{
			current.invalidate();
			current = current.getParent();
		}
		pages.revalidate();
		pages.repaint();
	}

	private void showPage(int page)
	{
		currentPage = Math.max(PAGE_MODE, Math.min(PAGE_PLAN, page));
		pageLayout.show(pages, pageName(currentPage));
		pageTitle.setText(PAGE_TITLES[currentPage]);
		if (currentPage == PAGE_MODE)
		{
			progress.setText("Choose an experience");
		}
		else if (currentPage == PAGE_PLAN)
		{
			progress.setText("Plan ready");
		}
		else if (choosingMaxPlan)
		{
			progress.setText("Step " + (currentPage == PAGE_ACCOUNT ? 1 : 2) + " of 2");
		}
		else
		{
			progress.setText("Step " + currentPage + " of 4");
		}
		backButton.setVisible(currentPage > PAGE_MODE);
		revalidate();
		repaint();
	}

