	private static String escapeHtml(String value)
	{
		return value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	private static int parseLevel(JTextField field, int fallback)
	{
		String value = field.getText().trim();
		if (value.isEmpty())
		{
			return clampLevel(fallback);
		}
		try
		{
			return clampLevel(Integer.parseInt(value));
		}
		catch (NumberFormatException ex)
		{
			return clampLevel(fallback);
		}
	}

	private static int clampLevel(int level)
	{
		return Math.max(1, Math.min(99, level));
	}

	private static void setLevel(JTextField field, int level)
	{
		field.setText(String.valueOf(clampLevel(level)));
	}

	private int getCurrentLevel()
	{
		return parseLevel(currentLevel, 1);
	}

	private int getTargetLevel()
	{
		return parseLevel(targetLevel, Math.min(99, getCurrentLevel() + targetOffset));
	}

	private static String formatHours(double minimum, double maximum)
	{
		if (Math.abs(maximum - minimum) < 0.05)
		{
			return String.format(Locale.US, "%.1f hours", minimum);
		}
		return String.format(Locale.US, "%.1f-%.1f hours", minimum, maximum);
	}

