	boolean hasHorizontalScrollBars()
	{
		for (Component component : pages.getComponents())
		{
			if (component instanceof JScrollPane
				&& ((JScrollPane) component).getHorizontalScrollBarPolicy()
				!= JScrollPane.HORIZONTAL_SCROLLBAR_NEVER)
			{
				return true;
			}
		}
		return false;
	}

	private static final class AlternativeRoute
	{
		private final TrainingAlternative alternative;
		private int fromLevel;
		private int toLevel;

		private AlternativeRoute(TrainingAlternative alternative, int fromLevel, int toLevel)
		{
			this.alternative = alternative;
			this.fromLevel = fromLevel;
			this.toLevel = toLevel;
		}

		private void include(GuideStep step)
		{
			fromLevel = Math.min(fromLevel, step.getFromLevel());
			toLevel = Math.max(toLevel, step.getToLevel());
		}
	}

	private static class NaturalHeightPanel extends JPanel
	{
		private NaturalHeightPanel()
		{
			setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
			setOpaque(false);
			setAlignmentX(Component.LEFT_ALIGNMENT);
		}

		@Override
		public Dimension getMaximumSize()
		{
			return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
		}
	}

	private static final class RoundedPanel extends NaturalHeightPanel
	{
		@Override
		protected void paintComponent(Graphics graphics)
		{
			Graphics2D copy = (Graphics2D) graphics.create();
			copy.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
				RenderingHints.VALUE_ANTIALIAS_ON);
			copy.setColor(ColorScheme.DARKER_GRAY_COLOR);
			copy.fillRoundRect(0, 0, getWidth() - 1, getHeight() - 1, 10, 10);
			copy.setColor(ColorScheme.MEDIUM_GRAY_COLOR);
			copy.drawRoundRect(0, 0, getWidth() - 1, getHeight() - 1, 10, 10);
			copy.dispose();
			super.paintComponent(graphics);
		}
	}

	private static class ChoiceButton extends JToggleButton
	{
		private ChoiceButton(String text, Icon icon)
		{
			super(text, icon);
			setUI(new BasicButtonUI());
			setBorder(BorderFactory.createEmptyBorder(9, 9, 9, 9));
			setContentAreaFilled(false);
			setFocusPainted(false);
			setOpaque(false);
			setRolloverEnabled(true);
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			Graphics2D copy = (Graphics2D) graphics.create();
			copy.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
				RenderingHints.VALUE_ANTIALIAS_ON);
			Color fill = isSelected() ? SELECTED
				: getModel().isRollover() ? new Color(54, 54, 54)
				: ColorScheme.DARKER_GRAY_COLOR;
			copy.setColor(fill);
			copy.fillRoundRect(0, 0, getWidth() - 1, getHeight() - 1, 10, 10);
