	private static final class RoundedBorder extends AbstractBorder
	{
		private final Color color;
		private final int radius;
		private final Insets insets;

		private RoundedBorder(Color color, int radius, Insets insets)
		{
			this.color = color;
			this.radius = radius;
			this.insets = insets;
		}

		@Override
		public void paintBorder(Component component, Graphics graphics, int x, int y,
			int width, int height)
		{
			Graphics2D copy = (Graphics2D) graphics.create();
			copy.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
				RenderingHints.VALUE_ANTIALIAS_ON);
			copy.setColor(color);
			copy.drawRoundRect(x, y, width - 1, height - 1, radius, radius);
			copy.dispose();
		}

		@Override
		public Insets getBorderInsets(Component component)
		{
			return new Insets(insets.top, insets.left, insets.bottom, insets.right);
		}
	}

	private static final class LineIcon implements Icon
	{
		private static final int PERSON = 0;
		private static final int SHIELD = 1;
		private static final int HEART = 2;
		private static final int BACKPACK = 3;
		private static final int GROUP = 4;
		private static final int GROUP_SHIELD = 5;
		private static final int LIGHTNING = 6;
		private static final int BALANCE = 7;
		private static final int COIN = 8;
		private static final int MOON = 9;
		private static final int ROUTE = 10;
		private final int type;

		private LineIcon(int type)
		{
			this.type = type;
		}

		@Override
		public int getIconWidth()
		{
			return 24;
		}

		@Override
		public int getIconHeight()
		{
			return 24;
		}

		@Override
		public void paintIcon(Component component, Graphics graphics, int x, int y)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			g.translate(x, y);
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
				RenderingHints.VALUE_ANTIALIAS_ON);
			g.setColor(ACCENT);
			if (type == LIGHTNING)
			{
				g.fill(new Polygon(new int[]{13, 6, 11, 8, 18, 13},
					new int[]{1, 13, 13, 23, 10, 10}, 6));
			}
			else if (type == COIN)
			{
				g.drawOval(3, 3, 18, 18);
				g.drawString("gp", 6, 16);
			}
			else if (type == MOON)
			{
				g.fillOval(3, 2, 18, 19);
				g.setColor(ColorScheme.DARKER_GRAY_COLOR);
				g.fillOval(9, 0, 16, 17);
			}
			else if (type == ROUTE)
			{
				g.fillOval(3, 16, 5, 5);
				g.fillOval(10, 9, 5, 5);
				g.fillOval(17, 2, 5, 5);
				g.drawLine(7, 17, 11, 13);
				g.drawLine(14, 10, 18, 6);
			}
			else if (type == BALANCE)
			{
				g.drawLine(12, 3, 12, 20);
				g.drawLine(5, 7, 19, 7);
				g.drawLine(7, 7, 4, 14);
				g.drawLine(17, 7, 20, 14);
				g.drawArc(2, 11, 6, 6, 180, 180);
				g.drawArc(16, 11, 6, 6, 180, 180);
				g.drawLine(7, 20, 17, 20);
			}
			else if (type == HEART)
			{
				g.fill(new Polygon(new int[]{12, 3, 2, 12, 22, 21},
					new int[]{21, 12, 7, 3, 7, 12}, 6));
			}
			else if (type == BACKPACK)
			{
				g.drawRoundRect(5, 6, 14, 16, 4, 4);
				g.drawArc(8, 1, 8, 9, 0, 180);
				g.drawLine(8, 13, 16, 13);
			}
			else if (type == SHIELD || type == GROUP_SHIELD)
			{
				g.draw(new Polygon(new int[]{12, 4, 5, 12, 19, 20},
					new int[]{2, 6, 14, 22, 14, 6}, 6));
				if (type == GROUP_SHIELD)
				{
					g.fillOval(8, 7, 4, 4);
					g.fillOval(13, 7, 4, 4);
				}
			}
			else
			{
				g.drawOval(type == GROUP ? 3 : 8, 3, 8, 8);
				if (type == GROUP)
				{
					g.drawOval(13, 3, 8, 8);
					g.drawArc(11, 11, 12, 10, 0, 180);
				}
				g.drawArc(type == GROUP ? 1 : 5, 11, 14, 11, 0, 180);
			}
			g.dispose();
		}
	}

	private static final class ScrollablePage extends NaturalHeightPanel implements Scrollable
	{
		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public Dimension getPreferredSize()
		{
			int width = getInsets().left + getInsets().right;
			int height = getInsets().top + getInsets().bottom;
			for (Component component : getComponents())
			{
				if (component.isVisible())
				{
					Dimension preferred = component.getPreferredSize();
					width = Math.max(width, preferred.width + getInsets().left + getInsets().right);
					height += preferred.height;
				}
			}
			return new Dimension(width, height);
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return Math.max(16, visibleRect.height - 32);
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}

	private static final class LevelFilter extends DocumentFilter
	{
		@Override
		public void insertString(FilterBypass bypass, int offset, String string,
			AttributeSet attributes) throws BadLocationException
		{
			replace(bypass, offset, 0, string, attributes);
		}

		@Override
		public void replace(FilterBypass bypass, int offset, int length, String text,
			AttributeSet attributes) throws BadLocationException
		{
			String replacement = text == null ? "" : text;
			String current = bypass.getDocument().getText(0, bypass.getDocument().getLength());
			String candidate = current.substring(0, offset) + replacement
				+ current.substring(offset + length);
			if (candidate.length() <= 2 && candidate.matches("\\d*"))
			{
				bypass.replace(offset, length, replacement, attributes);
			}
		}
	}
}

package com.efficientskilling;

import java.util.Collection;
import java.util.Locale;
import net.runelite.api.Quest;

/** Conservative matching for legacy requirements that name one complete quest. */
public final class QuestRequirementMatcher
{
	private QuestRequirementMatcher() { }

	public static Quest match(String requirement, Collection<Quest> quests)
	{
		String text = normalize(requirement).replaceFirst("^complete ", "");
		for (Quest quest : quests)
		{
			String name = normalize(quest.getName());
			if (text.equals(name) || text.startsWith(name + " for "))
			{
				return quest;
			}
		}
		return null;
	}

	private static String normalize(String value)
	{
		return value == null ? "" : value.toLowerCase(Locale.ROOT)
			.replace('’', '\'').replaceAll("[^a-z0-9']+", " ").trim();
	}
}

