	@Override
	protected void startUp()
	{
		detectAccountOnNextTick = false;
		if (TIMER_SIMULATOR_ENABLED)
		{
			trackedTaskSimulator = new TrackedTaskSimulator(Instant.now());
		}
		timedTaskExecutor = Executors.newSingleThreadScheduledExecutor(task ->
		{
			Thread thread = new Thread(task, "efficient-skilling-timed-tasks");
			thread.setDaemon(true);
			return thread;
		});
		long notificationPeriod = TIMER_SIMULATOR_ENABLED ? 1 : 30;
		notificationTask = timedTaskExecutor.scheduleAtFixedRate(
			this::checkTimedTaskNotifications, 1, notificationPeriod, TimeUnit.SECONDS);
		guideExecutor = Executors.newSingleThreadExecutor(task ->
		{
			Thread thread = new Thread(task, "efficient-skilling-guide-loader");
			thread.setDaemon(true);
			return thread;
		});
		pathToMaxController = new PathToMaxController(guideExecutor);
		ExecutorService executor = guideExecutor;
		guideLoadTask = executor.submit(() ->
		{
			try
			{
				guideService.load();
				SwingUtilities.invokeLater(() ->
				{
					if (guideExecutor != executor || executor.isShutdown())
					{
						return;
					}
					pathToMaxWindow = new PathToMaxWindow(null, timedTaskListener(), skillIconManager,
						config.interfaceFontScale(), scale -> configManager.setConfiguration(
							EfficientSkillingConfig.GROUP, "interfaceFontScale", scale), pathSettingsListener());
					pathToMaxWindow.updateCompanionSettings(config.timedTaskNotifications(),
						config.timedTaskSnoozeMinutes(), config.useBankedExperiencePreferences(),
						isCoreTimeTrackingActive());
					pathToMaxWindow.updateSkillStrategies(
						skillStrategyPreferenceStore.load(config.defaultStrategy()));
					pathToMaxWindow.updateManualLevels(manualStatsStore.load());
					pathToMaxWindow.updateMethodExclusions(methodExclusionStore.load());
					panel = new EfficientSkillingPanel(guideService, config, skillIconManager,
						this::openPathToMax);
					navigationButton = NavigationButton.builder()
						.tooltip("Efficient Skilling")
						.icon(ICON)
						.priority(6)
						.panel(panel)
						.build();
					clientToolbar.addNavigation(navigationButton);
					clientThread.invoke(this::refreshPlayerDetails);
				});
			}
			catch (RuntimeException ex)
			{
				log.error("Unable to load Efficient Skilling guide data", ex);
			}
		});
		log.debug("Efficient Skilling started");
	}

	@Override
	protected void shutDown()
	{
		if (pathToMaxController != null)
		{
			pathToMaxController.stop();
			pathToMaxController = null;
		}
		detectAccountOnNextTick = false;
		PathToMaxWindow oldWindow = pathToMaxWindow;
		NavigationButton oldNavigationButton = navigationButton;
		panel = null;
		pathToMaxWindow = null;
		navigationButton = null;
		clearActiveTimedTasks();
		clearTrackedActivities();
		clearBankSnapshot();
		if (notificationTask != null)
		{
			notificationTask.cancel(true);
			notificationTask = null;
		}
		if (timedTaskExecutor != null)
		{
			timedTaskExecutor.shutdownNow();
			timedTaskExecutor = null;
		}
		if (guideLoadTask != null)
		{
			guideLoadTask.cancel(true);
			guideLoadTask = null;
		}
		if (guideExecutor != null)
		{
			guideExecutor.shutdownNow();
			guideExecutor = null;
		}
		SwingUtilities.invokeLater(() ->
		{
			if (oldWindow != null)
			{
				oldWindow.close();
			}
			if (oldNavigationButton != null)
			{
				clientToolbar.removeNavigation(oldNavigationButton);
			}
		});
		log.debug("Efficient Skilling stopped");
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			detectAccountOnNextTick = true;
			coreTimeTrackingAdapter.reload();
			loadBankSnapshotForCurrentProfile();
			refreshPlayerDetails();
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			if (pathToMaxController != null) pathToMaxController.invalidate();
			detectAccountOnNextTick = false;
			clearActiveTimedTasks();
			clearTrackedActivities();
			clearBankSnapshot();
			EfficientSkillingPanel currentPanel = panel;
			if (currentPanel != null)
			{
				currentPanel.setDetectedAccount(null);
			}
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (detectAccountOnNextTick)
		{
			detectAccountOnNextTick = false;
			refreshDetectedAccount();
			loadTimedTasksForLoggedInAccount();
		}
		if (!TIMER_SIMULATOR_ENABLED)
		{
			refreshCoreTimeTracking();
		}
		if (questStateDirty && System.currentTimeMillis() - lastQuestSnapshotAt
			>= QUEST_REFRESH_INTERVAL_MILLIS)
		{
			questStateDirty = false;
			refreshOpenPathToMax();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (TimeTrackingConfig.CONFIG_GROUP.equals(event.getGroup()))
		{
			coreTimeTrackingAdapter.reload();
			refreshCoreTimeTracking();
		}
	}

	@Subscribe
	public void onPluginChanged(PluginChanged event)
	{
		if (event.getPlugin() instanceof TimeTrackingPlugin)
		{
			if (event.isLoaded())
			{
				coreTimeTrackingAdapter.reload();
				refreshCoreTimeTracking();
				refreshOpenPathToMax();
			}
			else
			{
				clearTrackedActivities();
				refreshOpenPathToMax();
			}
