	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (client.getGameState() != GameState.LOGGED_IN
			|| (event.getContainerId() != InventoryID.BANK
				&& event.getContainerId() != InventoryID.SEED_VAULT))
		{
			return;
		}
		String profileKey = configManager.getRSProfileKey();
		if (profileKey == null || profileKey.trim().isEmpty())
		{
			return;
		}
		try
		{
			BankItemSnapshot snapshot = bankSnapshotCapture.capture(event.getItemContainer(), Instant.now());
			if (event.getContainerId() == InventoryID.BANK)
			{
				boolean firstObservationThisSession = !bankObservedThisSession;
				bankObservedThisSession = true;
				boolean changed = bankProfileState.capture(profileKey, snapshot);
				if (changed) persistBankSnapshot(profileKey, snapshot);
				if (!changed && !firstObservationThisSession) return;
			}
			else
			{
				boolean firstObservationThisSession = !seedVaultObservedThisSession;
				seedVaultObservedThisSession = true;
				boolean changed = seedVaultProfileState.capture(profileKey, snapshot);
				if (changed) persistSeedVaultSnapshot(profileKey, snapshot);
				if (!changed && !firstObservationThisSession) return;
			}
			refreshOpenPathToMax();
		}
		catch (RuntimeException ex)
		{
			log.debug("Unable to capture account-storage snapshot", ex);
		}
	}

