	private void refreshPlayerDetails()
	{
		EfficientSkillingPanel currentPanel = panel;
		if (currentPanel == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		refreshDetectedAccount();
		for (Skill skill : Skill.values())
		{
			currentPanel.setLiveLevel(skill, client.getRealSkillLevel(skill));
		}
		loadTimedTasksForLoggedInAccount();
		loadBankSnapshotForCurrentProfile();
	}

	private void refreshDetectedAccount()
	{
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			setDetectedAccount(client.getVarbitValue(VarbitID.IRONMAN));
		}
	}

	private synchronized void refreshCoreTimeTracking()
	{
		if (client.getGameState() != GameState.LOGGED_IN || !isCoreTimeTrackingActive())
		{
			return;
		}
		Instant now = Instant.now();
		applyTrackedObservation(BIRD_HOUSE_ACTIVITY_ID, coreTimeTrackingAdapter.observe(now));
		applyTrackedObservation(HERB_RUN_ACTIVITY_ID, coreTimeTrackingAdapter.observeHerbRun(now));
	}

	private void applyTrackedObservation(String activityId, Optional<ActivityState> observed)
	{
		if (observed.isPresent())
		{
			applyTrackedActivity(activityId, observed.get());
		}
		else if (trackedActivities.remove(activityId) != null)
		{
			refreshOpenPathToMax();
		}
	}

	private void applyTrackedActivity(String activityId, ActivityState activity)
	{
		TimedActivityState current = trackedActivities.get(activityId);
		boolean newCycle = current == null
			|| !java.util.Objects.equals(current.getActivity().getCycleId(), activity.getCycleId());
		boolean changedStatus = current == null
			|| current.getActivity().getStatus() != activity.getStatus();
		TimedActivityState updated = current == null
			? new TimedActivityState(activity, trackedReminderProfileStore.loadActivity(activityId)
				.map(TimedActivityState::getReminder).orElse(ReminderState.enabled()))
			: current.observe(activity);
		trackedActivities.put(activityId, updated);
		if (newCycle || changedStatus)
		{
			trackedReminderProfileStore.saveActivity(activityId, updated);
			refreshOpenPathToMax();
		}
	}

	private void refreshOpenPathToMax()
	{
		SwingUtilities.invokeLater(() ->
		{
			PathToMaxWindow window = pathToMaxWindow;
			if (window != null && window.isVisible())
			{
				openPathToMax();
			}
		});
	}

	private boolean isCoreTimeTrackingActive()
	{
		return pluginManager.getPlugins().stream()
			.filter(TimeTrackingPlugin.class::isInstance)
			.map(TimeTrackingPlugin.class::cast)
			.anyMatch(pluginManager::isPluginActive);
	}

	private void setDetectedAccount(int accountType)
	{
		EfficientSkillingPanel currentPanel = panel;
		if (currentPanel == null)
		{
			return;
		}
		AccountProfile account = AccountProfile.fromVarbit(accountType);
		log.debug("Detected account type varbit {} as {}", accountType,
			account == null ? "undetected" : account);
		SwingUtilities.invokeLater(() -> currentPanel.setDetectedAccount(account));
	}

	private void openPathToMax()
	{
		PathToMaxController controller = pathToMaxController;
		if (controller == null) return;
		long requestGeneration = controller.beginRequest();
		EfficientSkillingPanel currentPanel = panel;
		PathToMaxWindow currentWindow = pathToMaxWindow;
		if (currentPanel == null || currentWindow == null)
		{
			return;
		}

		AccountProfile account = currentPanel.getSelectedAccount();
		GuideStrategy strategy = currentPanel.getSelectedApproach();
		if (account == null || strategy == null)
		{
			currentWindow.update(new PathToMaxViewModel(
				account == null ? "Confirm in sidebar" : account.toString(),
				strategy == null ? "Choose in sidebar" : strategy.toString(),
				"Confirm an account type and approach in the sidebar first.",
				0, 1, new LinkedHashMap<>()));
			currentWindow.showWindow();
			return;
		}
		SkillStrategyPreferences persistedStrategies = skillStrategyPreferenceStore.load(strategy);
		SkillStrategyPreferences selectedStrategies = persistedStrategies.withDefault(strategy);
		if (!selectedStrategies.equals(persistedStrategies))
		{
			skillStrategyPreferenceStore.save(selectedStrategies);
		}
		currentWindow.updateSkillStrategies(selectedStrategies);
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			Map<Skill, Integer> savedLevels = manualStatsStore.load();
			currentWindow.updateManualLevels(savedLevels);
			if (!savedLevels.isEmpty())
			{
				currentWindow.showWindow();
				buildManualPathToMax(savedLevels);
				return;
			}
			currentWindow.update(new PathToMaxViewModel(account.toString(), strategy.toString(),
				"Log in for exact XP, or open Settings and build from manual levels.",
				0, 1, new LinkedHashMap<>()));
			currentWindow.showWindow();
			return;
		}

		clientThread.invoke(() -> capturePathToMaxStats(
			account, strategy, currentWindow, requestGeneration));
	}

	private void capturePathToMaxStats(AccountProfile account, GuideStrategy strategy,
		PathToMaxWindow window, long requestGeneration)
	{
		PathToMaxController controller = pathToMaxController;
		if (controller == null || !controller.isCurrent(requestGeneration)) return;
		String accountIdentity = client.getLocalPlayer() == null
			? null : client.getLocalPlayer().getName();
		if (accountIdentity == null || accountIdentity.trim().isEmpty())
		{
			return;
		}
		Map<Skill, Integer> experience = new EnumMap<>(Skill.class);
		Map<String, Integer> levels = new LinkedHashMap<>();
		int totalLevel = 0;
		int skillCount = 0;
		for (Skill skill : Skill.values())
		{
			if ("OVERALL".equals(skill.name()))
			{
				continue;
			}
			int level = client.getRealSkillLevel(skill);
			experience.put(skill, Math.max(0, client.getSkillExperience(skill)));
			levels.put(formatSkill(skill), level);
			totalLevel += level;
			skillCount++;
		}
		Map<Quest, QuestState> questStates = new EnumMap<>(Quest.class);
		for (Quest quest : guideService.getReferencedQuests())
		{
			try
			{
				questStates.put(quest, quest.getState(client));
			}
			catch (RuntimeException ex)
			{
				log.debug("Unable to read quest state for {}", quest, ex);
			}
		}
		lastQuestSnapshotAt = System.currentTimeMillis();
		questStateDirty = false;

		ExecutorService executor = guideExecutor;
		if (executor == null || executor.isShutdown())
		{
			return;
		}
		int capturedTotalLevel = totalLevel;
		int capturedSkillCount = skillCount;
		String capturedProfileKey = configManager.getRSProfileKey();
		BankProfileState.Context bankContext = bankProfileState.context(capturedProfileKey);
		BankProfileState.Context seedVaultContext = seedVaultProfileState.context(capturedProfileKey);
		boolean capturedBankThisSession = bankObservedThisSession;
		boolean capturedVaultThisSession = seedVaultObservedThisSession;
		com.efficientskilling.integration.BankedExperiencePreferenceSnapshot bankedPreferences =
			config.useBankedExperiencePreferences() ? bankedExperiencePreferences.read()
				: com.efficientskilling.integration.BankedExperiencePreferenceSnapshot.defaults();
		SkillStrategyPreferences skillStrategies = skillStrategyPreferenceStore.load(strategy)
			.withDefault(strategy);
		Map<Skill, Integer> manualLevelPrefill = new EnumMap<>(Skill.class);
		for (Skill skill : experience.keySet())
		{
			manualLevelPrefill.put(skill, client.getRealSkillLevel(skill));
		}
		window.updateManualLevels(manualLevelPrefill);
		PathToMaxPlanningSnapshot snapshot = new PathToMaxPlanningSnapshot(account, skillStrategies,
			accountIdentity, experience, levels, capturedTotalLevel, capturedSkillCount,
			bankContext.getSnapshot(), seedVaultContext.getSnapshot(), capturedBankThisSession,
			capturedVaultThisSession, bankedPreferences, questStates, methodExclusionStore.load());
		if (!controller.submit(
			() -> buildAndShowPathToMax(snapshot, window, requestGeneration,
				bankContext, seedVaultContext)))
		{
			log.debug("Path to Max planning stopped during plugin shutdown");
		}
	}

	private void buildAndShowPathToMax(PathToMaxPlanningSnapshot snapshot,
		PathToMaxWindow window, long requestGeneration,
		BankProfileState.Context bankContext, BankProfileState.Context seedVaultContext)
	{
		AccountProfile account = snapshot.getAccount();
		GuideStrategy strategy = snapshot.getStrategies().getDefaultStrategy();
		SkillStrategyPreferences skillStrategies = snapshot.getStrategies();
		Map<Skill, Integer> experience = snapshot.getExperience();
		Map<Quest, QuestState> questStates = snapshot.getQuestStates();
		PathToMaxController controller = pathToMaxController;
		if (controller == null || !controller.isCurrent(requestGeneration) || window.isDisposed()
			|| !storageContextsCurrent(bankContext, seedVaultContext))
		{
			return;
		}
		Instant planningAt = Instant.now();
		BankItemSnapshot rawBank = snapshot.getBank();
		BankItemSnapshot rawSeedVault = snapshot.getSeedVault();
		AccountRules accountRules = AccountRules.forProfile(account);
		BankEvidencePolicy.Result bankEvidence = bankEvidencePolicy.evaluate(accountRules, rawBank, planningAt);
		BankEvidencePolicy.Result seedVaultEvidence = bankEvidencePolicy.evaluateSeedVault(
			accountRules, rawSeedVault, planningAt);
		BankItemSnapshot applicableBank = bankEvidence.isApplicable() ? rawBank : null;
		BankItemSnapshot applicableVault = seedVaultEvidence.isApplicable() ? rawSeedVault : null;
		BankItemSnapshot applicableStorage = combineStorageEvidence(
			applicableBank, applicableVault, planningAt,
			snapshot.isBankObservedThisSession(), snapshot.isSeedVaultObservedThisSession());
		boolean bankIncluded = sourceIncluded(true, applicableBank, applicableVault,
			snapshot.isBankObservedThisSession(), snapshot.isSeedVaultObservedThisSession());
		boolean vaultIncluded = sourceIncluded(false, applicableBank, applicableVault,
			snapshot.isBankObservedThisSession(), snapshot.isSeedVaultObservedThisSession());
		BankSnapshot observedBank = applicableStorage == null ? null : bankResourceMapper.map(applicableStorage);
		Map<RequirementItem, Long> ownedRequirementItems = pathToMaxModelFactory.requirementItems(applicableStorage);
		AccountStats accountStats = new AccountStats(experience);
		MaxPlan plan = new FarmingHerblorePlanner().plan(new MaxPlanRequest(
			account, skillStrategies.strategyFor(Skill.HERBLORE), accountStats, observedBank,
			applicableStorage != null, snapshot.getBankedExperiencePreferences()));
		Map<Skill, SkillBankedExperienceProjection> bankedProjections = applicableStorage == null
			? java.util.Collections.emptyMap()
			: bankedProjections(applicableStorage, experience, snapshot.getBankedExperiencePreferences());
		WholeAccountPlan wholeAccountPlan = wholeAccountPlanner.build(
			accountStats, bankedProjections, account, skillStrategies, questStates, ownedRequirementItems,
			applicableStorage != null, snapshot.getMethodExclusions());
		List<String> milestones = new ArrayList<>();
		for (MaxPlanStep step : plan.getSteps())
		{
			milestones.add(step.getTitle());
		}
		List<PathToMaxViewModel.TimedTaskRow> timedTasks = syncTimedTasks(
			snapshot.getAccountIdentity(), java.util.Collections.emptyList(), Instant.now());
		if (!TIMER_SIMULATOR_ENABLED)
		{
			birdHouseRow(Instant.now()).ifPresent(timedTasks::add);
			RecurringTask herbRunTask = plan.getRecurringTasks().stream()
				.filter(task -> HERB_RUN_ACTIVITY_ID.equals(task.getId())).findFirst().orElse(null);
			if (isCoreTimeTrackingActive() && herbRunTask != null)
			{
				herbRunRow(Instant.now(), herbRunTask).ifPresent(timedTasks::add);
			}
		}
		simulatorRow(Instant.now()).ifPresent(timedTasks::add);
		List<String> assumptions = new ArrayList<>(plan.getAssumptions());
		assumptions.add("Training catalogue last reviewed " + guideService.getReviewedAt()
			+ ". Rates are planning ranges and may change with game updates, equipment, and execution.");
		if (snapshot.getAccountIdentity().startsWith("manual:"))
		{
			assumptions.add("Manual levels use the minimum experience for each entered level. Log in to replace them with exact account experience, quest state, and current storage evidence.");
		}
		String bankStatus = accountRules.isBankAllowed()
			? bankEvidence.getStatus() + " " + seedVaultEvidence.getStatus()
			: bankEvidence.getStatus();
		if (accountRules.isBankAllowed() && rawBank != null && rawSeedVault != null
			&& !(snapshot.isBankObservedThisSession() && snapshot.isSeedVaultObservedThisSession()))
		{
			bankStatus += " Both sources must be opened in this client session before they are combined; until then only the source opened this session (or the newer saved source) is credited.";
		}
		else if (accountRules.isBankAllowed() && rawBank != null && rawSeedVault != null)
		{
			bankStatus += " Overlapping item IDs use the larger observed quantity so transfers between Bank and Seed Vault cannot be counted twice.";
		}
		List<PathToMaxViewModel.SupplyRow> supplies = new ArrayList<>();
		if (applicableStorage != null)
		{
			supplies.addAll(supplyRows(plan));
			supplies.addAll(bankedSkillSupplyRows(bankedProjections));
		}
		List<PathToMaxViewModel.SkillPlanRow> skillPlans = pathToMaxModelFactory.skillPlans(
			wholeAccountPlan, bankedProjections, questStates, ownedRequirementItems,
			applicableStorage != null, skillStrategies);
		List<PathToMaxViewModel.OverviewStepRow> overviewSteps = pathToMaxModelFactory.overview(wholeAccountPlan);
		List<PathToMaxViewModel.TimelineStepRow> timelineSteps = pathToMaxModelFactory.timeline(wholeAccountPlan);
		assumptions.add("The worklist schedules validated mandatory skill prerequisites, unlocks, and acquisitions before dependent methods. Free-text requirements remain notes; unresolved or cyclic dependencies are called out for manual review.");
		if (!TIMER_SIMULATOR_ENABLED && !isCoreTimeTrackingActive())
		{
			assumptions.add("RuneLite Time Tracking is disabled. Enable it to keep birdhouse and farming readiness current.");
		}
		if (TIMER_SIMULATOR_ENABLED)
		{
			assumptions.add("Developer timer simulation is active; it never changes or persists real activity state.");
		}
		String currentTask = plan.getSteps().isEmpty()
			? "Farming and Herblore are already complete."
			: plan.getSteps().get(0).getTitle();
		if (!timelineSteps.isEmpty())
		{
			currentTask = timelineSteps.get(0).getSkill() + ": " + timelineSteps.get(0).getMethod();
		}
		PathToMaxViewModel model = new PathToMaxViewModel(account.toString(), strategy.toString(),
			currentTask, snapshot.getTotalLevel(), snapshot.getSkillCount() * 99,
			snapshot.getDisplayLevels(), milestones, timedTasks,
			assumptions, bankStatus, supplies, skillPlans,
			new PathToMaxViewModel.StorageSummary(bankStatus, bankIncluded, vaultIncluded),
			overviewSteps, timelineSteps);
		SwingUtilities.invokeLater(() ->
		{
			PathToMaxController currentController = pathToMaxController;
			if (currentController != null && currentController.isCurrent(requestGeneration)
				&& !window.isDisposed()
				&& pathToMaxWindow == window
				&& storageContextsCurrent(bankContext, seedVaultContext))
			{
				window.updateCompanionSettings(config.timedTaskNotifications(),
					config.timedTaskSnoozeMinutes(), config.useBankedExperiencePreferences(),
					isCoreTimeTrackingActive());
			window.updateSkillStrategies(skillStrategies);
			window.updateMethodExclusions(snapshot.getMethodExclusions());
				window.update(model);
				window.showWindow();
			}
		});
	}

	private boolean storageContextsCurrent(BankProfileState.Context bankContext,
		BankProfileState.Context seedVaultContext)
	{
		return bankContext == null && seedVaultContext == null
			|| bankContext != null && seedVaultContext != null
				&& bankProfileState.isCurrent(bankContext)
				&& seedVaultProfileState.isCurrent(seedVaultContext);
	}

	private void buildManualPathToMax(Map<Skill, Integer> manualLevels)
	{
		EfficientSkillingPanel currentPanel = panel;
		PathToMaxWindow window = pathToMaxWindow;
		PathToMaxController controller = pathToMaxController;
		if (currentPanel == null || window == null || controller == null || manualLevels == null) return;
		AccountProfile account = currentPanel.getSelectedAccount();
		GuideStrategy selectedDefault = currentPanel.getSelectedApproach();
		if (account == null || selectedDefault == null) return;
		manualStatsStore.save(manualLevels);
		SkillStrategyPreferences strategies = skillStrategyPreferenceStore.load(selectedDefault)
			.withDefault(selectedDefault);
		Map<Skill, Integer> experience = new EnumMap<>(Skill.class);
		Map<String, Integer> displayLevels = new LinkedHashMap<>();
		int totalLevel = 0;
		int skillCount = 0;
		for (Skill skill : Skill.values())
		{
			if ("OVERALL".equals(skill.name())) continue;
			int level = Math.max(1, Math.min(99, manualLevels.getOrDefault(skill, 1)));
			experience.put(skill, net.runelite.api.Experience.getXpForLevel(level));
			displayLevels.put(formatSkill(skill), level);
			totalLevel += level;
			skillCount++;
		}
		PathToMaxPlanningSnapshot snapshot = new PathToMaxPlanningSnapshot(account, strategies,
			"manual:" + account.name(), experience, displayLevels, totalLevel, skillCount,
			null, null, false, false,
			com.efficientskilling.integration.BankedExperiencePreferenceSnapshot.defaults(),
			new EnumMap<>(Quest.class), methodExclusionStore.load());
		long generation = controller.beginRequest();
		if (!controller.submit(() -> buildAndShowPathToMax(snapshot, window, generation, null, null)))
		{
			log.debug("Manual Path to Max planning stopped during plugin shutdown");
		}
	}


	private synchronized Optional<PathToMaxViewModel.TimedTaskRow> birdHouseRow(Instant now)
	{
		TimedActivityState birdHouseActivity = trackedActivities.get(BIRD_HOUSE_ACTIVITY_ID);
		if (birdHouseActivity == null)
		{
			boolean active = isCoreTimeTrackingActive();
			return Optional.of(new PathToMaxViewModel.TimedTaskRow(BIRD_HOUSE_ACTIVITY_ID,
				active ? "Birdhouse tracking" : "RuneLite Time Tracking",
				active ? "Waiting for data" : "Time Tracking disabled",
				active
					? "Time Tracking is on, but this profile has no birdhouse data yet. Visit the birdhouse area once."
					: "Enable it in RuneLite's plugin list to track birdhouse and herb-patch readiness.",
				null, false, false, false, false));
		}
		ActivityState activity = birdHouseActivity.getActivity();
		ReminderState reminder = birdHouseActivity.getReminder();
		String status;
		switch (activity.getStatus())
		{
			case READY:
				status = "Ready";
				break;
			case PARTIALLY_READY:
				status = "Partially ready";
				break;
			case GROWING:
				status = "Growing";
				break;
			case COMPLETE:
				status = "Complete";
				break;
			case UNKNOWN:
			default:
				status = "No active birdhouses";
				break;
		}
		boolean reminderSnoozed = reminder.getSuppressedUntilEpochMillis() != null
			&& reminder.getSuppressedUntilEpochMillis() > now.toEpochMilli();
		Long dueAt = reminderSnoozed ? reminder.getSuppressedUntilEpochMillis()
			: activity.getStatus() == ActivityStatus.ATTENTION ? null : activity.getReadyAtEpochMillis();
		String detail = activity.getTarget() == 0
			? "Plant birdhouses to start the next timer. Synced from RuneLite Time Tracking."
			: activity.getProgress() + " of " + activity.getTarget()
				+ " active birdhouses ready. Synced from RuneLite Time Tracking.";
		return Optional.of(new PathToMaxViewModel.TimedTaskRow(BIRD_HOUSE_ACTIVITY_ID, "Birdhouse run",
			status, detail, dueAt, !reminder.isEnabled(), false, true));
	}

	private synchronized Optional<PathToMaxViewModel.TimedTaskRow> herbRunRow(Instant now,
		RecurringTask planTask)
	{
		TimedActivityState herbRun = trackedActivities.get(HERB_RUN_ACTIVITY_ID);
		if (herbRun == null)
		{
