			"Herb run", status, detail, dueAt, !reminder.isEnabled(), false, true));
	}

	private synchronized Optional<PathToMaxViewModel.TimedTaskRow> simulatorRow(Instant now)
	{
		if (!TIMER_SIMULATOR_ENABLED || trackedTaskSimulator == null)
		{
			return Optional.empty();
		}
		ActivityState activity = trackedTaskSimulator.stateAt(now);
		simulatedActivity = simulatedActivity == null
			? new TimedActivityState(activity, ReminderState.enabled())
			: simulatedActivity.observe(activity);
		ReminderState reminder = simulatedActivity.getReminder();
		String status = activity.getStatus() == ActivityStatus.READY ? "Ready"
			: activity.getStatus() == ActivityStatus.PARTIALLY_READY ? "Partially ready" : "Growing";
		Long dueAt = activity.getStatus() == ActivityStatus.READY
			&& reminder.getSuppressedUntilEpochMillis() != null
			&& reminder.getSuppressedUntilEpochMillis() > now.toEpochMilli()
			? reminder.getSuppressedUntilEpochMillis() : activity.getReadyAtEpochMillis();
		return Optional.of(new PathToMaxViewModel.TimedTaskRow("developer-tracked-task",
			"[DEMO] Tracked task", status,
			"Development-only: 15s partial, 30s ready, 10s reminder deferral.", dueAt,
			!reminder.isEnabled(), false, true));
	}

	private synchronized List<PathToMaxViewModel.TimedTaskRow> syncTimedTasks(
		String accountIdentity, List<RecurringTask> plannedTasks, Instant now)
	{
		boolean changed = false;
		if (!accountIdentity.equals(timedTaskAccountIdentity) || !timedTaskStateLoaded)
		{
			timedTaskStates.clear();
			timedTaskAccountIdentity = accountIdentity;
			applyTimedTaskData(timedTaskRepository.load(accountIdentity, TimedTaskData.class)
				.orElse(null));
			timedTaskStateLoaded = true;
			if (accountIdentity.equals(timedTaskLoadingIdentity))
			{
				timedTaskLoadingIdentity = null;
			}
		}

		Map<String, RecurringTask> definitions = new LinkedHashMap<>();
		for (RecurringTask task : plannedTasks)
		{
			definitions.put(task.getId(), task);
			TimedTaskState existing = timedTaskStates.get(task.getId());
			if (existing == null)
			{
				timedTaskStates.put(task.getId(), TimedTaskState.create(task.getId(), task.getTitle(),
					task.getInterval(), task.getTargetCompletions(), now));
				changed = true;
			}
			else if (existing.getTargetCompletions() != task.getTargetCompletions()
				|| existing.getIntervalMillis() != task.getInterval().toMillis()
				|| !existing.getTitle().equals(task.getTitle()))
			{
				timedTaskStates.put(task.getId(), new TimedTaskState(task.getId(), task.getTitle(),
					task.getInterval().toMillis(), task.getTargetCompletions(),
					Math.min(existing.getCompletedCount(), task.getTargetCompletions()),
					existing.getNextDueAtEpochMillis(), existing.getSnoozedUntilEpochMillis(),
					existing.isDisabled(), existing.getLastNotifiedDueAtEpochMillis()));
				changed = true;
			}
		}
		if (timedTaskStates.keySet().removeIf(id -> !definitions.containsKey(id)))
		{
			changed = true;
		}

		List<PathToMaxViewModel.TimedTaskRow> rows = new ArrayList<>();
		for (RecurringTask definition : plannedTasks)
		{
			TimedTaskState state = timedTaskStates.get(definition.getId());
			TimedTaskStatus status = state.statusAt(now);
			Long dueAt = status == TimedTaskStatus.SNOOZED
				? state.getSnoozedUntilEpochMillis()
				: status == TimedTaskStatus.READY || status == TimedTaskStatus.UPCOMING
					? state.getNextDueAtEpochMillis() : null;
			String detail = state.getCompletedCount() + " of " + state.getTargetCompletions()
				+ " completed - " + definition.getReason();
			rows.add(new PathToMaxViewModel.TimedTaskRow(state.getId(), state.getTitle(),
				formatTimedTaskStatus(status), detail, dueAt, state.isDisabled(), true, false));
		}
		if (changed)
		{
			saveTimedTasksAsync();
		}
		return rows;
	}

	private PathToMaxWindow.SettingsListener pathSettingsListener()
	{
		return new PathToMaxWindow.SettingsListener()
		{
			@Override
			public void onNotificationsChanged(boolean enabled)
			{
				configManager.setConfiguration(EfficientSkillingConfig.GROUP,
					"timedTaskNotifications", enabled);
			}

			@Override
			public void onSnoozeMinutesChanged(int minutes)
			{
				configManager.setConfiguration(EfficientSkillingConfig.GROUP,
					"timedTaskSnoozeMinutes", Math.max(1, Math.min(1440, minutes)));
			}

			@Override
			public void onBankedExperienceChanged(boolean enabled)
			{
				configManager.setConfiguration(EfficientSkillingConfig.GROUP,
					"useBankedExperiencePreferences", enabled);
				refreshOpenPathToMax();
			}

			@Override
			public void onSkillStrategiesChanged(SkillStrategyPreferences preferences)
			{
				skillStrategyPreferenceStore.save(preferences);
				EfficientSkillingPanel currentPanel = panel;
				if (currentPanel != null)
					currentPanel.setPathToMaxDefaultStrategy(preferences.getDefaultStrategy());
				refreshOpenPathToMax();
			}

			@Override
			public void onManualLevelsApplied(Map<Skill, Integer> manualLevels)
			{
				buildManualPathToMax(manualLevels);
			}

			@Override
			public void onMethodExcluded(Skill skill, String method)
			{
				MethodExclusions updated = methodExclusionStore.load().withExcluded(skill, method);
				methodExclusionStore.save(updated);
				PathToMaxWindow window = pathToMaxWindow;
				if (window != null) window.updateMethodExclusions(updated);
				refreshOpenPathToMax();
			}

			@Override
			public void onMethodRestored(Skill skill, String method)
			{
				MethodExclusions updated = methodExclusionStore.load().without(skill, method);
				methodExclusionStore.save(updated);
				PathToMaxWindow window = pathToMaxWindow;
				if (window != null) window.updateMethodExclusions(updated);
				refreshOpenPathToMax();
			}

			@Override
			public void onClearMethodExclusions()
			{
				MethodExclusions cleared = MethodExclusions.none();
				methodExclusionStore.save(cleared);
				PathToMaxWindow window = pathToMaxWindow;
				if (window != null) window.updateMethodExclusions(cleared);
				refreshOpenPathToMax();
			}

			@Override
			public void onWindowHidden()
			{
				PathToMaxController controller = pathToMaxController;
				if (controller != null) controller.invalidate();
			}
		};
	}

	private PathToMaxWindow.TimedTaskListener timedTaskListener()
	{
		return new PathToMaxWindow.TimedTaskListener()
		{
			@Override
			public void onComplete(String taskId)
			{
				updateTimedTask(taskId, state -> state.complete(Instant.now()));
			}

			@Override
			public void onSnooze(String taskId)
			{
				if ("developer-tracked-task".equals(taskId))
				{
					remindSimulatedTaskLater(Duration.ofSeconds(10));
					return;
				}
				int minutes = Math.max(1, Math.min(1440, config.timedTaskSnoozeMinutes()));
				if (BIRD_HOUSE_ACTIVITY_ID.equals(taskId) || HERB_RUN_ACTIVITY_ID.equals(taskId))
				{
					remindTrackedActivityLater(taskId, Duration.ofMinutes(minutes));
					return;
				}
				updateTimedTask(taskId, state -> state.snooze(Instant.now(), Duration.ofMinutes(minutes)));
			}

			@Override
			public void onPauseChanged(String taskId, boolean paused)
			{
				if ("developer-tracked-task".equals(taskId))
				{
					setSimulatedRemindersEnabled(!paused);
					return;
				}
				if (BIRD_HOUSE_ACTIVITY_ID.equals(taskId) || HERB_RUN_ACTIVITY_ID.equals(taskId))
				{
					setTrackedActivityRemindersEnabled(taskId, !paused);
					return;
				}
				updateTimedTask(taskId, state -> state.setDisabled(paused));
			}
		};
	}

	private void updateTimedTask(String taskId,
		java.util.function.UnaryOperator<TimedTaskState> update)
	{
		synchronized (this)
		{
			TimedTaskState current = timedTaskStates.get(taskId);
			if (current == null)
			{
				return;
			}
			timedTaskStates.put(taskId, update.apply(current));
			saveTimedTasksAsync();
		}
		openPathToMax();
	}

	private void remindTrackedActivityLater(String activityId, Duration delay)
	{
		TimedActivityState updated;
		synchronized (this)
		{
			TimedActivityState current = trackedActivities.get(activityId);
			if (current == null || current.getActivity().getStatus() != ActivityStatus.READY)
			{
				return;
			}
			updated = current.remindLater(Instant.now(), delay);
			trackedActivities.put(activityId, updated);
		}
		clientThread.invoke(() -> trackedReminderProfileStore.saveActivity(activityId, updated));
		openPathToMax();
	}

	private void setTrackedActivityRemindersEnabled(String activityId, boolean enabled)
	{
		TimedActivityState updated;
		synchronized (this)
		{
			TimedActivityState currentActivity = trackedActivities.get(activityId);
			if (currentActivity == null)
			{
				return;
			}
			ReminderState current = currentActivity.getReminder();
			ReminderState reminder = new ReminderState(enabled,
				current.getSuppressedUntilEpochMillis(), current.getLastNotifiedCycleId(),
				current.getGeneration(), current.getLastNotifiedGeneration());
			updated = new TimedActivityState(currentActivity.getActivity(), reminder);
			trackedActivities.put(activityId, updated);
		}
		clientThread.invoke(() -> trackedReminderProfileStore.saveActivity(activityId, updated));
		openPathToMax();
	}

	private void remindSimulatedTaskLater(Duration delay)
	{
		synchronized (this)
		{
			if (simulatedActivity == null)
			{
				return;
			}
			simulatedActivity = simulatedActivity.observe(trackedTaskSimulator.stateAt(Instant.now()));
			if (simulatedActivity.getActivity().getStatus() != ActivityStatus.READY)
			{
				return;
			}
			simulatedActivity = simulatedActivity.remindLater(Instant.now(), delay);
		}
		openPathToMax();
	}

	private void setSimulatedRemindersEnabled(boolean enabled)
	{
		synchronized (this)
		{
			if (simulatedActivity == null)
			{
				return;
			}
			ReminderState current = simulatedActivity.getReminder();
			simulatedActivity = new TimedActivityState(simulatedActivity.getActivity(),
				new ReminderState(enabled, current.getSuppressedUntilEpochMillis(),
					current.getLastNotifiedCycleId(), current.getGeneration(),
					current.getLastNotifiedGeneration()));
		}
		openPathToMax();
	}

	private void saveTimedTasksAsync()
	{
		ScheduledExecutorService executor = timedTaskExecutor;
		String accountIdentity = timedTaskAccountIdentity;
		TimedTaskData data = new TimedTaskData(new ArrayList<>(timedTaskStates.values()));
		if (executor == null || executor.isShutdown() || accountIdentity == null)
		{
			return;
		}
		try
		{
			executor.execute(() ->
			{
				try
				{
					timedTaskRepository.save(accountIdentity, data);
				}
				catch (IOException ex)
				{
					log.debug("Unable to save Path to Max timed tasks", ex);
				}
			});
		}
		catch (RejectedExecutionException ex)
		{
			log.debug("Timed-task save stopped during plugin shutdown");
		}
	}

	private void loadTimedTasksForLoggedInAccount()
	{
		if (client.getLocalPlayer() == null || timedTaskExecutor == null)
		{
			return;
		}
		String accountIdentity = client.getLocalPlayer().getName();
		if (accountIdentity == null || accountIdentity.trim().isEmpty())
		{
			return;
		}
		synchronized (this)
		{
			if ((accountIdentity.equals(timedTaskAccountIdentity) && timedTaskStateLoaded)
				|| accountIdentity.equals(timedTaskLoadingIdentity))
			{
				return;
			}
			timedTaskAccountIdentity = accountIdentity;
			timedTaskStateLoaded = false;
			timedTaskLoadingIdentity = accountIdentity;
			timedTaskStates.clear();
		}
		try
		{
			timedTaskExecutor.execute(() ->
			{
				TimedTaskData data = timedTaskRepository.load(accountIdentity, TimedTaskData.class)
					.orElse(null);
				synchronized (EfficientSkillingPlugin.this)
				{
					if (accountIdentity.equals(timedTaskAccountIdentity) && !timedTaskStateLoaded)
					{
						applyTimedTaskData(data);
						timedTaskStateLoaded = true;
					}
					if (accountIdentity.equals(timedTaskLoadingIdentity))
					{
						timedTaskLoadingIdentity = null;
					}
				}
			});
		}
		catch (RejectedExecutionException ex)
		{
			log.debug("Timed-task load stopped during plugin shutdown");
		}
	}

	private void loadBankSnapshotForCurrentProfile()
	{
		ScheduledExecutorService executor = timedTaskExecutor;
		String profileKey = configManager.getRSProfileKey();
		if (executor == null || executor.isShutdown() || profileKey == null || profileKey.trim().isEmpty())
		{
