			{
				Optional<BankItemSnapshot> loaded = bankSnapshotRepository.load(profileKey);
				Optional<BankItemSnapshot> loadedSeedVault = seedVaultSnapshotRepository.load(profileKey);
				boolean bankApplied = bankProfileState.applyLoaded(token, loaded);
				boolean vaultApplied = seedVaultProfileState.applyLoaded(seedVaultToken, loadedSeedVault);
				if (bankApplied || vaultApplied)
