	static BankItemSnapshot combineStorageEvidence(BankItemSnapshot bank,
		BankItemSnapshot seedVault, Instant observedAt)
	{
		return combineStorageEvidence(bank, seedVault, observedAt, true, true);
	}

	static BankItemSnapshot combineStorageEvidence(BankItemSnapshot bank,
		BankItemSnapshot seedVault, Instant observedAt, boolean bankObservedThisSession,
		boolean seedVaultObservedThisSession)
	{
		if (bank == null && seedVault == null)
		{
			return null;
		}
		if (bank != null && seedVault != null
			&& !(bankObservedThisSession && seedVaultObservedThisSession))
		{
			if (bankObservedThisSession) return bank;
			if (seedVaultObservedThisSession) return seedVault;
			return bank.getObservedAt().isAfter(seedVault.getObservedAt()) ? bank : seedVault;
		}
		Map<Integer, Long> quantities = new LinkedHashMap<>();
		if (bank != null)
		{
			bank.getQuantities().forEach((id, quantity) ->
				quantities.merge(id, quantity, Math::addExact));
		}
		if (seedVault != null)
		{
			seedVault.getQuantities().forEach((id, quantity) ->
				quantities.merge(id, quantity, Math::max));
		}
		return new BankItemSnapshot(observedAt, quantities);
	}


	private void applyTimedTaskData(TimedTaskData data)
	{
		if (data == null)
		{
			return;
		}
		int index = 0;
		for (TimedTaskState state : data.getTasks())
		{
			try
			{
				if (state == null)
				{
					throw new IllegalArgumentException("task is null");
				}
				TimedTaskState validated = new TimedTaskState(state.getId(), state.getTitle(),
					state.getIntervalMillis(), state.getTargetCompletions(),
					state.getCompletedCount(), state.getNextDueAtEpochMillis(),
					state.getSnoozedUntilEpochMillis(), state.isDisabled(),
					state.getLastNotifiedDueAtEpochMillis());
				timedTaskStates.put(validated.getId(), validated);
			}
			catch (RuntimeException ex)
			{
				log.debug("Ignoring invalid persisted timed task at index {}", index);
			}
			index++;
		}
	}

	private void checkTimedTaskNotifications()
	{
		try
		{
			doCheckTimedTaskNotifications();
		}
		catch (RuntimeException ex)
		{
			log.debug("Unable to check Path to Max timed-task notifications", ex);
		}
	}

	private void doCheckTimedTaskNotifications()
	{
		if (!config.timedTaskNotifications())
		{
			return;
		}
		List<String> notificationMessages = new ArrayList<>();
		Map<String, TimedActivityState> trackedToSave = new LinkedHashMap<>();
		synchronized (this)
		{
			Instant now = Instant.now();
			for (TimedTaskState state : timedTaskStates.values())
			{
				if (state.shouldNotifyAt(now))
				{
					notificationMessages.add(state.getTitle() + " is ready.");
					timedTaskStates.put(state.getId(), state.markNotified(now));
				}
			}
			if (!notificationMessages.isEmpty())
			{
				saveTimedTasksAsync();
			}
			if (!TIMER_SIMULATOR_ENABLED)
			{
				for (Map.Entry<String, TimedActivityState> entry : trackedActivities.entrySet())
				{
					TimedActivityState activity = entry.getValue();
					if (!activity.shouldNotifyAt(now))
					{
						continue;
					}
					boolean repeated = activity.getReminder().getGeneration() > 0;
					String title = trackedActivityTitle(entry.getKey());
					if (activity.getActivity().getStatus() == ActivityStatus.ATTENTION)
					{
						notificationMessages.add(repeated
							? title + " still needs attention." : title + " needs attention.");
					}
					else
					{
						notificationMessages.add(repeated
							? title + " is still ready." : title + " is ready.");
					}
					TimedActivityState notified = activity.markNotified(now);
					trackedActivities.put(entry.getKey(), notified);
					trackedToSave.put(entry.getKey(), notified);
				}
			}
			if (TIMER_SIMULATOR_ENABLED && trackedTaskSimulator != null)
			{
				ActivityState simulatedState = trackedTaskSimulator.stateAt(now);
				simulatedActivity = simulatedActivity == null
					? new TimedActivityState(simulatedState, ReminderState.enabled())
					: simulatedActivity.observe(simulatedState);
				if (simulatedActivity.shouldNotifyAt(now))
				{
					boolean repeated = simulatedActivity.getReminder().getGeneration() > 0;
					notificationMessages.add(repeated ? "[DEMO] Tracked task is still ready."
						: "[DEMO] Tracked task is ready.");
					simulatedActivity = simulatedActivity.markNotified(now);
				}
			}
		}
		for (Map.Entry<String, TimedActivityState> entry : trackedToSave.entrySet())
		{
			String activityId = entry.getKey();
			TimedActivityState saved = entry.getValue();
			clientThread.invoke(() -> trackedReminderProfileStore.saveActivity(activityId, saved));
		}
		for (String message : notificationMessages)
		{
			notifier.notify("Path to Max: " + message);
		}
	}

	private synchronized void clearActiveTimedTasks()
	{
		timedTaskStates.clear();
		timedTaskAccountIdentity = null;
		timedTaskStateLoaded = false;
		timedTaskLoadingIdentity = null;
	}

