	private static String trackedActivityTitle(String activityId)
	{
		return HERB_RUN_ACTIVITY_ID.equals(activityId) ? "Herb run" : "Birdhouse run";
	}

	private static List<PathToMaxViewModel.SupplyRow> supplyRows(MaxPlan plan)
	{
		List<PathToMaxViewModel.SupplyRow> rows = new ArrayList<>();
		for (ResourceBalance balance : plan.getResourceBalances())
		{
			if (balance.getResource() == com.efficientskilling.planner.MaxingResource.HERBLORE_XP_TENTHS)
			{
				rows.add(new PathToMaxViewModel.SupplyRow("Potential Herblore XP",
					balance.getObserved(), balance.getApplied(),
					balance.getRequired(), balance.getMissing(), true));
				continue;
			}
			String label = balance.getResource() == com.efficientskilling.planner.MaxingResource.HERB_SEED
				? "Herb seeds" : "Herbs usable for selected conversions";
			rows.add(new PathToMaxViewModel.SupplyRow(label, balance.getObserved(),
				balance.getApplied(), balance.getRequired(), balance.getMissing()));
		}
		return rows;
	}

	private static List<PathToMaxViewModel.SupplyRow> bankedSkillSupplyRows(
		Map<Skill, SkillBankedExperienceProjection> projections)
	{
		List<PathToMaxViewModel.SupplyRow> rows = new ArrayList<>();
		for (SkillBankedExperienceProjection projection : projections.values())
		{
			if (projection.getSkill() == Skill.HERBLORE
				|| projection.getTotalPotentialExperience().signum() <= 0)
			{
				continue;
			}
			BigDecimal needed = projection.getTargetExperience()
				.subtract(projection.getCurrentExperience()).max(BigDecimal.ZERO);
			rows.add(new PathToMaxViewModel.SupplyRow(
				formatSkill(projection.getSkill()) + " banked XP",
				toTenths(projection.getTotalPotentialExperience()),
				toTenths(projection.getCreditedTowardTargetExperience()),
				toTenths(needed), toTenths(projection.getRemainingAfterBankedExperience()), true));
		}
		return rows;
	}

	private static Map<Skill, SkillBankedExperienceProjection> bankedProjections(
		BankItemSnapshot storage, Map<Skill, Integer> experience,
		com.efficientskilling.integration.BankedExperiencePreferenceSnapshot preferences)
	{
		Map<Skill, SkillBankedExperienceProjection> projections = new EnumMap<>(Skill.class);
		BankedExperienceCalculator calculator = new BankedExperienceCalculator();
		for (Skill skill : Activity.BANKABLE_SKILLS)
		{
			long currentXp = Math.max(0, experience.getOrDefault(skill, 0));
			int level = net.runelite.api.Experience.getLevelForXp((int) Math.min(Integer.MAX_VALUE, currentXp));
			projections.put(skill, calculator.project(skill, storage.getQuantities(), level,
				currentXp, AccountStats.XP_FOR_99, preferences));
		}
		return projections;
	}

	private static boolean sourceIncluded(boolean bankSource, BankItemSnapshot bank,
		BankItemSnapshot vault, boolean bankObservedThisSession, boolean vaultObservedThisSession)
	{
		BankItemSnapshot source = bankSource ? bank : vault;
		if (source == null) return false;
		if (bank == null || vault == null || (bankObservedThisSession && vaultObservedThisSession)) return true;
		if (bankObservedThisSession != vaultObservedThisSession)
			return bankSource == bankObservedThisSession;
		boolean bankNewer = bank.getObservedAt().isAfter(vault.getObservedAt());
		return bankSource == bankNewer;
	}

	private static long toTenths(BigDecimal experience)
	{
		return experience.movePointRight(1).setScale(0, RoundingMode.HALF_UP).longValueExact();
	}

	private static String formatCount(long value)
	{
		return String.format(java.util.Locale.US, "%,d", value);
	}

	private static String formatTimedTaskStatus(TimedTaskStatus status)
	{
		switch (status)
		{
			case READY:
				return "Ready";
			case SNOOZED:
				return "Snoozed";
			case COMPLETE:
				return "Complete";
			case DISABLED:
				return "Paused";
			case UPCOMING:
			default:
				return "Upcoming";
		}
	}

	private static String formatSkill(Skill skill)
	{
		String lower = skill.name().toLowerCase(java.util.Locale.ROOT).replace('_', ' ');
		return Character.toUpperCase(lower.charAt(0)) + lower.substring(1);
	}

	@Provides
	EfficientSkillingConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(EfficientSkillingConfig.class);
	}
}

