/** Focused progressive editor for the global Path to Max style and skill overrides. */
final class SkillStrategyEditorPanel extends JPanel
{
	private static final Color ACCENT = new Color(255, 152, 31);
	private static final Color MUTED = new Color(170, 170, 170);
	private final Consumer<SkillStrategyPreferences> listener;
	private final JComboBox<GuideStrategy> defaultStrategy = new JComboBox<>(GuideStrategy.values());
	private final Map<Skill, JComboBox<String>> controls = new EnumMap<>(Skill.class);
	private final JPanel overrideRows = verticalPanel();
	private final JButton reveal = button("Show skill overrides");
	private SkillStrategyPreferences preferences = SkillStrategyPreferences.all(GuideStrategy.BALANCED);
	private boolean updating;

	SkillStrategyEditorPanel(Consumer<SkillStrategyPreferences> listener)
	{
		this.listener = Objects.requireNonNull(listener, "listener");
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
			BorderFactory.createEmptyBorder(16, 18, 16, 18)));
		setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel caption = new JLabel("TRAINING STYLES");
		caption.setForeground(ACCENT);
		caption.setFont(caption.getFont().deriveFont(Font.BOLD));
		caption.setAlignmentX(Component.LEFT_ALIGNMENT);
		add(caption);
		add(Box.createVerticalStrut(6));
		add(help("Set one account default, then override only the skills you want to train differently."));
		add(Box.createVerticalStrut(12));

		defaultStrategy.setMaximumSize(new Dimension(170, 30));
		defaultStrategy.getAccessibleContext().setAccessibleName("Default training style");
		defaultStrategy.addActionListener(event ->
		{
			if (updating) return;
			GuideStrategy selected = (GuideStrategy) defaultStrategy.getSelectedItem();
			if (selected == null) return;
			preferences = preferences.withDefault(selected);
			refreshControls();
			listener.accept(preferences);
		});
		add(row("Default style", "Applied to every skill without an explicit override.", defaultStrategy));
		add(Box.createVerticalStrut(10));

		overrideRows.setVisible(false);
		for (Skill skill : Skill.values())
		{
			if ("OVERALL".equals(skill.name())) continue;
			JComboBox<String> control = new JComboBox<>();
			control.setPreferredSize(new Dimension(190, 30));
			control.getAccessibleContext().setAccessibleName(skill.getName() + " training style");
			control.addActionListener(event ->
			{
				if (updating) return;
				int selected = control.getSelectedIndex();
				preferences = selected <= 0 ? preferences.withoutOverride(skill)
					: preferences.withOverride(skill, GuideStrategy.values()[selected - 1]);
				listener.accept(preferences);
			});
			controls.put(skill, control);
			overrideRows.add(row(skill.getName(), "Use the default or choose a style for this skill.", control));
			overrideRows.add(Box.createVerticalStrut(4));
		}
		JButton reset = button("Apply default to all / reset overrides");
		reset.getAccessibleContext().setAccessibleDescription("Make every skill use the default training style");
		reset.addActionListener(event ->
		{
			preferences = SkillStrategyPreferences.all(preferences.getDefaultStrategy());
			refreshControls();
			listener.accept(preferences);
		});
		overrideRows.add(Box.createVerticalStrut(8));
		overrideRows.add(reset);

		reveal.getAccessibleContext().setAccessibleDescription("Show or hide individual skill style controls");
		reveal.addActionListener(event -> setOverridesVisible(!overrideRows.isVisible()));
		add(reveal);
		add(Box.createVerticalStrut(8));
		add(overrideRows);
		refreshControls();
		SettingsPanelLayout.bind(this);
	}

	void setPreferences(SkillStrategyPreferences preferences)
	{
		this.preferences = Objects.requireNonNull(preferences, "preferences");
		updating = true;
		defaultStrategy.setSelectedItem(preferences.getDefaultStrategy());
		refreshControls();
		updating = false;
	}

	SkillStrategyPreferences getPreferences() { return preferences; }

	void chooseForSkill(Skill skill, GuideStrategy strategy)
	{
		preferences = strategy == null ? preferences.withoutOverride(skill)
			: preferences.withOverride(skill, strategy);
		refreshControls();
		listener.accept(preferences);
	}
	JComboBox<String> controlFor(Skill skill) { return controls.get(skill); }
	JComboBox<GuideStrategy> getDefaultControl() { return defaultStrategy; }
	boolean areOverridesVisible() { return overrideRows.isVisible(); }
	void setOverridesVisible(boolean visible)
	{
		overrideRows.setVisible(visible);
		reveal.setText(visible ? "Hide skill overrides" : "Show skill overrides");
		SettingsPanelLayout.refresh(this);
	}

	private void refreshControls()
	{
		boolean previous = updating;
		updating = true;
		for (Map.Entry<Skill, JComboBox<String>> entry : controls.entrySet())
		{
			JComboBox<String> control = entry.getValue();
			control.removeAllItems();
			control.addItem("Use default (" + preferences.getDefaultStrategy() + ")");
			for (GuideStrategy strategy : GuideStrategy.values()) control.addItem(strategy.toString());
			GuideStrategy override = preferences.getOverrides().get(entry.getKey());
			control.setSelectedIndex(override == null ? 0 : override.ordinal() + 1);
		}
		updating = previous;
	}

	private static JPanel verticalPanel()
	{
		JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setOpaque(false);
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		return panel;
	}

	private static JPanel row(String title, String description, Component control)
	{
		JPanel row = new JPanel(new BorderLayout(18, 0));
		row.setOpaque(false);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		JPanel copy = verticalPanel();
		JLabel heading = new JLabel(title);
		heading.setForeground(Color.WHITE);
		heading.setFont(heading.getFont().deriveFont(Font.BOLD));
		copy.add(heading);
		copy.add(Box.createVerticalStrut(3));
		copy.add(help(description));
		row.add(copy, BorderLayout.CENTER);
		JPanel controlPanel = new JPanel(new FlowLayout(FlowLayout.RIGHT, 0, 4));
		controlPanel.setOpaque(false);
		controlPanel.add(control);
		row.add(controlPanel, BorderLayout.EAST);
		row.setMaximumSize(new Dimension(920, Math.max(54, row.getPreferredSize().height)));
		return row;
	}

	private static JLabel help(String text)
	{
		JLabel label = new JLabel("<html><div style='width:420px'>" + text + "</div></html>");
		label.setForeground(MUTED);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	private static JButton button(String text)
	{
		JButton button = new JButton(text);
		button.setForeground(Color.WHITE);
		button.setBackground(new Color(55, 55, 55));
		button.setFocusPainted(true);
		button.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(new Color(75, 75, 75)),
			BorderFactory.createEmptyBorder(7, 12, 7, 12)));
		button.setAlignmentX(Component.LEFT_ALIGNMENT);
		return button;
	}
}

