	public static final class TimelineStepRow
	{
		public enum ActionType { TRAINING, PROCESS_STORED_SUPPLIES, QUEST, UNLOCK, ACQUISITION, UNRESOLVED }
		private final String skill;
		private final int fromLevel;
		private final int toLevel;
		private final String method;
		private final long requiredExperience;
		private final Double minimumHours;
		private final Double maximumHours;
		private final String priorityBlockId;
		private final int priorityBlockOrder;
		private final int stepOrder;
		private final boolean uncovered;
		private final ActionType actionType;
		private final String actionId;
		private final List<String> notes;

		public TimelineStepRow(String skill, int fromLevel, int toLevel, String method,
			long requiredExperience, Double minimumHours, Double maximumHours,
			String priorityBlockId, int priorityBlockOrder, int stepOrder, boolean uncovered)
		{
			this(skill, fromLevel, toLevel, method, requiredExperience, minimumHours, maximumHours,
				priorityBlockId, priorityBlockOrder, stepOrder,
				uncovered ? ActionType.UNRESOLVED : ActionType.TRAINING, "", Collections.emptyList());
		}

		public TimelineStepRow(String skill, int fromLevel, int toLevel, String method,
			long requiredExperience, Double minimumHours, Double maximumHours,
			String priorityBlockId, int priorityBlockOrder, int stepOrder,
			ActionType actionType, String actionId, List<String> notes)
		{
			this.skill = clean(skill, "Skill");
			this.fromLevel = Math.max(1, fromLevel);
			this.toLevel = Math.max(this.fromLevel, toLevel);
			this.actionType = actionType == null ? ActionType.UNRESOLVED : actionType;
			this.method = clean(method, this.actionType == ActionType.UNRESOLVED
				? "Route coverage required" : "Method not selected yet");
			this.requiredExperience = Math.max(0, requiredExperience);
			this.minimumHours = validHours(minimumHours);
			this.maximumHours = validHours(maximumHours);
			this.priorityBlockId = clean(priorityBlockId, this.skill.toLowerCase(java.util.Locale.ROOT));
			this.priorityBlockOrder = Math.max(1, priorityBlockOrder);
			this.stepOrder = Math.max(1, stepOrder);
			this.uncovered = this.actionType == ActionType.UNRESOLVED;
			this.actionId = clean(actionId, this.priorityBlockId + ":" + this.stepOrder);
			this.notes = immutableStrings(notes);
		}

		private static Double validHours(Double value)
		{
			return value == null || !Double.isFinite(value) || value < 0 ? null : value;
		}

