	public int getMaxedSkillCount()
	{
		int count = 0;
		for (SkillPlanRow skill : skillPlans)
		{
			if (skill.getLevel() >= 99 || skill.getRemainingExperience() == 0)
			{
				count++;
			}
		}
		return count;
	}

	public long getRemainingExperienceAfterBank()
	{
		long tenths = 0;
		for (SkillPlanRow skill : skillPlans)
		{
			long value = skill.getRemainingAfterBankTenths();
			tenths = Long.MAX_VALUE - tenths < value ? Long.MAX_VALUE : tenths + value;
		}
		return tenths / 10;
	}

	public int getReadyTimedTaskCount(long nowEpochMillis)
	{
		int count = 0;
		for (TimedTaskRow task : timedTasks)
		{
			String status = task.getDisplayStatus(nowEpochMillis);
			if (!task.isPaused() && !task.isComplete()
				&& ("Ready".equalsIgnoreCase(status)
					|| "Needs attention".equalsIgnoreCase(status)))
			{
				count++;
			}
		}
		return count;
	}

