			long requiredTenths = remainingExperience > Long.MAX_VALUE / 10 ? Long.MAX_VALUE
				: remainingExperience * 10;
			return requiredTenths == 0 ? 100 : (int) Math.min(100,
				Math.round(Math.min(requiredTenths, bankedExperienceTenths) * 100.0 / requiredTenths));
		}
	}

