	public static final class SupplyRow
	{
		private final String resource;
		private final long observed;
		private final long applied;
		private final long required;
		private final long missing;
		private final boolean tenths;

		public SupplyRow(String resource, long observed, long applied, long required, long missing)
		{
			this(resource, observed, applied, required, missing, false);
		}

		public SupplyRow(String resource, long observed, long applied, long required, long missing,
			boolean tenths)
		{
			this.resource = clean(resource, "Resource");
			this.observed = Math.max(0, observed);
			this.applied = Math.max(0, applied);
			this.required = Math.max(0, required);
			this.missing = Math.max(0, missing);
			this.tenths = tenths;
		}

		public String getResource() { return resource; }
		public long getObserved() { return observed; }
		public long getApplied() { return applied; }
		public long getRequired() { return required; }
		public long getMissing() { return missing; }
		public String formatObserved() { return format(observed); }
		public String formatApplied() { return format(applied); }
		public String formatRequired() { return format(required); }
		public String formatMissing() { return format(missing); }

		private String format(long value)
		{
			if (!tenths)
			{
				return String.format(java.util.Locale.ROOT, "%,d", value);
			}
			long whole = value / 10;
			return value % 10 == 0 ? String.format(java.util.Locale.ROOT, "%,d", whole)
				: String.format(java.util.Locale.ROOT, "%,d.%d", whole, value % 10);
		}
	}

	private static List<String> immutableStrings(List<String> values)
	{
		if (values == null)
		{
			return Collections.emptyList();
		}
		List<String> copy = new ArrayList<>();
		for (String value : values)
		{
			if (value != null && !value.trim().isEmpty())
			{
				copy.add(value.trim());
			}
		}
		return Collections.unmodifiableList(copy);
	}

	/** Display-ready recurring task. Timestamps and notification policy stay in the task engine. */
	public static final class TimedTaskRow
	{
		private final String id;
		private final String title;
		private final String status;
		private final String detail;
		private final Long dueAtEpochMillis;
		private final boolean paused;
		private final boolean completable;
		private final boolean supportsRemindLater;
		private final boolean supportsPause;

		public TimedTaskRow(String title, String status, String detail)
		{
			this(defaultId(title), title, status, detail, null,
				"paused".equalsIgnoreCase(clean(status, "")));
		}

		public TimedTaskRow(String id, String title, String status, String detail,
			Long dueAtEpochMillis, boolean paused)
		{
			this(id, title, status, detail, dueAtEpochMillis, paused, true, true);
		}

		public TimedTaskRow(String id, String title, String status, String detail,
			Long dueAtEpochMillis, boolean paused, boolean completable,
			boolean supportsRemindLater)
		{
			this(id, title, status, detail, dueAtEpochMillis, paused, completable,
				supportsRemindLater, true);
		}

		public TimedTaskRow(String id, String title, String status, String detail,
			Long dueAtEpochMillis, boolean paused, boolean completable,
			boolean supportsRemindLater, boolean supportsPause)
		{
			this.id = clean(id, defaultId(title));
			this.title = clean(title, "Recurring task");
			this.status = clean(status, "Not scheduled");
			this.detail = clean(detail, "No details available.");
			this.dueAtEpochMillis = dueAtEpochMillis;
			this.paused = paused;
			this.completable = completable;
			this.supportsRemindLater = supportsRemindLater;
			this.supportsPause = supportsPause;
		}

		public String getId()
		{
			return id;
		}

		public String getTitle()
		{
			return title;
		}

		public String getStatus()
		{
			return status;
		}

		public String getDetail()
		{
			return detail;
		}

		public Long getDueAtEpochMillis()
		{
			return dueAtEpochMillis;
		}

		public boolean isPaused()
		{
			return paused;
		}

		public boolean supportsPause()
		{
			return supportsPause;
		}

		public boolean isComplete()
		{
			return "complete".equalsIgnoreCase(status) || "completed".equalsIgnoreCase(status);
		}

		public boolean canComplete(long nowEpochMillis)
		{
			return completable && "Ready".equalsIgnoreCase(getDisplayStatus(nowEpochMillis));
		}

		public boolean canRemindLater(long nowEpochMillis)
		{
			String displayStatus = getDisplayStatus(nowEpochMillis);
			return supportsRemindLater && (("Needs attention".equalsIgnoreCase(displayStatus)
				&& (dueAtEpochMillis == null || dueAtEpochMillis <= nowEpochMillis))
				|| ("Ready".equalsIgnoreCase(displayStatus)
					&& (dueAtEpochMillis == null || dueAtEpochMillis <= nowEpochMillis)));
		}

		/** Returns the status at render time so an open window can transition to Ready. */
		public String getDisplayStatus(long nowEpochMillis)
		{
			if (isComplete())
			{
				return "Complete";
			}
			if (paused)
			{
				return "Paused";
			}
			if (dueAtEpochMillis != null && dueAtEpochMillis <= nowEpochMillis
				&& ("upcoming".equalsIgnoreCase(status) || "snoozed".equalsIgnoreCase(status)
					|| "growing".equalsIgnoreCase(status)
					|| "partially ready".equalsIgnoreCase(status)))
			{
				return "Ready";
			}
			return status;
		}

		private static String defaultId(String title)
		{
			String cleaned = clean(title, "recurring-task").toLowerCase(java.util.Locale.ROOT)
				.replaceAll("[^a-z0-9]+", "-").replaceAll("(^-|-$)", "");
			return cleaned.isEmpty() ? "recurring-task" : cleaned;
		}
	}

	private static String clean(String value, String fallback)
	{
		return value == null || value.trim().isEmpty() ? fallback : value.trim();
	}
}

package com.efficientskilling.integration;

import com.efficientskilling.planner.MethodExclusions;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.EnumMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Skill;
import net.runelite.client.config.ConfigManager;

/** Profile-scoped versioned persistence for explicitly avoided catalogue methods. */
@Singleton
public final class MethodExclusionStore
{
	static final String GROUP = "efficient-skilling";
	static final String KEY = "pathToMaxMethodExclusionsV1";
	private final ConfigManager configManager;

	@Inject public MethodExclusionStore(ConfigManager configManager) { this.configManager = configManager; }
	public MethodExclusions load() { return decode(configManager.getRSProfileConfiguration(GROUP, KEY)); }
	public void save(MethodExclusions exclusions)
	{
		StringBuilder stored = new StringBuilder("v1");
		exclusions.asMap().forEach((skill, methods) -> methods.forEach(method -> stored.append(';')
			.append(skill.name()).append('=').append(Base64.getUrlEncoder().withoutPadding()
				.encodeToString(method.getBytes(StandardCharsets.UTF_8)))));
		configManager.setRSProfileConfiguration(GROUP, KEY, stored.toString());
	}

	MethodExclusions decode(String stored)
	{
		Map<Skill, Set<String>> values = new EnumMap<>(Skill.class);
		if (stored == null) return MethodExclusions.none();
		String[] entries = stored.split(";");
		if (entries.length == 0 || !"v1".equals(entries[0])) return MethodExclusions.none();
		for (int index = 1; index < entries.length; index++)
		{
			String[] pair = entries[index].split("=", -1);
			try
			{
				if (pair.length != 2) continue;
				Skill skill = Skill.valueOf(pair[0]);
				String method = new String(Base64.getUrlDecoder().decode(pair[1]), StandardCharsets.UTF_8);
				if (!method.trim().isEmpty()) values.computeIfAbsent(skill, ignored -> new LinkedHashSet<>()).add(method);
			}
			catch (IllegalArgumentException ignored) { /* malformed or future value */ }
		}
		return new MethodExclusions(values);
	}
}

