import com.efficientskilling.vendor.bankedexperience.data.Activity;
import com.efficientskilling.vendor.bankedexperience.data.ExperienceItem;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;

/** Immutable, read-only view of Banked Experience's persisted choices. */
public final class BankedExperiencePreferenceSnapshot
{
	private final Map<ExperienceItem, Activity> activities;
	private final Set<ExperienceItem> ignoredItems;

	BankedExperiencePreferenceSnapshot(Map<ExperienceItem, Activity> activities,
		Set<ExperienceItem> ignoredItems)
	{
		EnumMap<ExperienceItem, Activity> activityCopy = new EnumMap<>(ExperienceItem.class);
		activityCopy.putAll(activities);
		this.activities = Collections.unmodifiableMap(activityCopy);
		this.ignoredItems = Collections.unmodifiableSet(ignoredItems.isEmpty()
			? EnumSet.noneOf(ExperienceItem.class) : EnumSet.copyOf(ignoredItems));
	}

	public Activity selectedActivity(ExperienceItem item, int level)
	{
		Activity selected = activities.get(item);
		if (selected != null) return selected;
		java.util.List<Activity> available = Activity.getByExperienceItem(item, level);
		return available.isEmpty() ? null : available.get(0);
	}

	public boolean isIgnored(ExperienceItem item) { return ignoredItems.contains(item); }
	public boolean hasExplicitActivity(ExperienceItem item) { return activities.containsKey(item); }
	public Map<ExperienceItem, Activity> getActivities() { return activities; }
	public Set<ExperienceItem> getIgnoredItems() { return ignoredItems; }

	public static BankedExperiencePreferenceSnapshot defaults()
	{
		return new BankedExperiencePreferenceSnapshot(Collections.emptyMap(), Collections.emptySet());
	}

	public static BankedExperiencePreferenceSnapshot of(Map<ExperienceItem, Activity> activities,
		Set<ExperienceItem> ignoredItems)
	{
		if (activities == null || ignoredItems == null) throw new IllegalArgumentException("preferences are required");
		return new BankedExperiencePreferenceSnapshot(activities, ignoredItems);
	}
}

package com.efficientskilling.integration;

import com.efficientskilling.vendor.bankedexperience.data.Activity;
import com.efficientskilling.vendor.bankedexperience.data.ExperienceItem;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;
import java.util.function.Function;
import javax.inject.Inject;
import net.runelite.client.config.ConfigManager;

/** Reads Banked Experience configuration without ever writing or mutating it. */
public final class BankedExperiencePreferences
{
	private static final String GROUP = "bankedexperience";
	private static final String ITEM_PREFIX = "ITEM_";
	private final ConfigManager configManager;

	@Inject
	public BankedExperiencePreferences(ConfigManager configManager) { this.configManager = configManager; }

	public BankedExperiencePreferenceSnapshot read()
	{
		return read(key -> configManager.getConfiguration(GROUP, key));
	}

	static BankedExperiencePreferenceSnapshot read(Function<String, String> lookup)
	{
		Map<ExperienceItem, Activity> selected = new EnumMap<>(ExperienceItem.class);
		Set<ExperienceItem> ignored = EnumSet.noneOf(ExperienceItem.class);
		String ignoredCsv = lookup.apply("ignoredItems");
		if (ignoredCsv != null)
		{
			for (String value : ignoredCsv.split(","))
			{
				try { ignored.add(ExperienceItem.valueOf(value.trim())); }
				catch (IllegalArgumentException ignoredInvalidValue) { /* foreign/old setting */ }
			}
		}
		for (ExperienceItem item : ExperienceItem.values())
		{
			String value = lookup.apply(ITEM_PREFIX + item.name());
			if (value == null || value.trim().isEmpty()) continue;
			try
			{
				Activity activity = Activity.valueOf(value.trim());
				if (Activity.getByExperienceItem(item).contains(activity)) selected.put(item, activity);
			}
			catch (IllegalArgumentException ignoredInvalidValue) { /* deterministic default is used */ }
		}
		return new BankedExperiencePreferenceSnapshot(selected, ignored);
	}
}

package com.efficientskilling.integration;

import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Skill;
import net.runelite.client.config.ConfigManager;

/** Profile-scoped last manual/live level snapshot for restoring the planner editor. */
@Singleton
public final class ManualStatsStore
{
	static final String GROUP = "efficient-skilling";
	static final String KEY = "pathToMaxManualLevelsV1";
	private final ConfigManager configManager;

	@Inject
	public ManualStatsStore(ConfigManager configManager) { this.configManager = configManager; }

	public Map<Skill, Integer> load()
	{
		return decode(configManager.getRSProfileConfiguration(GROUP, KEY));
	}

	public void save(Map<Skill, Integer> levels)
	{
		StringBuilder stored = new StringBuilder("v1");
		levels.entrySet().stream().sorted(Map.Entry.comparingByKey()).forEach(entry ->
		{
			if (entry.getKey() != null && entry.getValue() != null && !"OVERALL".equals(entry.getKey().name()))
			{
				stored.append(';').append(entry.getKey().name()).append('=')
					.append(Math.max(1, Math.min(99, entry.getValue())));
			}
		});
		configManager.setRSProfileConfiguration(GROUP, KEY, stored.toString());
	}

	Map<Skill, Integer> decode(String stored)
	{
		EnumMap<Skill, Integer> levels = new EnumMap<>(Skill.class);
		if (stored == null || stored.trim().isEmpty()) return Collections.emptyMap();
		String[] entries = stored.split(";");
		if (entries.length == 0 || !"v1".equals(entries[0])) return Collections.emptyMap();
		for (int index = 1; index < entries.length; index++)
		{
			String[] pair = entries[index].split("=", -1);
			if (pair.length != 2) continue;
			try
			{
				Skill skill = Skill.valueOf(pair[0]);
				int level = Integer.parseInt(pair[1]);
				if (!"OVERALL".equals(skill.name()) && level >= 1 && level <= 99) levels.put(skill, level);
			}
			catch (IllegalArgumentException ignored) { /* old, malformed, or future value */ }
		}
		return Collections.unmodifiableMap(levels);
	}
}

package com.efficientskilling.integration;

import com.efficientskilling.GuideStrategy;
import com.efficientskilling.planner.SkillStrategyPreferences;
import java.util.EnumMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Skill;
import net.runelite.client.config.ConfigManager;

/** Profile-scoped persistence for Path to Max skill-style overrides. */
@Singleton
public final class SkillStrategyPreferenceStore
{
	static final String GROUP = "efficient-skilling";
	static final String KEY = "pathToMaxSkillStrategiesV1";
	private final ConfigManager configManager;

	@Inject
	public SkillStrategyPreferenceStore(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	public SkillStrategyPreferences load(GuideStrategy defaultStrategy)
	{
		return decode(defaultStrategy, configManager.getRSProfileConfiguration(GROUP, KEY));
	}

	public void save(SkillStrategyPreferences preferences)
	{
		StringBuilder stored = new StringBuilder("v1;default=")
			.append(preferences.getDefaultStrategy().name());
		preferences.getOverrides().entrySet().stream().sorted(java.util.Map.Entry.comparingByKey())
			.forEach(entry -> stored.append(';').append(entry.getKey().name()).append('=')
				.append(entry.getValue().name()));
		configManager.setRSProfileConfiguration(GROUP, KEY, stored.toString());
	}

	SkillStrategyPreferences decode(GuideStrategy defaultStrategy, String json)
	{
		EnumMap<Skill, GuideStrategy> overrides = new EnumMap<>(Skill.class);
		if (json == null || json.trim().isEmpty()) return new SkillStrategyPreferences(defaultStrategy, overrides);
		String[] entries = json.split(";");
		if (entries.length == 0 || !"v1".equals(entries[0]))
		{
			return new SkillStrategyPreferences(defaultStrategy, overrides);
		}
		GuideStrategy storedDefault = defaultStrategy;
		for (int index = 1; index < entries.length; index++)
		{
			String[] pair = entries[index].split("=", -1);
			if (pair.length == 2)
			{
				try
				{
					if ("default".equals(pair[0])) storedDefault = GuideStrategy.valueOf(pair[1]);
					else overrides.put(Skill.valueOf(pair[0]), GuideStrategy.valueOf(pair[1]));
				}
				catch (IllegalArgumentException | NullPointerException ignored) { /* forward/legacy value */ }
			}
		}
		return new SkillStrategyPreferences(storedDefault, overrides);
	}
}

