package com.efficientskilling.planner;

import java.time.DateTimeException;
import java.time.Duration;
import java.time.Instant;
import java.util.Objects;

/**
 * Immutable, persistence-friendly state for a recurring Path to Max task.
 * Time values are stored as epoch milliseconds so the RuneLite-provided Gson
 * can serialize this class without a java.time type adapter.
 */
public final class TimedTaskState
{
	private final String id;
	private final String title;
	private final long intervalMillis;
	private final long targetCompletions;
	private final long completedCount;
	private final long nextDueAtEpochMillis;
	private final Long snoozedUntilEpochMillis;
	private final boolean disabled;
	private final Long lastNotifiedDueAtEpochMillis;

	public TimedTaskState(
		String id,
		String title,
		long intervalMillis,
		long targetCompletions,
		long completedCount,
		long nextDueAtEpochMillis,
		Long snoozedUntilEpochMillis,
		boolean disabled)
	{
		this(id, title, intervalMillis, targetCompletions, completedCount, nextDueAtEpochMillis,
			snoozedUntilEpochMillis, disabled, null);
	}

	public TimedTaskState(
		String id,
		String title,
		long intervalMillis,
		long targetCompletions,
		long completedCount,
		long nextDueAtEpochMillis,
		Long snoozedUntilEpochMillis,
		boolean disabled,
		Long lastNotifiedDueAtEpochMillis)
	{
		this.id = requireText(id, "id");
		this.title = requireText(title, "title");
		if (intervalMillis <= 0)
		{
			throw new IllegalArgumentException("intervalMillis must be positive");
		}
		if (targetCompletions <= 0)
		{
			throw new IllegalArgumentException("targetCompletions must be positive");
		}
		if (completedCount < 0 || completedCount > targetCompletions)
		{
			throw new IllegalArgumentException("completedCount must be between zero and the target");
		}
		this.intervalMillis = intervalMillis;
		this.targetCompletions = targetCompletions;
		this.completedCount = completedCount;
		this.nextDueAtEpochMillis = nextDueAtEpochMillis;
		this.snoozedUntilEpochMillis = snoozedUntilEpochMillis;
		this.disabled = disabled;
		this.lastNotifiedDueAtEpochMillis = lastNotifiedDueAtEpochMillis;
	}

	public static TimedTaskState create(String id, String title, Duration interval,
		long targetCompletions, Instant firstDueAt)
	{
		Objects.requireNonNull(interval, "interval");
		return new TimedTaskState(id, title, positiveMillis(interval), targetCompletions, 0,
			toEpochMillis(firstDueAt), null, false);
	}

	public TimedTaskState complete(Instant completedAt)
	{
		if (completedCount == targetCompletions)
		{
			return this;
		}
		long completedAtMillis = toEpochMillis(completedAt);
		long dueAt;
		try
		{
			dueAt = Math.addExact(completedAtMillis, intervalMillis);
		}
		catch (ArithmeticException ex)
		{
			throw new IllegalArgumentException("next due time is outside the supported range", ex);
		}
		return copy(completedCount + 1, dueAt, null, disabled, null);
	}

	public TimedTaskState snooze(Instant now, Duration duration)
	{
		Objects.requireNonNull(duration, "duration");
		if (duration.isNegative() || duration.isZero())
		{
			throw new IllegalArgumentException("snooze duration must be positive");
		}
		long until;
		try
		{
			long base = Math.max(toEpochMillis(now), effectiveDueAtEpochMillis());
			until = Math.addExact(base, positiveMillis(duration));
		}
		catch (ArithmeticException ex)
		{
			throw new IllegalArgumentException("snooze time is outside the supported range", ex);
		}
		return copy(completedCount, nextDueAtEpochMillis, until, disabled, null);
	}

	public TimedTaskState setDisabled(boolean disabled)
	{
		return this.disabled == disabled ? this : copy(completedCount, nextDueAtEpochMillis,
			snoozedUntilEpochMillis, disabled, lastNotifiedDueAtEpochMillis);
	}

	public TimedTaskState disable()
	{
		return setDisabled(true);
	}

	public TimedTaskState enable()
	{
		return setDisabled(false);
	}

	public TimedTaskStatus statusAt(Instant now)
	{
		long nowMillis = toEpochMillis(now);
		if (completedCount >= targetCompletions)
		{
			return TimedTaskStatus.COMPLETE;
		}
		if (disabled)
		{
			return TimedTaskStatus.DISABLED;
		}
		if (snoozedUntilEpochMillis != null
			&& snoozedUntilEpochMillis > nextDueAtEpochMillis
			&& snoozedUntilEpochMillis > nowMillis)
		{
			return TimedTaskStatus.SNOOZED;
		}
		return nextDueAtEpochMillis <= nowMillis ? TimedTaskStatus.READY : TimedTaskStatus.UPCOMING;
	}

	public boolean shouldNotifyAt(Instant now)
	{
		return statusAt(now) == TimedTaskStatus.READY
			&& !Long.valueOf(effectiveDueAtEpochMillis()).equals(lastNotifiedDueAtEpochMillis);
	}

	public TimedTaskState markNotified(Instant now)
	{
		if (!shouldNotifyAt(now))
		{
			return this;
		}
		return copy(completedCount, nextDueAtEpochMillis, snoozedUntilEpochMillis,
			disabled, effectiveDueAtEpochMillis());
	}

	public Duration remainingAt(Instant now)
	{
		long nowMillis = toEpochMillis(now);
		TimedTaskStatus status = statusAt(now);
		if (status == TimedTaskStatus.UPCOMING)
		{
			return Duration.ofMillis(nextDueAtEpochMillis - nowMillis);
		}
		if (status == TimedTaskStatus.SNOOZED)
		{
			return Duration.ofMillis(snoozedUntilEpochMillis - nowMillis);
		}
		return Duration.ZERO;
	}

	private long effectiveDueAtEpochMillis()
	{
		return snoozedUntilEpochMillis == null
			? nextDueAtEpochMillis
			: Math.max(nextDueAtEpochMillis, snoozedUntilEpochMillis);
	}

	private TimedTaskState copy(long completed, long dueAt, Long snoozedUntil, boolean isDisabled,
		Long lastNotifiedDueAt)
	{
		return new TimedTaskState(id, title, intervalMillis, targetCompletions, completed,
			dueAt, snoozedUntil, isDisabled, lastNotifiedDueAt);
	}

	private static long positiveMillis(Duration duration)
	{
		try
		{
			long millis = duration.toMillis();
			if (millis <= 0)
			{
				throw new IllegalArgumentException("duration must be at least one millisecond");
			}
			return millis;
		}
		catch (ArithmeticException ex)
		{
			throw new IllegalArgumentException("duration is outside the supported range", ex);
		}
	}

	private static long toEpochMillis(Instant instant)
	{
		Objects.requireNonNull(instant, "instant");
		try
		{
			return instant.toEpochMilli();
		}
		catch (ArithmeticException | DateTimeException ex)
		{
			throw new IllegalArgumentException("instant is outside the supported range", ex);
		}
	}

	private static String requireText(String value, String name)
	{
		if (value == null || value.trim().isEmpty())
		{
			throw new IllegalArgumentException(name + " is required");
		}
		return value;
	}

	public String getId() { return id; }
	public String getTitle() { return title; }
	public long getIntervalMillis() { return intervalMillis; }
	public Duration getInterval() { return Duration.ofMillis(intervalMillis); }
	public long getTargetCompletions() { return targetCompletions; }
	public long getCompletedCount() { return completedCount; }
	public long getNextDueAtEpochMillis() { return nextDueAtEpochMillis; }
	public Instant getNextDueAt() { return Instant.ofEpochMilli(nextDueAtEpochMillis); }
	public Long getSnoozedUntilEpochMillis() { return snoozedUntilEpochMillis; }
	public Instant getSnoozedUntil() { return snoozedUntilEpochMillis == null ? null : Instant.ofEpochMilli(snoozedUntilEpochMillis); }
	public boolean isDisabled() { return disabled; }
	public Long getLastNotifiedDueAtEpochMillis() { return lastNotifiedDueAtEpochMillis; }
}

package com.efficientskilling.planner;

import java.time.Instant;
import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;

/** Last observed resources; this is evidence, not a live view of the bank. */
public final class BankSnapshot
{
	private final Instant observedAt;
	private final Map<MaxingResource, Long> quantities;
	private final Map<MaxingResource, Map<Integer, Long>> provenance;
	private final Map<Integer, Long> items;

	public BankSnapshot(Instant observedAt, Map<MaxingResource, Long> quantities)
	{
		this(observedAt, quantities, Collections.emptyMap(), Collections.emptyMap());
	}

	public BankSnapshot(Instant observedAt, Map<MaxingResource, Long> quantities,
		Map<MaxingResource, Map<Integer, Long>> provenance)
	{
		this(observedAt, quantities, provenance, Collections.emptyMap());
	}

	public BankSnapshot(Instant observedAt, Map<MaxingResource, Long> quantities,
		Map<MaxingResource, Map<Integer, Long>> provenance, Map<Integer, Long> items)
	{
		if (observedAt == null || quantities == null || provenance == null || items == null)
		{
			throw new IllegalArgumentException("observation time and quantities are required");
		}
		EnumMap<MaxingResource, Long> copy = new EnumMap<>(MaxingResource.class);
		for (Map.Entry<MaxingResource, Long> entry : quantities.entrySet())
		{
			if (entry.getKey() == null || entry.getValue() == null || entry.getValue() < 0)
			{
				throw new IllegalArgumentException("resource quantities must be non-negative");
			}
			copy.put(entry.getKey(), entry.getValue());
		}
		this.observedAt = observedAt;
		this.quantities = Collections.unmodifiableMap(copy);
		EnumMap<MaxingResource, Map<Integer, Long>> provenanceCopy = new EnumMap<>(MaxingResource.class);
		for (Map.Entry<MaxingResource, Map<Integer, Long>> resource : provenance.entrySet())
		{
			if (resource.getKey() == null || resource.getValue() == null)
			{
				throw new IllegalArgumentException("resource provenance is required");
			}
			java.util.LinkedHashMap<Integer, Long> provenanceItems = new java.util.LinkedHashMap<>();
			for (Map.Entry<Integer, Long> item : resource.getValue().entrySet())
			{
				if (item.getKey() == null || item.getKey() < 0 || item.getValue() == null || item.getValue() < 0)
				{
					throw new IllegalArgumentException("provenance quantities must be non-negative");
				}
				provenanceItems.put(item.getKey(), item.getValue());
			}
			provenanceCopy.put(resource.getKey(), Collections.unmodifiableMap(provenanceItems));
		}
		this.provenance = Collections.unmodifiableMap(provenanceCopy);
		java.util.LinkedHashMap<Integer, Long> itemCopy = new java.util.LinkedHashMap<>();
		for (Map.Entry<Integer, Long> item : items.entrySet())
		{
			if (item.getKey() == null || item.getKey() < 0 || item.getValue() == null || item.getValue() < 0)
			{
				throw new IllegalArgumentException("item quantities must be non-negative");
			}
			itemCopy.put(item.getKey(), item.getValue());
		}
		this.items = Collections.unmodifiableMap(itemCopy);
	}

	public Instant getObservedAt()
	{
		return observedAt;
	}

	public long quantity(MaxingResource resource)
	{
		return quantities.getOrDefault(resource, 0L);
	}

	/** Canonical item ids and quantities that contributed to a mapped resource. */
	public Map<Integer, Long> provenance(MaxingResource resource)
	{
		return provenance.getOrDefault(resource, Collections.emptyMap());
	}

	/** All captured canonical items, used by generic banked-XP adapters. */
	public Map<Integer, Long> getItems() { return items; }
}

package com.efficientskilling.planner;

import com.efficientskilling.AccountProfile;
import com.efficientskilling.Guide;
import com.efficientskilling.GuideService;
import com.efficientskilling.GuideStep;
import com.efficientskilling.GuideStrategy;
import com.efficientskilling.planner.bankedxp.SkillBankedExperienceProjection;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import com.efficientskilling.RequirementItem;

/** Builds the full path to max exclusively from GuideService's reviewed catalogue. */
@Singleton
public final class WholeAccountPlanner
{
	private final GuideService guideService;

	@Inject
	public WholeAccountPlanner(GuideService guideService)
	{
		this.guideService = guideService;
	}

	public WholeAccountPlan build(AccountStats stats,
		Map<Skill, SkillBankedExperienceProjection> bankedExperience,
		AccountProfile account, GuideStrategy strategy)
	{
		return build(stats, bankedExperience, account, strategy, java.util.Collections.emptyMap());
	}

	public WholeAccountPlan build(AccountStats stats,
		Map<Skill, SkillBankedExperienceProjection> bankedExperience,
		AccountProfile account, GuideStrategy strategy, Map<Quest, QuestState> questStates)
	{
		return build(stats, bankedExperience, account, strategy, questStates,
			java.util.Collections.emptyMap());
	}

	public WholeAccountPlan build(AccountStats stats,
		Map<Skill, SkillBankedExperienceProjection> bankedExperience,
		AccountProfile account, GuideStrategy strategy, Map<Quest, QuestState> questStates,
		Map<RequirementItem, Long> ownedItems)
	{
		return build(stats, bankedExperience, account, strategy, questStates, ownedItems, true);
	}

	public WholeAccountPlan build(AccountStats stats,
		Map<Skill, SkillBankedExperienceProjection> bankedExperience,
		AccountProfile account, GuideStrategy strategy, Map<Quest, QuestState> questStates,
		Map<RequirementItem, Long> ownedItems, boolean storageEvidenceKnown)
	{
		return build(stats, bankedExperience, account, SkillStrategyPreferences.all(strategy),
			questStates, ownedItems, storageEvidenceKnown);
	}

	public WholeAccountPlan build(AccountStats stats,
		Map<Skill, SkillBankedExperienceProjection> bankedExperience,
		AccountProfile account, SkillStrategyPreferences strategies, Map<Quest, QuestState> questStates,
		Map<RequirementItem, Long> ownedItems, boolean storageEvidenceKnown)
	{
		return build(stats, bankedExperience, account, strategies, questStates, ownedItems,
			storageEvidenceKnown, MethodExclusions.none());
	}

	public WholeAccountPlan build(AccountStats stats,
		Map<Skill, SkillBankedExperienceProjection> bankedExperience,
		AccountProfile account, SkillStrategyPreferences strategies, Map<Quest, QuestState> questStates,
		Map<RequirementItem, Long> ownedItems, boolean storageEvidenceKnown,
		MethodExclusions exclusions)
	{
		if (stats == null || bankedExperience == null || account == null || strategies == null
			|| questStates == null || ownedItems == null || exclusions == null)
		{
			throw new IllegalArgumentException("whole-account plan inputs are required");
		}

		Map<Skill, SkillBankedExperienceProjection> projections = new EnumMap<>(Skill.class);
		projections.putAll(bankedExperience);
		List<SkillProgression> progressions = new ArrayList<>();
		for (Skill skill : Skill.values())
		{
			if (guideService.hasData(skill))
			{
				progressions.add(buildSkill(skill, stats, projections.get(skill), account,
					strategies.strategyFor(skill), exclusions));
			}
		}

		// Put the largest remaining grinds first; Skill ordinal makes ties reproducible.
		progressions.sort(Comparator.comparingInt(SkillProgression::getRemainingExperience)
			.reversed().thenComparingInt(value -> value.getSkill().ordinal()));
		return new WholeAccountPlan(account, strategies.getDefaultStrategy(), progressions,
			new DependencyTimelineScheduler(progressions, questStates, ownedItems,
				storageEvidenceKnown).schedule(progressions));
	}

	private SkillProgression buildSkill(Skill skill, AccountStats stats,
		SkillBankedExperienceProjection projection, AccountProfile account, GuideStrategy strategy,
		MethodExclusions exclusions)
	{
		int currentXp = Math.min(AccountStats.XP_FOR_99, stats.getExperience(skill));
		int bankedXp = projection == null ? 0 : projection.getUsableExperience()
			.setScale(0, RoundingMode.FLOOR).min(java.math.BigDecimal.valueOf(Integer.MAX_VALUE)).intValue();
		bankedXp = Math.min(bankedXp, AccountStats.XP_FOR_99 - currentXp);
		int effectiveXp = currentXp + bankedXp;
		int remainingXp = AccountStats.XP_FOR_99 - effectiveXp;
		// Stored supplies are potential work, not an earned level. Route selection and typed
		// prerequisites must therefore start from the account's actual experience.
		int startingLevel = Math.min(99, Experience.getLevelForXp(currentXp));
		Guide guide = guideService.buildGuide(skill, startingLevel, 99, account, strategy, exclusions);
		List<SkillProgressionStep> steps = new ArrayList<>();
		int segmentStartXp = currentXp;
		for (GuideStep guideStep : guide.getSteps())
		{
			int segmentEndXp = Experience.getXpForLevel(guideStep.getToLevel());
			steps.add(new SkillProgressionStep(guideStep.getFromLevel(), guideStep.getToLevel(),
				Math.max(0, segmentEndXp - segmentStartXp), guideStep.getMethod()));
			segmentStartXp = segmentEndXp;
		}
		return new SkillProgression(skill, strategy, currentXp, bankedXp, effectiveXp, remainingXp,
			steps, guide.getUncoveredLevel());
	}
}

package com.efficientskilling.planner;

import com.efficientskilling.GuideStrategy;
import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import java.util.Objects;
import net.runelite.api.Skill;

/** Immutable global strategy plus the skills which explicitly override it. */
public final class SkillStrategyPreferences
{
	private final GuideStrategy defaultStrategy;
	private final Map<Skill, GuideStrategy> overrides;

	public SkillStrategyPreferences(GuideStrategy defaultStrategy,
		Map<Skill, GuideStrategy> overrides)
	{
		this.defaultStrategy = Objects.requireNonNull(defaultStrategy, "defaultStrategy");
		EnumMap<Skill, GuideStrategy> copy = new EnumMap<>(Skill.class);
		if (overrides != null)
		{
			overrides.forEach((skill, strategy) ->
			{
				if (skill != null && strategy != null && strategy != defaultStrategy)
				{
					copy.put(skill, strategy);
				}
			});
		}
		this.overrides = Collections.unmodifiableMap(copy);
	}

	public static SkillStrategyPreferences all(GuideStrategy strategy)
	{
		return new SkillStrategyPreferences(strategy, Collections.emptyMap());
	}

	public GuideStrategy getDefaultStrategy() { return defaultStrategy; }
	public GuideStrategy strategyFor(Skill skill)
	{
		return overrides.getOrDefault(Objects.requireNonNull(skill, "skill"), defaultStrategy);
	}
	public boolean isOverridden(Skill skill) { return overrides.containsKey(skill); }
	public Map<Skill, GuideStrategy> getOverrides() { return overrides; }

	public SkillStrategyPreferences withDefault(GuideStrategy strategy)
	{
		return new SkillStrategyPreferences(strategy, overrides);
	}

	public SkillStrategyPreferences withOverride(Skill skill, GuideStrategy strategy)
	{
		EnumMap<Skill, GuideStrategy> changed = new EnumMap<>(Skill.class);
		changed.putAll(overrides);
		if (strategy == null || strategy == defaultStrategy) changed.remove(skill);
		else changed.put(Objects.requireNonNull(skill, "skill"), strategy);
		return new SkillStrategyPreferences(defaultStrategy, changed);
	}

	public SkillStrategyPreferences withoutOverride(Skill skill)
	{
		return withOverride(skill, null);
	}

	@Override
	public boolean equals(Object other)
	{
		if (this == other) return true;
		if (!(other instanceof SkillStrategyPreferences)) return false;
		SkillStrategyPreferences that = (SkillStrategyPreferences) other;
		return defaultStrategy == that.defaultStrategy && overrides.equals(that.overrides);
	}

	@Override
	public int hashCode() { return Objects.hash(defaultStrategy, overrides); }
}

package com.efficientskilling.planner;

import java.util.Collections;
import java.util.EnumMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Skill;

/** Immutable user exclusions keyed by the method's primary skill and catalogue name. */
public final class MethodExclusions
{
	private final Map<Skill, Set<String>> values;

	public MethodExclusions(Map<Skill, ? extends Set<String>> values)
	{
		EnumMap<Skill, Set<String>> copy = new EnumMap<>(Skill.class);
		if (values != null) values.forEach((skill, names) ->
		{
			LinkedHashSet<String> clean = new LinkedHashSet<>();
			if (names != null) names.stream().filter(name -> name != null && !name.trim().isEmpty())
				.map(String::trim).sorted().forEach(clean::add);
			if (skill != null && !clean.isEmpty()) copy.put(skill, Collections.unmodifiableSet(clean));
		});
		this.values = Collections.unmodifiableMap(copy);
	}

	public static MethodExclusions none() { return new MethodExclusions(Collections.emptyMap()); }
	public boolean excludes(Skill skill, String method) { return values.getOrDefault(skill, Collections.emptySet()).contains(method); }
	public Set<String> forSkill(Skill skill) { return values.getOrDefault(skill, Collections.emptySet()); }
	public Map<Skill, Set<String>> asMap() { return values; }
	public boolean isEmpty() { return values.isEmpty(); }
	public MethodExclusions only(Skill skill)
	{
		Set<String> methods = forSkill(skill);
		return methods.isEmpty() ? none()
			: new MethodExclusions(Collections.singletonMap(skill, methods));
	}

	public MethodExclusions withExcluded(Skill skill, String method)
	{
		EnumMap<Skill, Set<String>> changed = mutableCopy();
		changed.computeIfAbsent(skill, ignored -> new LinkedHashSet<>()).add(method.trim());
		return new MethodExclusions(changed);
	}

	public MethodExclusions without(Skill skill, String method)
	{
		EnumMap<Skill, Set<String>> changed = mutableCopy();
		Set<String> names = changed.get(skill);
		if (names != null) names.remove(method);
		return new MethodExclusions(changed);
	}

	private EnumMap<Skill, Set<String>> mutableCopy()
	{
		EnumMap<Skill, Set<String>> copy = new EnumMap<>(Skill.class);
		values.forEach((skill, names) -> copy.put(skill, new LinkedHashSet<>(names)));
		return copy;
	}
}

package com.efficientskilling.planner;

import com.efficientskilling.MethodDependency;
import com.efficientskilling.MethodDependencyType;
import com.efficientskilling.TrainingMethod;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import com.efficientskilling.RequirementItem;

/** Schedules validated typed dependencies while retaining deterministic catalogue fallback. */
final class DependencyTimelineScheduler
{
	private final Map<Skill, Cursor> cursors = new EnumMap<>(Skill.class);
	private final List<PlanTimelineStep> result = new ArrayList<>();
	private final Set<String> emittedManualActions = new LinkedHashSet<>();
	private final Set<String> emittedProblems = new LinkedHashSet<>();
	private final Set<Skill> activeSkills = new HashSet<>();
	private int blockOrder;
	private int stepOrder;
	private String blockId;
	private final Map<Quest, QuestState> questStates;
	private final Map<RequirementItem, Long> ownedItems;
	private final boolean storageEvidenceKnown;

	DependencyTimelineScheduler(List<SkillProgression> progressions, Map<Quest, QuestState> questStates,
		Map<RequirementItem, Long> ownedItems, boolean storageEvidenceKnown)
	{
		this.questStates = new java.util.EnumMap<>(Quest.class);
		this.questStates.putAll(questStates);
		this.ownedItems = new java.util.EnumMap<>(RequirementItem.class);
		this.ownedItems.putAll(ownedItems);
		this.storageEvidenceKnown = storageEvidenceKnown;
		for (SkillProgression progression : progressions)
		{
			cursors.put(progression.getSkill(), new Cursor(progression));
		}
	}

	List<PlanTimelineStep> schedule(List<SkillProgression> priorityOrder)
	{
		for (SkillProgression progression : priorityOrder)
		{
			if (progression.isComplete()) continue;
			blockOrder++;
			blockId = progression.getSkill().name().toLowerCase(java.util.Locale.ROOT);
			scheduleSkillTo(progression.getSkill(), 99);
		}
		return result;
	}

	private void scheduleSkillTo(Skill skill, int targetLevel)
	{
		Cursor cursor = cursors.get(skill);
		if (cursor == null)
		{
			emitProblem(skill, targetLevel, "No reviewed route exists for the required skill.",
				"missing-skill:" + skill);
			return;
		}
		int targetXp = targetLevel >= 99 ? AccountStats.XP_FOR_99 : Experience.getXpForLevel(targetLevel);
		if (cursor.currentXp >= targetXp) return;
		if (!activeSkills.add(skill))
		{
			emitProblem(skill, targetLevel, "Dependency cycle detected; review this prerequisite manually.",
				"cycle:" + skill + ":" + targetLevel);
			return;
		}
		try
		{
			processStoredSupplies(skill, cursor, targetXp);
			while (cursor.currentXp < targetXp)
			{
				SkillProgressionStep segment = cursor.currentSegment();
				if (segment == null)
				{
					int level = cursor.progression.getUncoveredLevel() == null
						? Experience.getLevelForXp(cursor.currentXp)
						: cursor.progression.getUncoveredLevel();
					emitProblem(skill, level, "Reviewed route coverage is missing from this level.",
						"uncovered:" + skill + ":" + level);
					return;
				}
				TrainingMethod method = segment.getMethod();
				for (MethodDependency dependency : method.getDependencies())
				{
					if (!dependency.isMandatory()) continue;
					if (dependency.getType() == MethodDependencyType.SKILL_LEVEL)
					{
						scheduleSkillTo(dependency.getSkill(), dependency.getLevel());
					}
					else if (dependency.getType() == MethodDependencyType.ITEM_OWNED)
					{
						if (!storageEvidenceKnown)
						{
							emitProblem(skill, Experience.getLevelForXp(cursor.currentXp),
								"Open the Bank or relevant storage to verify: " + dependency.getLabel(),
								"unknown-item:" + dependency.getItem());
						}
						else if (ownedItems.getOrDefault(dependency.getItem(), 0L) < dependency.getQuantity())
						{
							emitManual(dependency, skill);
						}
					}
					else if (dependency.getType() != MethodDependencyType.QUEST_COMPLETED
						|| questStates.get(dependency.getQuest()) != QuestState.FINISHED)
					{
						emitManual(dependency, skill);
					}
				}

				int amount = Math.min(cursor.segmentRemaining, targetXp - cursor.currentXp);
				int endXp = cursor.currentXp + amount;
				List<String> notes = new ArrayList<>(method.getRequirements());
				for (MethodDependency dependency : method.getDependencies())
				{
					if (!dependency.isMandatory()) notes.add("Optional: " + dependency.getLabel());
				}
				result.add(new PlanTimelineStep(skill, Experience.getLevelForXp(cursor.currentXp),
					Math.min(99, Experience.getLevelForXp(endXp)), method.getName(), amount,
					hours(amount, method.getXpPerHourHigh()), hours(amount, method.getXpPerHourLow()),
					blockId, blockOrder, ++stepOrder, TimelineActionType.TRAINING,
					"training:" + skill + ":" + cursor.segmentIndex, notes));
				cursor.currentXp = endXp;
				cursor.segmentRemaining -= amount;
				if (cursor.segmentRemaining == 0) cursor.advance();
			}
		}
		finally
		{
			activeSkills.remove(skill);
		}
	}

	private void processStoredSupplies(Skill skill, Cursor cursor, int targetXp)
	{
		while (cursor.bankedRemaining > 0 && cursor.currentXp < targetXp)
		{
			SkillProgressionStep segment = cursor.currentSegment();
			if (segment == null)
			{
				return;
			}
			int amount = Math.min(cursor.bankedRemaining,
				Math.min(cursor.segmentRemaining, targetXp - cursor.currentXp));
			if (amount <= 0)
			{
				return;
			}
			int startXp = cursor.currentXp;
			int endXp = startXp + amount;
			result.add(new PlanTimelineStep(skill, Experience.getLevelForXp(startXp),
				Math.min(99, Experience.getLevelForXp(endXp)), "Process stored supplies", amount,
				null, null, blockId, blockOrder, ++stepOrder,
				TimelineActionType.PROCESS_STORED_SUPPLIES,
				"stored-supplies:" + skill + ":" + cursor.segmentIndex,
				Collections.singletonList("Use the currently usable stored-XP conversion before relying on the resulting levels.")));
			cursor.currentXp = endXp;
			cursor.bankedRemaining -= amount;
			cursor.segmentRemaining -= amount;
			if (cursor.segmentRemaining == 0) cursor.advance();
		}
	}

	private void emitManual(MethodDependency dependency, Skill dependentSkill)
	{
		String dependencyId = dependency.getType() == MethodDependencyType.QUEST_COMPLETED
			? dependency.getQuest().name() : dependency.getType() == MethodDependencyType.ITEM_OWNED
				? dependency.getItem().name() : dependency.getId();
		String identity = dependency.getType() + ":" + dependencyId;
		if (!emittedManualActions.add(identity)) return;
		TimelineActionType type = dependency.getType() == MethodDependencyType.QUEST_COMPLETED
			? TimelineActionType.QUEST : dependency.getType() == MethodDependencyType.UNLOCK
				? TimelineActionType.UNLOCK : TimelineActionType.ACQUISITION;
		result.add(new PlanTimelineStep(dependency.getSkill() == null ? dependentSkill : dependency.getSkill(),
			0, 0, dependency.getLabel(), 0, null, null, blockId, blockOrder, ++stepOrder,
			type, dependencyId, Collections.emptyList()));
	}

	private void emitProblem(Skill skill, int level, String message, String identity)
	{
		if (!emittedProblems.add(identity)) return;
		result.add(new PlanTimelineStep(skill, Math.max(1, level), Math.max(1, level), message,
			0, null, null, blockId == null ? skill.name().toLowerCase(java.util.Locale.ROOT) : blockId,
			Math.max(1, blockOrder), ++stepOrder, TimelineActionType.UNRESOLVED, identity,
			Collections.emptyList()));
	}

	private static Double hours(int xp, Integer rate)
	{
		return rate == null ? null : (double) xp / rate;
	}

	private static final class Cursor
	{
		private final SkillProgression progression;
		private int currentXp;
		private int segmentIndex;
		private int segmentRemaining;
		private int bankedRemaining;

		private Cursor(SkillProgression progression)
		{
			this.progression = progression;
			this.currentXp = progression.getCurrentExperience();
			this.bankedRemaining = progression.getCreditedBankedExperience();
			this.segmentRemaining = progression.getSteps().isEmpty() ? 0
				: progression.getSteps().get(0).getExperienceRequired();
		}

		private SkillProgressionStep currentSegment()
		{
			return segmentIndex >= progression.getSteps().size() ? null
				: progression.getSteps().get(segmentIndex);
		}

		private void advance()
		{
			segmentIndex++;
			segmentRemaining = segmentIndex >= progression.getSteps().size() ? 0
				: progression.getSteps().get(segmentIndex).getExperienceRequired();
		}
	}
}

