package com.efficientskilling.planner.bankedxp;

public enum ActivitySelectionSource
{
	EXPLICIT,
	DEFAULT
}

package com.efficientskilling.planner.bankedxp;

import com.efficientskilling.integration.BankedExperiencePreferenceSnapshot;
import com.efficientskilling.vendor.bankedexperience.data.Activity;
import com.efficientskilling.vendor.bankedexperience.data.ExperienceItem;
import com.efficientskilling.vendor.bankedexperience.data.ItemStack;
import com.efficientskilling.vendor.bankedexperience.data.Secondaries;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.List;
import java.util.EnumSet;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.Skill;

/** Generic theoretical-XP calculator over the vendored all-skill activity graph. */
public final class BankedExperienceCalculator
{
	public SkillBankedExperienceProjection project(Skill skill, Map<Integer, Long> items, int level,
		long currentExperience, long targetExperience, BankedExperiencePreferenceSnapshot preferences)
	{
		validate(skill, items, preferences);
		List<ResourceConversion> conversions = new ArrayList<>();
		for (Map.Entry<Integer, Long> entry : normalizeStartingResources(skill, items).entrySet())
		{
			validateEntry(entry);
			ExperienceItem item = findItem(skill, entry.getKey());
			if (item == null || entry.getValue() == 0) continue;
			// Finished potion doses are only training resources when the player explicitly
			// selected an upgrade conversion in Banked Experience. They are not part of the
			// normal herb -> unfinished potion -> finished potion training path.
			if (item.isByDose() && !preferences.hasExplicitActivity(item)) continue;
			// A path-to-99 projection chooses defaults from the target-level catalog, while
			// status below still records whether the account can use the full chain now.
			Activity selected = preferences.selectedActivity(item, 99);
			ActivitySelectionSource source = preferences.hasExplicitActivity(item)
				? ActivitySelectionSource.EXPLICIT : ActivitySelectionSource.DEFAULT;
			ConversionStatus status;
			CalculationKind kind = CalculationKind.EXACT;
			BigDecimal xp = BigDecimal.ZERO;
			List<String> warnings = new ArrayList<>();
			if (preferences.isIgnored(item)) status = ConversionStatus.IGNORED;
			else if (selected == null)
			{
				status = ConversionStatus.UNSUPPORTED;
				warnings.add("No selected or default activity is available");
			}
			else
			{
				UnitProjection unit = projectUnit(item, selected, level, preferences,
					EnumSet.noneOf(ExperienceItem.class));
				status = unit.unsupported ? ConversionStatus.UNSUPPORTED
					: unit.requiredLevel > level ? ConversionStatus.LEVEL_LOCKED : ConversionStatus.USABLE;
				kind = unit.expected ? CalculationKind.EXPECTED : CalculationKind.EXACT;
				xp = unit.unsupported ? BigDecimal.ZERO
					: unit.experience.multiply(BigDecimal.valueOf(entry.getValue()));
				warnings.addAll(unit.warnings);
			}
			conversions.add(new ResourceConversion(item, entry.getValue(), selected, source, status, kind, xp, warnings));
		}
		return new SkillBankedExperienceProjection(skill, BigDecimal.valueOf(currentExperience),
			BigDecimal.valueOf(targetExperience), conversions);
	}

	public BankedExperienceResult calculate(Skill skill, Map<Integer, Long> items, int level,
		BankedExperiencePreferenceSnapshot preferences)
	{
		validate(skill, items, preferences);
		BigDecimal exactXp = BigDecimal.ZERO;
		long valued = 0;
		Map<Integer, BigDecimal> exactSecondaries = new LinkedHashMap<>();
		BigDecimal degrimeHerbs = BigDecimal.ZERO;
		for (Map.Entry<Integer, Long> entry : normalizeStartingResources(skill, items).entrySet())
		{
			validateEntry(entry);
			ExperienceItem item = findItem(skill, entry.getKey());
			if (item == null || entry.getValue() == 0 || preferences.isIgnored(item)) continue;
			UnitResult unit = calculateUnit(item, level, preferences, EnumSet.noneOf(ExperienceItem.class));
			exactXp = exactXp.add(unit.experience.multiply(BigDecimal.valueOf(entry.getValue())));
			valued = Math.addExact(valued, entry.getValue());
			for (Map.Entry<Integer, BigDecimal> need : unit.secondaryNeeds.entrySet())
				exactSecondaries.merge(need.getKey(), need.getValue().multiply(BigDecimal.valueOf(entry.getValue())), BigDecimal::add);
			degrimeHerbs = degrimeHerbs.add(unit.degrimeHerbs.multiply(BigDecimal.valueOf(entry.getValue())));
		}
		if (degrimeHerbs.signum() > 0)
		{
			BigDecimal casts = degrimeHerbs.divide(BigDecimal.valueOf(27), 0, RoundingMode.CEILING);
			exactSecondaries.merge(net.runelite.api.gameval.ItemID.NATURERUNE,
				casts.multiply(BigDecimal.valueOf(2)), BigDecimal::add);
		}
		Map<Integer, Long> secondaries = new LinkedHashMap<>();
		for (Map.Entry<Integer, BigDecimal> need : exactSecondaries.entrySet())
			secondaries.put(need.getKey(), need.getValue().setScale(0, RoundingMode.CEILING).longValueExact());
		Map<Integer, Long> missing = new LinkedHashMap<>();
		for (Map.Entry<Integer, Long> need : secondaries.entrySet())
		{
			long deficit = Math.max(0, need.getValue() - availableEquivalent(need.getKey(), items));
			if (deficit > 0) missing.put(need.getKey(), deficit);
		}
		long xpTenths = exactXp.movePointRight(1).setScale(0, RoundingMode.HALF_UP).longValueExact();
		return new BankedExperienceResult(xpTenths, valued, secondaries, missing);
	}

	private static long availableEquivalent(int requiredId, Map<Integer, Long> items)
	{
		for (Secondaries secondary : Secondaries.values())
		{
			Secondaries.SecondaryHandler handler = secondary.getCustomHandler();
			if (handler instanceof Secondaries.Crushable)
			{
				int[] ids = ((Secondaries.Crushable) handler).getItems();
				if (ids[ids.length - 1] == requiredId)
				{
					long total = 0;
					for (int id : ids) total = Math.addExact(total, items.getOrDefault(id, 0L));
					return total;
				}
			}
			else if (handler instanceof Secondaries.ByDose)
			{
				int[] ids = ((Secondaries.ByDose) handler).getItems();
				if (ids[0] == requiredId)
				{
					long doses = 0;
					for (int i = 0; i < ids.length; i++)
						doses = Math.addExact(doses, Math.multiplyExact(items.getOrDefault(ids[i], 0L), i + 1L));
					return doses;
				}
			}
		}
		return items.getOrDefault(requiredId, 0L);
	}

	private static Map<Integer, Long> normalizeStartingResources(Skill skill, Map<Integer, Long> items)
	{
		Map<Integer, Long> normalized = new LinkedHashMap<>();
		for (Map.Entry<Integer, Long> entry : items.entrySet())
		{
			validateEntry(entry);
			ExperienceItem item = findItem(skill, entry.getKey());
			if (item == null || !item.isByDose())
			{
				normalized.merge(entry.getKey(), entry.getValue(), Math::addExact);
				continue;
			}
			int dose = 0;
			int[] ids = item.getItemIds();
			for (int i = 0; i < ids.length; i++) if (ids[i] == entry.getKey()) dose = i + 1;
			normalized.merge(item.getItemID(), Math.multiplyExact(entry.getValue(), dose), Math::addExact);
		}
		return normalized;
	}

	private static void validate(Skill skill, Map<Integer, Long> items,
		BankedExperiencePreferenceSnapshot preferences)
	{
		if (skill == null || items == null || preferences == null) throw new IllegalArgumentException("inputs are required");
	}

	private static void validateEntry(Map.Entry<Integer, Long> entry)
	{
		if (entry.getKey() == null || entry.getValue() == null || entry.getValue() < 0)
			throw new IllegalArgumentException("item quantities must be non-negative");
	}

	private static ExperienceItem findItem(Skill skill, int itemId)
	{
		for (ExperienceItem candidate : ExperienceItem.getBySkill(skill))
			for (int candidateId : candidate.getItemIds())
				if (candidateId == itemId) return candidate;
		return null;
	}

	private static UnitProjection projectUnit(ExperienceItem item, Activity activity, int level,
		BankedExperiencePreferenceSnapshot preferences, EnumSet<ExperienceItem> path)
	{
		UnitProjection result = new UnitProjection();
		if (!path.add(item))
		{
			result.unsupported = true;
			result.warnings.add("Cyclic linked activity");
			return result;
		}
		result.experience = BigDecimal.valueOf(activity.getXp());
		result.requiredLevel = activity.getLevel();
		result.expected = activity.isRngActivity();
		if (activity.getSecondaries() != null && activity.getSecondaries().getCustomHandler() != null)
		{
			Secondaries.SecondaryHandler handler = activity.getSecondaries().getCustomHandler();
			if (handler instanceof Secondaries.ByDose)
				result.warnings.add("Potion doses are combined across dose sizes");
			else if (handler instanceof Secondaries.Crushable)
				result.warnings.add("Crushed and uncrushed items are treated as equivalent");
			else if (handler instanceof Secondaries.Degrime)
				result.warnings.add("Nature runes assume full 27-herb Degrime casts");
			else
			{
				result.unsupported = true;
				result.warnings.add("Unknown custom secondary handling");
			}
		}
		if (activity.getLinkedItem() != null)
		{
			ExperienceItem linkedItem = activity.getLinkedItem();
			if (preferences.isIgnored(linkedItem))
			{
				result.warnings.add("The ignored linked resource ends this conversion chain");
			}
			else
			{
				Activity linkedActivity = preferences.selectedActivity(linkedItem, 99);
				if (linkedActivity == null)
				{
					result.warnings.add("The unavailable linked activity ends this conversion chain");
				}
				else
				{
					UnitProjection linked = projectUnit(linkedItem, linkedActivity, level, preferences, path);
					BigDecimal output = activity.getOutput() == null ? BigDecimal.ONE
						: BigDecimal.valueOf(activity.getOutput().getQty());
					result.experience = result.experience.add(output.multiply(linked.experience));
					result.expected |= linked.expected;
					result.requiredLevel = Math.max(result.requiredLevel, linked.requiredLevel);
					result.unsupported |= linked.unsupported;
					result.warnings.addAll(linked.warnings);
				}
			}
		}
		return result;
	}

	private static UnitResult calculateUnit(ExperienceItem item, int level,
		BankedExperiencePreferenceSnapshot preferences, EnumSet<ExperienceItem> path)
	{
		if (!path.add(item) || preferences.isIgnored(item)) return new UnitResult();
		Activity activity = preferences.selectedActivity(item, level);
		if (activity == null) return new UnitResult();
		UnitResult result = new UnitResult();
		result.experience = BigDecimal.valueOf(activity.getXp());
		addSecondaries(result.secondaryNeeds, activity.getSecondaries());
		if (activity.getSecondaries() != null
			&& activity.getSecondaries().getCustomHandler() instanceof Secondaries.Degrime)
			result.degrimeHerbs = BigDecimal.ONE;
		if (activity.getLinkedItem() != null)
		{
			UnitResult linked = calculateUnit(activity.getLinkedItem(), level, preferences, path);
			BigDecimal output = activity.getOutput() == null ? BigDecimal.ONE
				: BigDecimal.valueOf(activity.getOutput().getQty());
			result.experience = result.experience.add(output.multiply(linked.experience));
			for (Map.Entry<Integer, BigDecimal> need : linked.secondaryNeeds.entrySet())
				result.secondaryNeeds.merge(need.getKey(), need.getValue().multiply(output), BigDecimal::add);
			result.degrimeHerbs = result.degrimeHerbs.add(linked.degrimeHerbs.multiply(output));
		}
		return result;
	}

	private static void addSecondaries(Map<Integer, BigDecimal> needs, Secondaries secondary)
	{
		if (secondary == null) return;
		for (ItemStack stack : secondary.getItems())
		{
			BigDecimal quantity = BigDecimal.valueOf(stack.getQty());
			if (quantity.signum() > 0) needs.merge(stack.getId(), quantity, BigDecimal::add);
		}
		Secondaries.SecondaryHandler handler = secondary.getCustomHandler();
		if (handler instanceof Secondaries.ByDose)
			needs.merge(((Secondaries.ByDose) handler).getItems()[0], BigDecimal.ONE, BigDecimal::add);
		else if (handler instanceof Secondaries.Crushable)
		{
			int[] ids = ((Secondaries.Crushable) handler).getItems();
			needs.merge(ids[ids.length - 1], BigDecimal.ONE, BigDecimal::add);
		}
		// Degrime is accumulated separately because its rune requirement is nonlinear by batch.
	}

	private static final class UnitResult
	{
		private BigDecimal experience = BigDecimal.ZERO;
		private final Map<Integer, BigDecimal> secondaryNeeds = new LinkedHashMap<>();
		private BigDecimal degrimeHerbs = BigDecimal.ZERO;
	}

	private static final class UnitProjection
	{
		private BigDecimal experience = BigDecimal.ZERO;
		private boolean expected;
		private boolean unsupported;
		private int requiredLevel;
		private final List<String> warnings = new ArrayList<>();
	}
}

