package com.efficientskilling.planner.bankedxp;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.runelite.api.Skill;

public final class SkillBankedExperienceProjection
{
	private final Skill skill;
	private final BigDecimal currentExperience;
	private final BigDecimal targetExperience;
	private final BigDecimal usableExperience;
	private final BigDecimal levelLockedExperience;
	private final BigDecimal totalPotentialExperience;
	private final BigDecimal creditedTowardTargetExperience;
	private final BigDecimal remainingAfterBankedExperience;
	private final List<ResourceConversion> conversions;

	SkillBankedExperienceProjection(Skill skill, BigDecimal currentExperience, BigDecimal targetExperience,
		List<ResourceConversion> conversions)
	{
		this.skill = skill;
		this.currentExperience = currentExperience;
		this.targetExperience = targetExperience;
		this.conversions = Collections.unmodifiableList(new ArrayList<>(conversions));
		this.usableExperience = sum(conversions, ConversionStatus.USABLE);
		this.levelLockedExperience = sum(conversions, ConversionStatus.LEVEL_LOCKED);
		this.totalPotentialExperience = usableExperience.add(levelLockedExperience);
		BigDecimal needed = targetExperience.subtract(currentExperience).max(BigDecimal.ZERO);
		this.creditedTowardTargetExperience = totalPotentialExperience.min(needed);
		this.remainingAfterBankedExperience = needed.subtract(creditedTowardTargetExperience);
	}

	private static BigDecimal sum(List<ResourceConversion> conversions, ConversionStatus status)
	{
		BigDecimal sum = BigDecimal.ZERO;
		for (ResourceConversion conversion : conversions)
			if (conversion.getStatus() == status) sum = sum.add(conversion.getPotentialExperience());
		return sum;
	}

	public Skill getSkill() { return skill; }
	public BigDecimal getCurrentExperience() { return currentExperience; }
	public BigDecimal getTargetExperience() { return targetExperience; }
	public BigDecimal getUsableExperience() { return usableExperience; }
	public BigDecimal getLevelLockedExperience() { return levelLockedExperience; }
	public BigDecimal getTotalPotentialExperience() { return totalPotentialExperience; }
	public BigDecimal getCreditedTowardTargetExperience() { return creditedTowardTargetExperience; }
	public BigDecimal getRemainingAfterBankedExperience() { return remainingAfterBankedExperience; }
	public List<ResourceConversion> getConversions() { return conversions; }
}

