package com.efficientskilling.planner;

/** Planner-visible supply requirement and the observed bank evidence applied to it. */
public final class ResourceBalance
{
	private final MaxingResource resource;
	private final long required;
	private final long observed;
	private final long applied;
	private final long missing;

	public ResourceBalance(MaxingResource resource, long required, long observed, long applied)
	{
		if (resource == null || required < 0 || observed < 0 || applied < 0 || applied > observed)
		{
			throw new IllegalArgumentException("resource balance values must be valid and non-negative");
		}
		this.resource = resource;
		this.required = required;
		this.observed = observed;
		this.applied = Math.min(required, applied);
		this.missing = Math.max(0, required - this.applied);
	}

	public MaxingResource getResource() { return resource; }
	public long getRequired() { return required; }
	public long getObserved() { return observed; }
	public long getApplied() { return applied; }
	public long getMissing() { return missing; }
}

package com.efficientskilling.planner;

import com.efficientskilling.AccountProfile;

/** Hard planning capabilities derived from the manually selected account type. */
public final class AccountRules
{
	private final boolean tradingAllowed;
	private final boolean bankAllowed;
	private final boolean hardcoreRiskRestrictions;
	private final boolean groupResourcesMustBeDeclared;

	private AccountRules(boolean tradingAllowed, boolean bankAllowed, boolean hardcoreRiskRestrictions,
		boolean groupResourcesMustBeDeclared)
	{
		this.tradingAllowed = tradingAllowed;
		this.bankAllowed = bankAllowed;
		this.hardcoreRiskRestrictions = hardcoreRiskRestrictions;
		this.groupResourcesMustBeDeclared = groupResourcesMustBeDeclared;
	}

	public static AccountRules forProfile(AccountProfile profile)
	{
		if (profile == null)
		{
			throw new IllegalArgumentException("account type is required");
		}
		boolean main = profile == AccountProfile.MAIN;
		boolean uim = profile == AccountProfile.ULTIMATE_IRONMAN;
		boolean hardcore = profile == AccountProfile.HARDCORE_IRONMAN
			|| profile == AccountProfile.HARDCORE_GROUP_IRONMAN;
		boolean group = profile == AccountProfile.GROUP_IRONMAN
			|| profile == AccountProfile.HARDCORE_GROUP_IRONMAN;
		return new AccountRules(main, !uim, hardcore, group);
	}

	public boolean isTradingAllowed() { return tradingAllowed; }
	public boolean isBankAllowed() { return bankAllowed; }
	public boolean hasHardcoreRiskRestrictions() { return hardcoreRiskRestrictions; }
	public boolean mustDeclareGroupResources() { return groupResourcesMustBeDeclared; }
}

package com.efficientskilling.planner;

import java.util.concurrent.atomic.AtomicLong;

/** Rejects results produced for planning inputs which have since been superseded. */
public final class LatestRequestGate
{
	private final AtomicLong generation = new AtomicLong();

