package com.efficientskilling.planner;

import java.util.Objects;
import java.util.concurrent.Executor;
import java.util.concurrent.RejectedExecutionException;

/** Runs one task at a time and retains only the newest task requested while it runs. */
public final class LatestTaskCoalescer
{
	private boolean running;
	private boolean stopped;
	private Runnable pending;

	public synchronized boolean submit(Executor executor, Runnable task)
	{
		Objects.requireNonNull(executor, "executor");
		Objects.requireNonNull(task, "task");
		if (stopped) return false;
		if (running)
		{
			pending = task;
			return true;
		}
		running = true;
		return execute(executor, task);
	}

	public synchronized void stop()
	{
		stopped = true;
		pending = null;
	}

	private boolean execute(Executor executor, Runnable task)
	{
		try
		{
			executor.execute(() ->
			{
				try { task.run(); }
				finally { completed(executor); }
			});
			return true;
		}
		catch (RejectedExecutionException ex)
		{
			running = false;
			pending = null;
			return false;
		}
	}

	private synchronized void completed(Executor executor)
	{
		if (stopped)
		{
			running = false;
			pending = null;
			return;
		}
		Runnable next = pending;
		pending = null;
		if (next == null) running = false;
		else execute(executor, next);
	}
}

