	private final long generation;
	private final Long lastNotifiedGeneration;

	public ReminderState(boolean enabled, Long suppressedUntilEpochMillis,
		String lastNotifiedCycleId, long generation, Long lastNotifiedGeneration)
	{
		if (generation < 0 || (lastNotifiedGeneration != null && lastNotifiedGeneration < 0))
		{
			throw new IllegalArgumentException("generation cannot be negative");
		}
		this.enabled = enabled;
		this.suppressedUntilEpochMillis = suppressedUntilEpochMillis;
		this.lastNotifiedCycleId = lastNotifiedCycleId;
		this.generation = generation;
		this.lastNotifiedGeneration = lastNotifiedGeneration;
	}

	public static ReminderState enabled() { return new ReminderState(true, null, null, 0, null); }
	public boolean isEnabled() { return enabled; }
	public Long getSuppressedUntilEpochMillis() { return suppressedUntilEpochMillis; }
	public String getLastNotifiedCycleId() { return lastNotifiedCycleId; }
