}

package com.efficientskilling.planner.tracking;

import java.time.Duration;
import java.time.Instant;
import java.util.Objects;

/** Coordinates activity observations with reminder delivery without conflating their state. */
public final class TimedActivityState
{
	private final ActivityState activity;
	private final ReminderState reminder;

	public TimedActivityState(ActivityState activity, ReminderState reminder)
	{
		this.activity = Objects.requireNonNull(activity, "activity");
		this.reminder = Objects.requireNonNull(reminder, "reminder");
	}

	public TimedActivityState observe(ActivityState observed)
	{
		Objects.requireNonNull(observed, "observed");
		if (Objects.equals(activity.getCycleId(), observed.getCycleId()))
		{
			return new TimedActivityState(observed, reminder);
		}
		// Refreshes of an already-actionable ready run must not re-arm its notification.
		// A real next cycle passes through a non-ready state, which still resets below.
		if (activity.getStatus() == ActivityStatus.READY
			&& observed.getStatus() == ActivityStatus.READY)
		{
			return new TimedActivityState(observed, reminder);
		}
		return new TimedActivityState(observed,
			new ReminderState(reminder.isEnabled(), null, null, 0, null));
	}

	public TimedActivityState remindLater(Instant now, Duration delay)
	{
		if (activity.getStatus() != ActivityStatus.READY
			&& activity.getStatus() != ActivityStatus.ATTENTION)
		{
			throw new IllegalStateException("remind later is only available for actionable activities");
		}
		Objects.requireNonNull(now, "now");
		Objects.requireNonNull(delay, "delay");
		long millis = delay.toMillis();
		if (millis <= 0)
		{
			throw new IllegalArgumentException("delay must be positive");
		}
		long until;
		try
		{
			until = Math.addExact(now.toEpochMilli(), millis);
		}
		catch (ArithmeticException ex)
		{
			throw new IllegalArgumentException("suppression time is outside the supported range", ex);
		}
		ReminderState next = new ReminderState(reminder.isEnabled(), until,
			reminder.getLastNotifiedCycleId(), Math.addExact(reminder.getGeneration(), 1),
			reminder.getLastNotifiedGeneration());
		return new TimedActivityState(activity, next);
	}

	public boolean shouldNotifyAt(Instant now)
	{
		if (!reminder.isEnabled() || (activity.getStatus() != ActivityStatus.READY
			&& activity.getStatus() != ActivityStatus.ATTENTION))
		{
			return false;
		}
		Long suppressed = reminder.getSuppressedUntilEpochMillis();
		if (suppressed != null && now.toEpochMilli() < suppressed)
		{
			return false;
		}
		return !Objects.equals(activity.getCycleId(), reminder.getLastNotifiedCycleId())
			|| !Long.valueOf(reminder.getGeneration()).equals(reminder.getLastNotifiedGeneration());
	}

	public TimedActivityState markNotified(Instant now)
	{
		if (!shouldNotifyAt(now))
		{
			return this;
		}
		return new TimedActivityState(activity, new ReminderState(reminder.isEnabled(),
			reminder.getSuppressedUntilEpochMillis(), activity.getCycleId(), reminder.getGeneration(),
			reminder.getGeneration()));
	}

	public ActivityState getActivity() { return activity; }
	public ReminderState getReminder() { return reminder; }
}

