package com.efficientskilling.planner.tracking;

import com.efficientskilling.planner.TimedTaskState;
import java.time.Instant;

public final class TimedTaskStateMigration
{
	private TimedTaskStateMigration() { }

	public static TimedActivityState migrate(TimedTaskState legacy, Instant now)
	{
		long nowMillis = now.toEpochMilli();
		boolean complete = legacy.getCompletedCount() >= legacy.getTargetCompletions();
		boolean ready = !complete && legacy.getNextDueAtEpochMillis() <= nowMillis;
		ActivityStatus status = complete ? ActivityStatus.COMPLETE
			: ready ? ActivityStatus.READY : ActivityStatus.GROWING;
		String cycleId = "legacy:" + legacy.getNextDueAtEpochMillis();
		ActivityState activity = new ActivityState(ActivityTrackingType.MANUAL, status, cycleId,
			legacy.getNextDueAtEpochMillis(), legacy.getCompletedCount(), legacy.getTargetCompletions());
		Long suppression = ready && legacy.getSnoozedUntilEpochMillis() != null
			&& legacy.getSnoozedUntilEpochMillis() > nowMillis
			? legacy.getSnoozedUntilEpochMillis() : null;
		String notifiedCycle = legacy.getLastNotifiedDueAtEpochMillis() == null ? null : cycleId;
		Long notifiedGeneration = notifiedCycle == null ? null : 0L;
		ReminderState reminder = new ReminderState(!legacy.isDisabled(), suppression,
			notifiedCycle, 0, notifiedGeneration);
		return new TimedActivityState(activity, reminder);
	}
}

