package com.efficientskilling.planner;

import com.efficientskilling.AccountProfile;
import com.efficientskilling.planner.bankedxp.BankedExperienceCalculator;
import com.efficientskilling.planner.bankedxp.SkillBankedExperienceProjection;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.Duration;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import net.runelite.api.Skill;

/**
 * Deterministic Farming and Herblore supply projection used alongside the whole-account planner.
 */
public final class FarmingHerblorePlanner
{
	private static final Duration HERB_RUN_INTERVAL = Duration.ofMinutes(80);

	public MaxPlan plan(MaxPlanRequest request)
	{
		AccountProfile profile = request.getAccountProfile();
		AccountRules rules = AccountRules.forProfile(profile);
		int farmingXp = request.getStats().remainingTo99(Skill.FARMING);
		int herbloreXp = request.getStats().remainingTo99(Skill.HERBLORE);
		Map<Integer, Long> storedItems =
			request.getBankSnapshot() == null ? Collections.emptyMap()
				: (request.getBankSnapshot().getItems().isEmpty()
					? request.getBankSnapshot().provenance(MaxingResource.CLEAN_HERB)
					: request.getBankSnapshot().getItems());
		long currentHerbloreXp = request.getStats().getExperience(Skill.HERBLORE);
		SkillBankedExperienceProjection herbPotential = new BankedExperienceCalculator().project(
			Skill.HERBLORE, storedItems,
			net.runelite.api.Experience.getLevelForXp((int) currentHerbloreXp),
			currentHerbloreXp, AccountStats.XP_FOR_99, request.getBankedExperiencePreferences());
		long observedHerbs = rules.isBankAllowed() && request.getBankSnapshot() != null
			? request.getBankSnapshot().quantity(MaxingResource.CLEAN_HERB) : 0;
		long potentialXpTenths = rules.isBankAllowed()
			? toTenths(herbPotential.getTotalPotentialExperience()) : 0;
		long appliedXpTenths = rules.isBankAllowed() && request.isBankEvidenceApplicable()
			? Math.min(Math.multiplyExact((long) herbloreXp, 10L), potentialXpTenths) : 0;
		long remainingHerbloreXpTenths = Math.max(0,
			Math.multiplyExact((long) herbloreXp, 10L) - appliedXpTenths);
		long observedSeeds = rules.isBankAllowed() && request.getBankSnapshot() != null
			? request.getBankSnapshot().quantity(MaxingResource.HERB_SEED) : 0;

		List<MaxPlanStep> steps = new ArrayList<>();
		List<RecurringTask> recurring = new ArrayList<>();
		List<String> assumptions = new ArrayList<>();
		assumptions.add("Stored Herblore resources are valued with the selected conversion method; fractional XP is retained exactly.");
		assumptions.add("The selected strategy changes whole-account methods through the reviewed catalogue; this supply projection follows account trading rules and the selected stored-resource conversions.");

		if (herbloreXp > 0 && rules.isTradingAllowed())
		{
			String title = appliedXpTenths < Math.multiplyExact((long) herbloreXp, 10L) ? "Buy remaining Herblore supplies"
				: "Use banked Herblore supplies";
			steps.add(new MaxPlanStep("buy-herblore-supplies", title, null, 0,
				Collections.singletonList(appliedXpTenths > 0
					? "The plan credits " + formatTenths(appliedXpTenths) + " potential Herblore XP from selected banked-herb conversions; tradable secondaries may still need to be bought."
					: "Main accounts may trade, so gathering is not a hard prerequisite.")));
		}
		else if (herbloreXp > 0)
		{
			if (remainingHerbloreXpTenths > 0)
			{
				steps.add(new MaxPlanStep("unlock-herb-runs", "Prepare sustainable herb runs", Skill.FARMING, 0,
					Collections.singletonList("Stored Herblore resources do not cover 99; use recurring herb runs and account-appropriate herb sources for the remaining demand.")));
				recurring.add(new RecurringTask("herb-run", "Complete an herb run", HERB_RUN_INTERVAL, 1,
					"Keep gathering herbs for 99 Herblore; each completed run updates readiness and the next storage snapshot updates remaining demand."));
			}
			if (potentialXpTenths > 0)
			{
				assumptions.add("The latest storage snapshots contribute " + formatTenths(appliedXpTenths)
					+ " potential Herblore XP. Selected conversions may still require gathering secondaries for this restricted account.");
			}
			assumptions.add("Herb demand is calculated from observed storage; potion secondaries remain explicit gathering work rather than stored-value estimates.");
			if (potentialXpTenths > 0)
			{
				steps.add(new MaxPlanStep("gather-herblore-secondaries", "Gather Herblore secondaries", null, 0,
					Collections.singletonList("Gather the inputs required by the selected Banked Experience conversions.")));
			}
		}

		if (farmingXp > 0)
		{
			steps.add(new MaxPlanStep("train-farming", "Train Farming to 99", Skill.FARMING, farmingXp,
				Collections.singletonList("This credits exact remaining Farming XP from the account snapshot.")));
		}
		if (herbloreXp > 0)
		{
			String title = rules.isTradingAllowed()
				? "Process supplies and train Herblore to 99"
				: "Review remaining Herblore work";
			String explanation = rules.isTradingAllowed()
				? "Main-account supply purchasing is available for the remaining conversion inputs."
				: "Gather the missing secondaries identified by the selected conversions, then process the credited resources.";
			steps.add(new MaxPlanStep("train-herblore", title, Skill.HERBLORE, herbloreXp,
				Collections.singletonList(explanation)));
		}
		if (!rules.isBankAllowed() && request.getBankSnapshot() != null)
		{
			assumptions.add("The supplied bank snapshot was ignored because Ultimate Ironman plans cannot assume bank storage.");
		}
		if (rules.hasHardcoreRiskRestrictions())
		{
			assumptions.add("Hardcore risk restrictions are active; the current acquisition route contains no deliberately risky methods.");
		}
		if (rules.mustDeclareGroupResources())
		{
			assumptions.add("No Group Ironman teammate resources are assumed; contributions must be manually declared before they can affect the plan.");
		}
		List<ResourceBalance> resources = new ArrayList<>();
		resources.add(new ResourceBalance(MaxingResource.CLEAN_HERB, 0, observedHerbs, 0));
		resources.add(new ResourceBalance(MaxingResource.HERB_SEED, 0, observedSeeds, 0));
		resources.add(new ResourceBalance(MaxingResource.HERBLORE_XP_TENTHS,
			Math.multiplyExact((long) herbloreXp, 10L), potentialXpTenths, appliedXpTenths));
		return new MaxPlan(profile, request.getStrategy(), steps, recurring, assumptions, resources);
	}

	private static String formatTenths(long value)
	{
		return (value / 10) + (value % 10 == 0 ? "" : "." + value % 10);
	}

	private static long toTenths(BigDecimal value)
	{
		return value.movePointRight(1).setScale(0, RoundingMode.HALF_UP).longValueExact();
	}

	private static long divideRoundUp(long numerator, long denominator)
	{
		return numerator == 0 ? 0 : 1 + ((numerator - 1) / denominator);
	}
}

