package com.efficientskilling.planner;

import com.efficientskilling.planner.bank.BankItemSnapshot;
import java.util.Collections;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.gameval.ItemID;

/** Maps canonical bank item evidence into the resources understood by the current planner. */
public final class BankResourceMapper
{
	private static final Map<Integer, MaxingResource> ITEM_RESOURCES = createMappings();

	public BankSnapshot map(BankItemSnapshot raw)
	{
		if (raw == null)
		{
			throw new IllegalArgumentException("raw bank snapshot is required");
		}
		EnumMap<MaxingResource, Long> quantities = new EnumMap<>(MaxingResource.class);
		EnumMap<MaxingResource, Map<Integer, Long>> provenance = new EnumMap<>(MaxingResource.class);
		for (Map.Entry<Integer, Long> item : raw.getQuantities().entrySet())
		{
			MaxingResource resource = ITEM_RESOURCES.get(item.getKey());
			if (resource == null || item.getValue() == 0)
			{
				continue;
			}
			quantities.merge(resource, item.getValue(), Math::addExact);
			provenance.computeIfAbsent(resource, ignored -> new LinkedHashMap<>())
				.put(item.getKey(), item.getValue());
		}
		return new BankSnapshot(raw.getObservedAt(), quantities, provenance, raw.getQuantities());
	}

	private static Map<Integer, MaxingResource> createMappings()
	{
		Map<Integer, MaxingResource> mappings = new LinkedHashMap<>();
		add(mappings, MaxingResource.CLEAN_HERB,
			ItemID.GUAM_LEAF, ItemID.UNIDENTIFIED_GUAM,
			ItemID.MARENTILL, ItemID.UNIDENTIFIED_MARENTILL,
			ItemID.TARROMIN, ItemID.UNIDENTIFIED_TARROMIN,
			ItemID.HARRALANDER, ItemID.UNIDENTIFIED_HARRALANDER,
			ItemID.RANARR_WEED, ItemID.UNIDENTIFIED_RANARR,
			ItemID.TOADFLAX, ItemID.UNIDENTIFIED_TOADFLAX,
			ItemID.IRIT_LEAF, ItemID.UNIDENTIFIED_IRIT,
			ItemID.AVANTOE, ItemID.UNIDENTIFIED_AVANTOE,
			ItemID.KWUARM, ItemID.UNIDENTIFIED_KWUARM,
			ItemID.HUASCA, ItemID.UNIDENTIFIED_HUASCA,
			ItemID.SNAPDRAGON, ItemID.UNIDENTIFIED_SNAPDRAGON,
			ItemID.CADANTINE, ItemID.UNIDENTIFIED_CADANTINE,
			ItemID.LANTADYME, ItemID.UNIDENTIFIED_LANTADYME,
			ItemID.DWARF_WEED, ItemID.UNIDENTIFIED_DWARF_WEED,
			ItemID.TORSTOL, ItemID.UNIDENTIFIED_TORSTOL);
		add(mappings, MaxingResource.HERB_SEED,
			ItemID.GUAM_SEED, ItemID.MARRENTILL_SEED, ItemID.TARROMIN_SEED,
			ItemID.HARRALANDER_SEED, ItemID.RANARR_SEED, ItemID.TOADFLAX_SEED,
			ItemID.IRIT_SEED, ItemID.AVANTOE_SEED, ItemID.KWUARM_SEED,
			ItemID.HUASCA_SEED, ItemID.SNAPDRAGON_SEED, ItemID.CADANTINE_SEED,
			ItemID.LANTADYME_SEED, ItemID.DWARF_WEED_SEED, ItemID.TORSTOL_SEED);
		return Collections.unmodifiableMap(mappings);
	}

	private static void add(Map<Integer, MaxingResource> mappings, MaxingResource resource, int... itemIds)
	{
		for (int itemId : itemIds)
		{
			if (mappings.put(itemId, resource) != null)
			{
				throw new IllegalStateException("duplicate bank resource item mapping: " + itemId);
			}
		}
	}
}

