/** Owns Path to Max request generations and latest-only background scheduling. */
public final class PathToMaxController
{
	private final Executor executor;
	private final LatestRequestGate requests = new LatestRequestGate();
	private final LatestTaskCoalescer tasks = new LatestTaskCoalescer();

	public PathToMaxController(Executor executor)
	{
		this.executor = Objects.requireNonNull(executor, "executor");
	}

	public long beginRequest() { return requests.begin(); }
	public boolean isCurrent(long generation) { return requests.isCurrent(generation); }
