package com.efficientskilling.planner.bank;

import com.efficientskilling.planner.AccountRules;
import java.time.Duration;
import java.time.Instant;

/** Decides whether captured personal-bank evidence is safe to credit to a plan. */
public final class BankEvidencePolicy
{
	private static final Duration FRESHNESS = Duration.ofHours(24);
	private static final Duration FUTURE_TOLERANCE = Duration.ofMinutes(5);

	public Result evaluate(AccountRules rules, BankItemSnapshot snapshot, Instant now)
	{
		return evaluate(rules, snapshot, now, "Personal bank", "bank");
	}

	public Result evaluateSeedVault(AccountRules rules, BankItemSnapshot snapshot, Instant now)
	{
		return evaluate(rules, snapshot, now, "Seed Vault", "Seed Vault");
	}

	private Result evaluate(AccountRules rules, BankItemSnapshot snapshot, Instant now,
		String displayName, String openName)
	{
		if (!rules.isBankAllowed())
		{
			return new Result(false, false,
				"Bank and Seed Vault supplies are intentionally excluded for Ultimate Ironman. Inventory, looting bag, and death storage are not captured yet.");
		}
		if (snapshot == null)
		{
			return new Result(false, false,
				"No " + displayName + " snapshot captured yet. Open your " + openName
					+ " once to make its supplies available to the plan.");
		}

		Duration age = Duration.between(snapshot.getObservedAt(), now);
		if (age.compareTo(FUTURE_TOLERANCE.negated()) < 0)
		{
			return new Result(false, true,
				"The saved " + displayName + " snapshot has an invalid future timestamp and is not applied. Reopen your " + openName + " to refresh it.");
		}

		Duration displayAge = age.isNegative() ? Duration.ZERO : age;
		String ageText = formatAge(displayAge);
		if (displayAge.compareTo(FRESHNESS) <= 0)
		{
			return new Result(true, true, displayName + " observed " + ageText
				+ " ago. Supported supplies are applied to this plan; snapshots are credited for 24 hours.");
		}
		return new Result(false, true, displayName + " was observed " + ageText
			+ " ago and is not applied. Reopen it to refresh.");
	}

	private static String formatAge(Duration age)
	{
		long minutes = age.toMinutes();
		return minutes < 60 ? minutes + " minutes"
			: minutes < 1440 ? (minutes / 60) + " hours" : (minutes / 1440) + " days";
	}

	public static final class Result
	{
		private final boolean applicable;
		private final boolean evidenceAvailable;
		private final String status;

		private Result(boolean applicable, boolean evidenceAvailable, String status)
		{
			this.applicable = applicable;
			this.evidenceAvailable = evidenceAvailable;
			this.status = status;
		}

		public boolean isApplicable() { return applicable; }
		public boolean isEvidenceAvailable() { return evidenceAvailable; }
		public String getStatus() { return status; }
	}
}

package com.efficientskilling.planner.bank;

import java.time.Instant;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;

/** Converts a complete RuneLite bank container into stable item quantities. */
public final class BankSnapshotCapture
{
	private final ItemLookup itemLookup;

	@Inject
	public BankSnapshotCapture(ItemManager itemManager)
	{
		this(new ItemLookup()
		{
			@Override
			public boolean isPlaceholder(int itemId)
			{
				ItemComposition composition = itemManager.getItemComposition(itemId);
				return composition.getPlaceholderTemplateId() != -1;
			}

			@Override
			public int canonicalize(int itemId)
			{
				return itemManager.canonicalize(itemId);
			}
		});
	}

	BankSnapshotCapture(ItemLookup itemLookup)
	{
		this.itemLookup = itemLookup;
	}

	/** Must be called on the client thread because it reads item compositions. */
	public BankItemSnapshot capture(ItemContainer bank, Instant observedAt)
	{
		if (bank == null || observedAt == null)
		{
			throw new IllegalArgumentException("bank and observation time are required");
		}

		return capture(bank.getItems(), observedAt);
	}

	BankItemSnapshot capture(Item[] items, Instant observedAt)
	{
		if (items == null || observedAt == null)
		{
			throw new IllegalArgumentException("items and observation time are required");
		}
		Map<Integer, Long> quantities = new HashMap<>();
		for (Item item : items)
		{
			int itemId = item.getId();
			int quantity = item.getQuantity();
			if (itemId <= 0 || quantity <= 0 || itemId == ItemID.BANK_FILLER)
			{
				continue;
			}

			if (itemLookup.isPlaceholder(itemId))
			{
				continue;
			}

			int canonicalId = itemLookup.canonicalize(itemId);
			if (canonicalId > 0)
			{
				quantities.merge(canonicalId, (long) quantity, Math::addExact);
			}
		}
		return new BankItemSnapshot(observedAt, quantities);
	}

	interface ItemLookup
	{
		boolean isPlaceholder(int itemId);

		int canonicalize(int itemId);
	}
}

package com.efficientskilling.planner.bank;

import java.util.Optional;

/** Coordinates per-profile bank evidence so late loads and planning jobs cannot cross accounts. */
public final class BankProfileState
{
	private String profileKey;
	private long generation;
	private BankItemSnapshot snapshot;

	public synchronized Token switchProfile(String nextProfileKey)
	{
		profileKey = validKey(nextProfileKey) ? nextProfileKey : null;
		snapshot = null;
		generation++;
		return profileKey == null ? null : new Token(profileKey, generation);
	}

	public synchronized boolean capture(String capturedProfileKey, BankItemSnapshot captured)
	{
		if (!validKey(capturedProfileKey) || captured == null
			|| !capturedProfileKey.equals(profileKey))
		{
			return false;
		}
		if (snapshot != null && snapshot.getQuantities().equals(captured.getQuantities())
			&& !captured.getObservedAt().isAfter(snapshot.getObservedAt().plusSeconds(2))) return false;
		snapshot = captured;
		generation++;
		return true;
	}

	public synchronized boolean applyLoaded(Token token, Optional<BankItemSnapshot> loaded)
	{
		if (token == null || loaded == null || !token.profileKey.equals(profileKey)
			|| token.generation != generation)
		{
			return false;
		}
		snapshot = loaded.orElse(null);
		generation++;
		return true;
	}

	public synchronized Context context(String expectedProfileKey)
	{
		BankItemSnapshot evidence = expectedProfileKey != null && expectedProfileKey.equals(profileKey)
			? snapshot : null;
		return new Context(expectedProfileKey, generation, evidence);
	}

	public synchronized boolean isCurrent(Context context)
	{
		return context != null && context.profileKey != null
			&& context.profileKey.equals(profileKey) && context.generation == generation;
	}

	private static boolean validKey(String key)
	{
		return key != null && !key.trim().isEmpty();
	}

	public static final class Token
	{
		private final String profileKey;
		private final long generation;

		private Token(String profileKey, long generation)
		{
			this.profileKey = profileKey;
			this.generation = generation;
		}

		public String getProfileKey() { return profileKey; }
	}

	public static final class Context
	{
		private final String profileKey;
		private final long generation;
		private final BankItemSnapshot snapshot;

		private Context(String profileKey, long generation, BankItemSnapshot snapshot)
		{
			this.profileKey = profileKey;
			this.generation = generation;
			this.snapshot = snapshot;
		}

		public BankItemSnapshot getSnapshot() { return snapshot; }
	}
}

