package com.efficientskilling.planner.bank;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.Instant;
import java.util.Map;
import java.util.Locale;
import java.util.Optional;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

/** Atomic, per-profile storage for the last complete bank observation. */
@Slf4j
public final class BankSnapshotRepository
{
	public static final int SCHEMA_VERSION = 1;
	private static final String DIRECTORY_NAME = "efficient-skilling";
	private final Gson gson;
	private final Path storageDirectory;
	private final String filePrefix;

	@Inject
	public BankSnapshotRepository(Gson gson)
	{
		this(gson, RuneLite.RUNELITE_DIR.toPath().resolve(DIRECTORY_NAME));
	}

	/** Constructor intended for tests and explicitly configured storage roots. */
	public BankSnapshotRepository(Gson gson, Path storageDirectory)
	{
		this(gson, storageDirectory, "bank");
	}

	BankSnapshotRepository(Gson gson, Path storageDirectory, String filePrefix)
	{
		this.gson = gson;
		this.storageDirectory = storageDirectory.toAbsolutePath().normalize();
		this.filePrefix = filePrefix;
	}

	/** Performs disk IO; callers must invoke this away from the client thread. */
	public Optional<BankItemSnapshot> load(String rsProfileKey)
	{
		Path file = fileFor(rsProfileKey);
		if (!Files.isRegularFile(file))
		{
			return Optional.empty();
		}

		try
		{
			Envelope envelope = gson.fromJson(
				new String(Files.readAllBytes(file), StandardCharsets.UTF_8), Envelope.class);
			if (envelope == null || envelope.schemaVersion != SCHEMA_VERSION || envelope.payload == null)
			{
				log.debug("Ignoring unsupported or incomplete bank snapshot in {}", file);
				return Optional.empty();
			}
			SnapshotPayload payload = gson.fromJson(envelope.payload, SnapshotPayload.class);
			if (payload == null || payload.quantities == null)
			{
				return Optional.empty();
			}
			return Optional.of(new BankItemSnapshot(Instant.ofEpochMilli(payload.observedAtEpochMilli), payload.quantities));
		}
		catch (IOException | RuntimeException ex)
		{
			log.debug("Unable to read bank snapshot from {}", file, ex);
			return Optional.empty();
		}
	}

	/** Performs disk IO; callers must invoke this away from the client thread. */
	public synchronized void save(String rsProfileKey, BankItemSnapshot snapshot) throws IOException
	{
		if (snapshot == null)
		{
			throw new IllegalArgumentException("snapshot is required");
		}
		Files.createDirectories(storageDirectory);
		Path destination = fileFor(rsProfileKey);
		Path temporary = destination.resolveSibling(destination.getFileName() + ".tmp");
		SnapshotPayload payload = new SnapshotPayload(snapshot.getObservedAt().toEpochMilli(), snapshot.getQuantities());
		Files.write(temporary, gson.toJson(new Envelope(SCHEMA_VERSION, gson.toJsonTree(payload)))
			.getBytes(StandardCharsets.UTF_8));
		try
		{
			Files.move(temporary, destination, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
		}
		catch (AtomicMoveNotSupportedException ex)
		{
			Files.move(temporary, destination, StandardCopyOption.REPLACE_EXISTING);
		}
	}

	Path fileFor(String rsProfileKey)
	{
		String identity = rsProfileKey == null ? "" : rsProfileKey.trim().toLowerCase(Locale.ROOT);
		return storageDirectory.resolve(filePrefix + "-" + sha256(identity) + ".json").normalize();
	}

	private static String sha256(String value)
	{
		try
		{
			byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
			StringBuilder result = new StringBuilder(digest.length * 2);
			for (byte part : digest)
			{
				result.append(String.format("%02x", part & 0xff));
			}
			return result.toString();
		}
		catch (NoSuchAlgorithmException ex)
		{
			throw new IllegalStateException("SHA-256 is required by the Java runtime", ex);
		}
	}

	private static final class Envelope
	{
		private int schemaVersion;
		private JsonElement payload;

		private Envelope(int schemaVersion, JsonElement payload)
		{
			this.schemaVersion = schemaVersion;
			this.payload = payload;
		}
	}

	private static final class SnapshotPayload
	{
		private long observedAtEpochMilli;
		private Map<Integer, Long> quantities;

		private SnapshotPayload(long observedAtEpochMilli, Map<Integer, Long> quantities)
		{
			this.observedAtEpochMilli = observedAtEpochMilli;
			this.quantities = quantities;
		}
	}
}

package com.efficientskilling.planner.bank;

import java.time.Instant;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/** Complete contents of the player's bank at the time it was last observed. */
public final class BankItemSnapshot
{
	private final Instant observedAt;
	private final Map<Integer, Long> quantities;

	public BankItemSnapshot(Instant observedAt, Map<Integer, Long> quantities)
	{
		if (observedAt == null || quantities == null)
		{
			throw new IllegalArgumentException("observation time and quantities are required");
		}

		Map<Integer, Long> copy = new HashMap<>();
		for (Map.Entry<Integer, Long> entry : quantities.entrySet())
		{
			if (entry.getKey() == null || entry.getKey() <= 0
				|| entry.getValue() == null || entry.getValue() <= 0)
			{
				throw new IllegalArgumentException("item ids and quantities must be positive");
			}
			copy.put(entry.getKey(), entry.getValue());
		}
		this.observedAt = observedAt;
		this.quantities = Collections.unmodifiableMap(copy);
	}

	public Instant getObservedAt()
	{
		return observedAt;
	}

	public long quantity(int itemId)
	{
		return quantities.getOrDefault(itemId, 0L);
	}

	public Map<Integer, Long> getQuantities()
	{
		return quantities;
	}
}

