import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.Skill;

/** Immutable exact-XP account state. Missing skills are treated as zero XP. */
public final class AccountStats
{
	public static final int XP_FOR_99 = 13_034_431;
	private final Map<Skill, Integer> experience;

	public AccountStats(Map<Skill, Integer> experience)
	{
		if (experience == null)
		{
			throw new IllegalArgumentException("experience is required");
		}
		EnumMap<Skill, Integer> copy = new EnumMap<>(Skill.class);
		for (Map.Entry<Skill, Integer> entry : experience.entrySet())
		{
			if (entry.getKey() == null || entry.getValue() == null || entry.getValue() < 0)
			{
				throw new IllegalArgumentException("skill XP must be non-negative");
			}
			copy.put(entry.getKey(), entry.getValue());
		}
		this.experience = Collections.unmodifiableMap(copy);
	}

	public int getExperience(Skill skill)
	{
		return experience.getOrDefault(skill, 0);
	}

	public int remainingTo99(Skill skill)
	{
		return Math.max(0, XP_FOR_99 - getExperience(skill));
	}
}

