package com.efficientskilling.tracking;

import com.efficientskilling.planner.tracking.ActivityState;
import com.efficientskilling.planner.tracking.ActivityStatus;
import com.efficientskilling.planner.tracking.ActivityTrackingType;
import java.time.Duration;
import java.time.Instant;

/** Development-only deterministic tracked-activity sequence. */
public final class TrackedTaskSimulator
{
	public static final Duration PARTIAL_AFTER = Duration.ofSeconds(15);
	public static final Duration READY_AFTER = Duration.ofSeconds(30);
	private final Instant startedAt;

	public TrackedTaskSimulator(Instant startedAt)
	{
		this.startedAt = startedAt;
	}

	public ActivityState stateAt(Instant now)
	{
		Duration elapsed = Duration.between(startedAt, now);
		ActivityStatus status = elapsed.compareTo(READY_AFTER) >= 0 ? ActivityStatus.READY
			: elapsed.compareTo(PARTIAL_AFTER) >= 0 ? ActivityStatus.PARTIALLY_READY
			: ActivityStatus.GROWING;
		long progress = status == ActivityStatus.READY ? 4
			: status == ActivityStatus.PARTIALLY_READY ? 2 : 0;
		return new ActivityState(ActivityTrackingType.TRACKED_GAME, status,
			"developer-simulation", startedAt.plus(READY_AFTER).toEpochMilli(), progress, 4);
	}
}

