package com.efficientskilling.tracking.timetracking.vendored;

/** Adapted from RuneLite's Time Tracking bird-house state decoder. */
public enum BirdHouseState
{
	SEEDED,
	BUILT,
	EMPTY,
	UNKNOWN;

	private static final int MAX_KNOWN_VARP = 27;

	public static BirdHouseState fromVarpValue(int varp)
	{
		if (varp < 0 || varp > MAX_KNOWN_VARP)
		{
			return UNKNOWN;
		}
		if (varp == 0)
		{
			return EMPTY;
		}
		return varp % 3 == 0 ? SEEDED : BUILT;
	}
}

