package com.efficientskilling.tracking.timetracking.vendored.farming;

public final class HerbPatchState
{
	public enum State { EMPTY, GROWING, HARVESTABLE, DISEASED, DEAD }

	private final State state;
	private final int stage;

	private HerbPatchState(State state, int stage)
	{
		this.state = state;
		this.stage = stage;
	}

	public State getState() { return state; }
	public int getStage() { return stage; }

	/** Read-only herb subset of RuneLite's PatchImplementation.HERB decoder. */
	public static HerbPatchState fromVarbitValue(int value)
	{
		if ((value >= 0 && value <= 3) || value == 67
			|| (value >= 176 && value <= 191) || (value >= 204 && value <= 219)
			|| (value >= 221 && value <= 255))
		{
			return new HerbPatchState(State.EMPTY, 0);
		}

		int[] growingStarts = {4, 11, 18, 25, 32, 39, 46, 53, 60, 68, 75, 82, 89, 96, 103};
		for (int start : growingStarts)
		{
			if (value >= start && value <= start + 3)
			{
				return new HerbPatchState(State.GROWING, value - start);
			}
		}
		int[] harvestStarts = {8, 15, 22, 29, 36, 43, 50, 57, 64, 72, 79, 86, 93, 100, 107};
		for (int start : harvestStarts)
		{
			if (value >= start && value <= start + 2)
			{
				return new HerbPatchState(State.HARVESTABLE, 4);
			}
		}
		if ((value >= 128 && value <= 169) || (value >= 173 && value <= 175)
			|| (value >= 198 && value <= 200))
		{
			return new HerbPatchState(State.DISEASED, 0);
		}
		if ((value >= 170 && value <= 172) || (value >= 201 && value <= 203))
		{
			return new HerbPatchState(State.DEAD, 0);
		}
		// Goutweed is not a herb-run crop and value 220 is unused upstream.
		return null;
	}
}

