package com.efficientskilling.tracking.timetracking.vendored.farming;

import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import java.util.function.Function;
import net.runelite.client.config.ConfigManager;

/** Read-only herb subset of RuneLite's FarmingTracker prediction logic. */
public final class ReadOnlyHerbTracker
{
	private static final String CONFIG_GROUP = "timetracking";
	private static final String OFFSET = "farmTickOffset";
	private static final String OFFSET_PRECISION = "farmTickOffsetPrecision";
	private static final int TICK_RATE_MINUTES = 20;
	private static final int STAGES = 5;

	private final Function<String, String> configurationReader;
	private Map<HerbPatch, HerbPatchPrediction> predictions = Collections.emptyMap();

	public ReadOnlyHerbTracker(ConfigManager configManager)
	{
		this(key -> configManager.getRSProfileConfiguration(CONFIG_GROUP, key));
	}

	ReadOnlyHerbTracker(Function<String, String> configurationReader)
	{
		this.configurationReader = configurationReader;
	}

	public void reload()
	{
		Map<HerbPatch, HerbPatchPrediction> loaded = new EnumMap<>(HerbPatch.class);
		Integer offset = parseInteger(configurationReader.apply(OFFSET));
		Integer precision = parseInteger(configurationReader.apply(OFFSET_PRECISION));
		for (HerbPatch patch : HerbPatch.values())
		{
			String stored = configurationReader.apply(patch.configKey());
			if (stored == null)
			{
				continue;
			}
			String[] parts = stored.split(":", -1);
			if (parts.length != 2)
			{
				continue;
			}
			try
			{
				HerbPatchState state = HerbPatchState.fromVarbitValue(Integer.parseInt(parts[0]));
				long observedAt = Long.parseLong(parts[1]);
				if (state == null || observedAt <= 0)
				{
					continue;
				}
				long done = state.getState() == HerbPatchState.State.GROWING
					? getTickTime(STAGES - 1 - state.getStage(), observedAt, offset, precision)
					: state.getState() == HerbPatchState.State.HARVESTABLE
						? getTickTime(0, observedAt, offset, precision) : 0;
				loaded.put(patch, new HerbPatchPrediction(patch, state.getState(), done));
			}
			catch (NumberFormatException ignored)
			{
				// A malformed patch is ignored independently, matching RuneLite.
			}
		}
		predictions = Collections.unmodifiableMap(loaded);
	}

	public Map<HerbPatch, HerbPatchPrediction> getPredictions()
	{
		return predictions;
	}

	static long getTickTime(int ticks, long requestedTime, Integer offsetMinutes, Integer precisionMinutes)
	{
		long offsetSeconds = offsetMinutes != null && precisionMinutes != null
			&& (precisionMinutes >= TICK_RATE_MINUTES || precisionMinutes >= 40)
			? (offsetMinutes % TICK_RATE_MINUTES) * 60L : 0L;
		long adjusted = requestedTime + offsetSeconds;
		long currentTick = adjusted - Math.floorMod(adjusted, TICK_RATE_MINUTES * 60L);
		return currentTick + ticks * TICK_RATE_MINUTES * 60L - offsetSeconds;
	}

	private static Integer parseInteger(String value)
	{
		try { return value == null ? null : Integer.valueOf(value); }
		catch (NumberFormatException ignored) { return null; }
	}
}

