import com.efficientskilling.planner.tracking.ActivityState;
import com.efficientskilling.planner.tracking.ActivityStatus;
import com.efficientskilling.planner.tracking.ActivityTrackingType;
import com.efficientskilling.tracking.timetracking.vendored.BirdHouseData;
import com.efficientskilling.tracking.timetracking.vendored.BirdHouseSpace;
import com.efficientskilling.tracking.timetracking.vendored.BirdHouseState;
import com.efficientskilling.tracking.timetracking.vendored.ReadOnlyBirdHouseTracker;
import com.efficientskilling.tracking.timetracking.vendored.farming.HerbPatch;
import com.efficientskilling.tracking.timetracking.vendored.farming.HerbPatchPrediction;
import com.efficientskilling.tracking.timetracking.vendored.farming.HerbPatchState;
import com.efficientskilling.tracking.timetracking.vendored.farming.ReadOnlyHerbTracker;
import java.time.Instant;
import java.util.Map;
import java.util.Optional;
import javax.inject.Inject;
import net.runelite.client.config.ConfigManager;

/** Translates RuneLite Time Tracking's persisted bird-house state into planner state. */
public final class CoreTimeTrackingAdapter
{
	private final ReadOnlyBirdHouseTracker birdHouseTracker;
	private final ReadOnlyHerbTracker herbTracker;

	@Inject
	public CoreTimeTrackingAdapter(ConfigManager configManager)
	{
		birdHouseTracker = new ReadOnlyBirdHouseTracker(configManager);
		herbTracker = new ReadOnlyHerbTracker(configManager);
	}

	public void reload()
	{
		birdHouseTracker.reload();
		herbTracker.reload();
	}

	public Optional<ActivityState> observeHerbRun(Instant now)
	{
		return observeHerbRun(herbTracker.getPredictions(), now);
	}

	static Optional<ActivityState> observeHerbRun(Map<HerbPatch, HerbPatchPrediction> predictions,
		Instant now)
	{
		if (predictions.isEmpty())
		{
			return Optional.empty();
		}
		int active = 0;
		int ready = 0;
		int unhealthy = 0;
		long latestReady = 0;
		StringBuilder cycle = new StringBuilder("core-herb-run");
		for (HerbPatch patch : HerbPatch.values())
		{
			HerbPatchPrediction prediction = predictions.get(patch);
			if (prediction == null)
			{
				cycle.append(':').append(patch.name()).append("=missing");
				continue;
			}
			if (prediction.getState() == HerbPatchState.State.GROWING
				|| prediction.getState() == HerbPatchState.State.HARVESTABLE)
			{
				cycle.append(':').append(patch.name()).append("=ACTIVE@")
					.append(prediction.getDoneEstimate());
				active++;
				long done = prediction.getDoneEstimate();
				latestReady = Math.max(latestReady, done);
				if (prediction.getState() == HerbPatchState.State.HARVESTABLE
					|| done <= now.getEpochSecond())
				{
					ready++;
				}
			}
			else if (prediction.getState() == HerbPatchState.State.DISEASED
				|| prediction.getState() == HerbPatchState.State.DEAD)
			{
				cycle.append(':').append(patch.name()).append('=').append(prediction.getState());
				unhealthy++;
			}
			else
			{
				cycle.append(':').append(patch.name()).append('=').append(prediction.getState());
			}
		}
		ActivityStatus status = unhealthy > 0 ? ActivityStatus.ATTENTION
			: active == 0 ? ActivityStatus.UNKNOWN
			: ready == active ? ActivityStatus.READY
			: ready > 0 ? ActivityStatus.PARTIALLY_READY : ActivityStatus.GROWING;
		Long readyAt = active > 0 ? safeMultiply(latestReady, 1000L) : null;
		return Optional.of(new ActivityState(ActivityTrackingType.TRACKED_GAME, status,
			cycle.toString(), readyAt, unhealthy > 0 ? unhealthy : ready, active + unhealthy));
	}

	public Optional<ActivityState> observe(Instant now)
	{
		return observe(birdHouseTracker.getData(), now);
	}

	static Optional<ActivityState> observe(Map<BirdHouseSpace, BirdHouseData> data, Instant now)
	{
		if (data.isEmpty())
		{
			return Optional.empty();
		}

		int seeded = 0;
		int ready = 0;
		long latestReadyAtSeconds = 0;
		StringBuilder cycle = new StringBuilder("core-birdhouse");
		for (BirdHouseSpace space : BirdHouseSpace.values())
		{
			BirdHouseData entry = data.get(space);
			if (entry == null)
			{
				cycle.append(':').append(space.name()).append("=missing");
				continue;
			}
			cycle.append(':').append(space.name()).append('=').append(entry.getVarp())
				.append('@').append(entry.getTimestamp());
			if (BirdHouseState.fromVarpValue(entry.getVarp()) == BirdHouseState.SEEDED)
			{
				seeded++;
				long readyAt = safeAdd(entry.getTimestamp(),
					ReadOnlyBirdHouseTracker.BIRD_HOUSE_DURATION_SECONDS);
				latestReadyAtSeconds = Math.max(latestReadyAtSeconds, readyAt);
				if (readyAt <= now.getEpochSecond())
				{
					ready++;
				}
			}
		}

		ActivityStatus status = seeded == 0 ? ActivityStatus.UNKNOWN
			: ready == seeded ? ActivityStatus.READY
			: ready > 0 ? ActivityStatus.PARTIALLY_READY : ActivityStatus.GROWING;
		Long readyAtMillis = seeded > 0
			? safeMultiply(latestReadyAtSeconds, 1000L) : null;
		return Optional.of(new ActivityState(ActivityTrackingType.TRACKED_GAME, status,
			cycle.toString(), readyAtMillis, ready, seeded));
	}

	private static long safeAdd(long value, long addition)
	{
		try
		{
			return Math.addExact(value, addition);
		}
		catch (ArithmeticException ex)
		{
			return Long.MAX_VALUE;
		}
	}

	private static long safeMultiply(long value, long multiplier)
	{
		try
		{
			return Math.multiplyExact(value, multiplier);
		}
		catch (ArithmeticException ex)
		{
			return Long.MAX_VALUE;
		}
	}
}

package com.efficientskilling.tracking.timetracking;

import com.efficientskilling.planner.tracking.ActivityState;
import com.efficientskilling.planner.tracking.ReminderState;
import com.efficientskilling.planner.tracking.TimedActivityState;
import com.google.gson.Gson;
import java.util.Optional;
import javax.inject.Inject;
import net.runelite.client.config.ConfigManager;

/** Stores our reminder controls separately from the core Time Tracking data we consume. */
public final class TrackedReminderProfileStore
{
	private static final String GROUP = "efficient-skilling";
	private static final String ACTIVITY_PREFIX = "tracked.activity.";
	private final ConfigManager configManager;
	private final Gson gson;

	@Inject
	public TrackedReminderProfileStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	public Optional<TimedActivityState> loadActivity(String activityId)
	{
		String stored = configManager.getRSProfileConfiguration(GROUP, key(activityId));
		if (stored == null)
		{
			return Optional.empty();
		}
		try
		{
			TimedActivityState parsed = gson.fromJson(stored, TimedActivityState.class);
			if (parsed == null || parsed.getActivity() == null || parsed.getReminder() == null)
			{
				return Optional.empty();
			}
			ActivityState activity = parsed.getActivity();
			ReminderState reminder = parsed.getReminder();
			return Optional.of(new TimedActivityState(new ActivityState(activity.getTrackingType(),
				activity.getStatus(), activity.getCycleId(), activity.getReadyAtEpochMillis(),
				activity.getProgress(), activity.getTarget()), new ReminderState(reminder.isEnabled(),
				reminder.getSuppressedUntilEpochMillis(), reminder.getLastNotifiedCycleId(),
				reminder.getGeneration(), reminder.getLastNotifiedGeneration())));
		}
		catch (RuntimeException ex)
		{
			return Optional.empty();
		}
	}

	public void saveActivity(String activityId, TimedActivityState state)
	{
		configManager.setRSProfileConfiguration(GROUP, key(activityId), gson.toJson(state));
	}

	private static String key(String activityId)
	{
		if (activityId == null || !activityId.matches("[a-z0-9-]+"))
		{
			throw new IllegalArgumentException("activityId must contain lowercase letters, digits, or hyphens");
		}
		return ACTIVITY_PREFIX + activityId;
	}
}

