package com.efficientskilling;

import java.util.Collections;
import java.util.List;

public final class Guide
{
	private final List<GuideStep> steps;
	private final Integer uncoveredLevel;

	Guide(List<GuideStep> steps, Integer uncoveredLevel)
	{
		this.steps = Collections.unmodifiableList(steps);
		this.uncoveredLevel = uncoveredLevel;
	}

	public List<GuideStep> getSteps()
	{
		return steps;
	}

	public Integer getUncoveredLevel()
	{
		return uncoveredLevel;
	}

	public boolean isComplete()
	{
		return uncoveredLevel == null;
	}

	public Double getMinimumHours()
	{
		return sumHours(true);
	}

	public Double getMaximumHours()
	{
		return sumHours(false);
	}

	private Double sumHours(boolean minimum)
	{
		double total = 0;
		for (GuideStep step : steps)
		{
			Double hours = minimum ? step.getMinimumHours() : step.getMaximumHours();
			if (hours == null)
			{
				return null;
			}
			total += hours;
		}
		return total;
	}
}

