package com.efficientskilling;

import com.efficientskilling.planner.AccountStats;
import com.efficientskilling.planner.PlanTimelineStep;
import com.efficientskilling.planner.SkillProgression;
import com.efficientskilling.planner.SkillProgressionStep;
import com.efficientskilling.planner.SkillStrategyPreferences;
import com.efficientskilling.planner.WholeAccountPlan;
import com.efficientskilling.planner.bank.BankItemSnapshot;
import com.efficientskilling.planner.bankedxp.ActivitySelectionSource;
import com.efficientskilling.planner.bankedxp.CalculationKind;
import com.efficientskilling.planner.bankedxp.ResourceConversion;
import com.efficientskilling.planner.bankedxp.SkillBankedExperienceProjection;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.text.NumberFormat;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.inject.Singleton;
import net.runelite.api.Experience;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;

/** Pure presentation mapping from planner domain objects to the Path to Max view model. */
@Singleton
public final class PathToMaxModelFactory
{
	public List<PathToMaxViewModel.SkillPlanRow> skillPlans(WholeAccountPlan plan,
		Map<Skill, SkillBankedExperienceProjection> projections,
		Map<Quest, QuestState> questStates, Map<RequirementItem, Long> ownedItems,
		boolean hasStorageEvidence, SkillStrategyPreferences strategies)
	{
		List<PathToMaxViewModel.SkillPlanRow> rows = new ArrayList<>();
		Map<Skill, Integer> actualLevels = new EnumMap<>(Skill.class);
		for (SkillProgression progression : plan.getProgressions())
			actualLevels.put(progression.getSkill(), Experience.getLevelForXp(progression.getCurrentExperience()));
		for (SkillProgression progression : plan.getProgressions())
		{
			SkillBankedExperienceProjection projection = projections.get(progression.getSkill());
			List<PathToMaxViewModel.SkillStageRow> stages = new ArrayList<>();
			List<PathToMaxViewModel.RequirementRow> requirements = new ArrayList<>();
			for (SkillProgressionStep step : progression.getSteps())
			{
				String unlock = step.getMethod().getRequirements().isEmpty() ? "No unlock dependency"
					: String.join(", ", step.getMethod().getRequirements());
				String coverage = stages.isEmpty() && progression.getCreditedBankedExperience() > 0
					? formatCount(progression.getCreditedBankedExperience()) + " stored XP applied before this stage"
					: "Training XP required";
				List<PathToMaxViewModel.ReferenceLink> references = new ArrayList<>();
				references.add(new PathToMaxViewModel.ReferenceLink("Primary source", step.getMethod().getSource()));
				for (MethodLink link : step.getMethod().getAdditionalLinks())
					references.add(new PathToMaxViewModel.ReferenceLink(link.getLabel(), link.getUrl()));
				stages.add(new PathToMaxViewModel.SkillStageRow(step.getFromLevel(), step.getToLevel(),
					step.getMethod().getName(), unlock, coverage, references));
				addDependencies(requirements, step, questStates, actualLevels, ownedItems, hasStorageEvidence);
			}
			if (progression.getUncoveredLevel() != null)
				addRequirement(requirements, "No reviewed method currently covers level "
					+ progression.getUncoveredLevel() + ".", PathToMaxViewModel.RequirementState.UNKNOWN);
			if (projection != null && projection.getLevelLockedExperience().signum() > 0)
				addRequirement(requirements, "Future-level stored conversions are visible below but are not inserted into the training stages yet.", PathToMaxViewModel.RequirementState.UNKNOWN);
			long bankedTenths = (long) progression.getCreditedBankedExperience() * 10;
			rows.add(new PathToMaxViewModel.SkillPlanRow(formatSkill(progression.getSkill()),
				Experience.getLevelForXp(progression.getCurrentExperience()),
				Math.max(0, AccountStats.XP_FOR_99 - progression.getCurrentExperience()), bankedTenths,
				(long) progression.getRemainingExperience() * 10,
				projection == null ? java.util.Collections.emptyList() : conversionRows(projection),
				stages, requirements, progression.getStrategy().toString(),
				strategies.isOverridden(progression.getSkill()),
				"Selected from reviewed " + plan.getAccountProfile() + " routes using the "
					+ progression.getStrategy() + " style"
					+ (strategies.isOverridden(progression.getSkill())
						? " explicitly chosen for this skill." : " inherited from the account default.")));
		}
		return rows;
	}

	private static void addDependencies(List<PathToMaxViewModel.RequirementRow> requirements,
		SkillProgressionStep step, Map<Quest, QuestState> quests, Map<Skill, Integer> levels,
		Map<RequirementItem, Long> items, boolean storageKnown)
	{
		for (MethodDependency dependency : step.getMethod().getDependencies())
		{
			PathToMaxViewModel.RequirementState state = PathToMaxViewModel.RequirementState.UNKNOWN;
			if (dependency.getType() == MethodDependencyType.QUEST_COMPLETED)
			{
				QuestState quest = quests.get(dependency.getQuest());
				state = quest == null ? PathToMaxViewModel.RequirementState.UNKNOWN : quest == QuestState.FINISHED
					? PathToMaxViewModel.RequirementState.SATISFIED : PathToMaxViewModel.RequirementState.UNSATISFIED;
			}
			else if (dependency.getType() == MethodDependencyType.SKILL_LEVEL)
				state = levels.getOrDefault(dependency.getSkill(), 1) >= dependency.getLevel()
					? PathToMaxViewModel.RequirementState.SATISFIED : PathToMaxViewModel.RequirementState.UNSATISFIED;
			else if (dependency.getType() == MethodDependencyType.ITEM_OWNED)
				state = !storageKnown ? PathToMaxViewModel.RequirementState.UNKNOWN
					: items.getOrDefault(dependency.getItem(), 0L) >= dependency.getQuantity()
						? PathToMaxViewModel.RequirementState.SATISFIED : PathToMaxViewModel.RequirementState.UNSATISFIED;
			addRequirement(requirements, dependency.getLabel(), state);
		}
		for (String requirement : step.getMethod().getRequirements())
		{
			if (coveredByTypedDependency(requirement, step.getMethod().getDependencies())) continue;
			Quest quest = QuestRequirementMatcher.match(requirement, quests.keySet());
			PathToMaxViewModel.RequirementState state = PathToMaxViewModel.RequirementState.UNKNOWN;
			if (quest != null)
			{
				QuestState questState = quests.get(quest);
				state = questState == QuestState.FINISHED ? PathToMaxViewModel.RequirementState.SATISFIED
					: questState == null ? PathToMaxViewModel.RequirementState.UNKNOWN
						: PathToMaxViewModel.RequirementState.UNSATISFIED;
			}
			else
			{
				PathToMaxViewModel.RequirementState levelState = legacyLevelState(requirement, levels);
				if (levelState != null) state = levelState;
			}
			addRequirement(requirements, requirement, state);
		}
	}

	public Map<RequirementItem, Long> requirementItems(BankItemSnapshot storage)
	{
		Map<RequirementItem, Long> quantities = new EnumMap<>(RequirementItem.class);
		if (storage == null) return quantities;
		for (RequirementItem item : RequirementItem.values())
		{
			long quantity = 0;
			for (int itemId : item.getItemIds()) quantity += storage.quantity(itemId);
			quantities.put(item, quantity);
		}
		return quantities;
	}

	public List<PathToMaxViewModel.OverviewStepRow> overview(WholeAccountPlan plan)
	{
		List<PathToMaxViewModel.OverviewStepRow> rows = new ArrayList<>();
		int priority = 1;
		for (SkillProgression progression : plan.getProgressions())
		{
			if (progression.isComplete()) continue;
			if (progression.getSteps().isEmpty())
			{
				rows.add(new PathToMaxViewModel.OverviewStepRow(formatSkill(progression.getSkill()),
					"Route coverage required", formatCount(progression.getRemainingExperience())
						+ " XP remains, but the reviewed catalogue has no method from level "
						+ progression.getUncoveredLevel() + ".", "UNCOVERED"));
				continue;
			}
			SkillProgressionStep first = progression.getSteps().get(0);
			String detail = formatCount(progression.getRemainingExperience()) + " XP remains after "
				+ formatCount(progression.getCreditedBankedExperience()) + " currently usable stored XP; start with levels "
				+ first.getFromLevel() + "-" + first.getToLevel() + ".";
			rows.add(new PathToMaxViewModel.OverviewStepRow(formatSkill(progression.getSkill()),
				first.getMethod().getName(), detail, "LARGEST GRIND " + priority++));
		}
		return rows;
	}

	public List<PathToMaxViewModel.TimelineStepRow> timeline(WholeAccountPlan plan)
	{
		List<PathToMaxViewModel.TimelineStepRow> rows = new ArrayList<>();
		for (PlanTimelineStep step : plan.getTimelineSteps())
			rows.add(new PathToMaxViewModel.TimelineStepRow(formatSkill(step.getSkill()),
				step.getFromLevel(), step.getToLevel(), step.getMethod(), step.getRequiredExperience(),
				step.getMinimumHours(), step.getMaximumHours(), step.getPriorityBlockId(),
				step.getPriorityBlockOrder(), step.getStepOrder(),
				PathToMaxViewModel.TimelineStepRow.ActionType.valueOf(step.getActionType().name()),
				step.getActionId(), step.getNotes()));
		return rows;
	}

	private static List<PathToMaxViewModel.ConversionRow> conversionRows(SkillBankedExperienceProjection projection)
	{
		List<PathToMaxViewModel.ConversionRow> rows = new ArrayList<>();
		for (ResourceConversion conversion : projection.getConversions())
		{
			PathToMaxViewModel.ConversionStatus status;
			switch (conversion.getStatus())
			{
				case IGNORED: status = PathToMaxViewModel.ConversionStatus.IGNORED; break;
				case LEVEL_LOCKED: status = PathToMaxViewModel.ConversionStatus.LEVEL_LOCKED; break;
				case UNSUPPORTED: status = PathToMaxViewModel.ConversionStatus.UNAVAILABLE; break;
				default: status = PathToMaxViewModel.ConversionStatus.CREDITED;
			}
			String method = conversion.getActivity() == null ? "No supported conversion" : conversion.getActivity().getName();
			if (conversion.getCalculationKind() == CalculationKind.EXPECTED) method += " (expected value)";
			if (!conversion.getWarnings().isEmpty()) method += " - " + conversion.getWarnings().get(0);
			String resource = formatEnumName(conversion.getResource().name())
				+ (conversion.getResource().isByDose() ? " doses" : "");
			rows.add(new PathToMaxViewModel.ConversionRow(resource, conversion.getQuantity(), method,
				toTenths(conversion.getPotentialExperience()),
				conversion.getSelectionSource() == ActivitySelectionSource.EXPLICIT
					? PathToMaxViewModel.ChoiceKind.IMPORTED : PathToMaxViewModel.ChoiceKind.DEFAULT, status));
		}
		return rows;
	}

	private static void addRequirement(List<PathToMaxViewModel.RequirementRow> rows, String label,
		PathToMaxViewModel.RequirementState state)
	{
		String comparable = label.toLowerCase(Locale.ROOT).replaceFirst("^complete\\s+", "");
		for (int i = 0; i < rows.size(); i++)
		{
			String existing = rows.get(i).getLabel().toLowerCase(Locale.ROOT).replaceFirst("^complete\\s+", "");
			if (existing.equals(comparable) || existing.startsWith(comparable + " for ") || comparable.startsWith(existing + " for "))
			{
				if (rows.get(i).getState() == PathToMaxViewModel.RequirementState.UNKNOWN
					&& state != PathToMaxViewModel.RequirementState.UNKNOWN)
					rows.set(i, new PathToMaxViewModel.RequirementRow(label, state));
				return;
			}
		}
		rows.add(new PathToMaxViewModel.RequirementRow(label, state));
	}

	private static boolean coveredByTypedDependency(String requirement, List<MethodDependency> dependencies)
	{
		String key = requirement.toLowerCase(Locale.ROOT).replace(" recommended", "").trim();
		for (MethodDependency dependency : dependencies)
		{
			String label = dependency.getLabel().toLowerCase(Locale.ROOT)
				.replaceFirst("^(complete|reach)\\s+", "").replace(" observed in storage", "").trim();
			if (label.contains(key) || key.contains(label)) return true;
		}
		return false;
	}

	private static PathToMaxViewModel.RequirementState legacyLevelState(String requirement,
		Map<Skill, Integer> actualLevels)
	{
		java.util.regex.Matcher matcher = java.util.regex.Pattern.compile(
			"^(\\d{1,2})\\s+([A-Za-z]+)(?:\\s+(?:level|required|recommended))?$",
			java.util.regex.Pattern.CASE_INSENSITIVE).matcher(requirement.trim());
		if (!matcher.matches()) return null;
		try
		{
			Skill skill = Skill.valueOf(matcher.group(2).toUpperCase(Locale.ROOT));
			return actualLevels.getOrDefault(skill, 1) >= Integer.parseInt(matcher.group(1))
				? PathToMaxViewModel.RequirementState.SATISFIED : PathToMaxViewModel.RequirementState.UNSATISFIED;
		}
		catch (RuntimeException ignored) { return null; }
	}

	private static long toTenths(BigDecimal value) { return value.movePointRight(1).setScale(0, RoundingMode.HALF_UP).longValue(); }
	private static String formatCount(long value) { return NumberFormat.getIntegerInstance(Locale.US).format(value); }
	private static String formatSkill(Skill skill)
	{
		String lower = skill.name().toLowerCase(Locale.ROOT).replace('_', ' ');
		return Character.toUpperCase(lower.charAt(0)) + lower.substring(1);
	}
	private static String formatEnumName(String value)
	{
		String lower = value.toLowerCase(Locale.ROOT).replace('_', ' ');
		StringBuilder result = new StringBuilder();
		for (String word : lower.split(" "))
		{
			if (result.length() > 0) result.append(' ');
			result.append(Character.toUpperCase(word.charAt(0))).append(word.substring(1));
		}
		return result.toString();
	}
}

package com.efficientskilling;

import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
