/** Progressive level editor used to build a Path to Max plan without live account stats. */
final class ManualStatsPanel extends JPanel
{
	private static final Color ACCENT = new Color(255, 152, 31);
	private static final Color MUTED = new Color(170, 170, 170);
	private final Consumer<Map<Skill, Integer>> listener;
	private final Map<Skill, JSpinner> levels = new EnumMap<>(Skill.class);
	private final JPanel rows = verticalPanel();
	private final JButton reveal = button("Enter manual levels");

	ManualStatsPanel(Consumer<Map<Skill, Integer>> listener)
	{
		this.listener = listener;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
			BorderFactory.createEmptyBorder(16, 18, 16, 18)));
		setAlignmentX(Component.LEFT_ALIGNMENT);
		JLabel caption = new JLabel("MANUAL / OFFLINE STATS");
		caption.setForeground(ACCENT);
		caption.setFont(caption.getFont().deriveFont(Font.BOLD));
		caption.setAlignmentX(Component.LEFT_ALIGNMENT);
		add(caption);
		add(Box.createVerticalStrut(6));
		JLabel help = new JLabel("<html><div style='width:620px'>Build a plan while logged out. Each level uses the minimum XP for that level; live exact XP replaces it after login.</div></html>");
		help.setForeground(MUTED);
		help.setAlignmentX(Component.LEFT_ALIGNMENT);
		add(help);
		add(Box.createVerticalStrut(10));
		rows.setVisible(false);
		for (Skill skill : Skill.values())
		{
			if ("OVERALL".equals(skill.name())) continue;
			JSpinner spinner = new JSpinner(new SpinnerNumberModel(1, 1, 99, 1));
			spinner.setMaximumSize(new Dimension(82, 30));
			spinner.getAccessibleContext().setAccessibleName(skill.getName() + " manual level");
			levels.put(skill, spinner);
			JPanel row = new JPanel();
			row.setLayout(new BoxLayout(row, BoxLayout.X_AXIS));
			row.setOpaque(false);
			row.setAlignmentX(Component.LEFT_ALIGNMENT);
			JLabel label = new JLabel(skill.getName());
			label.setForeground(Color.WHITE);
			row.add(label);
			row.add(Box.createHorizontalGlue());
			row.add(spinner);
			row.setMaximumSize(new Dimension(920, 36));
			rows.add(row);
			rows.add(Box.createVerticalStrut(3));
		}
		JButton apply = button("Build plan from manual levels");
		apply.addActionListener(event -> listener.accept(snapshot()));
		apply.getAccessibleContext().setAccessibleDescription("Build a Path to Max plan using the entered levels");
		rows.add(Box.createVerticalStrut(8));
		rows.add(apply);
		reveal.addActionListener(event -> setEditorVisible(!rows.isVisible()));
		add(reveal);
		add(Box.createVerticalStrut(8));
		add(rows);
		SettingsPanelLayout.bind(this);
	}

	void setLevels(Map<Skill, Integer> values)
	{
		if (values == null) return;
		values.forEach((skill, level) ->
		{
			JSpinner spinner = levels.get(skill);
			if (spinner != null && level != null) spinner.setValue(Math.max(1, Math.min(99, level)));
		});
	}

	Map<Skill, Integer> snapshot()
	{
		EnumMap<Skill, Integer> copy = new EnumMap<>(Skill.class);
		levels.forEach((skill, spinner) -> copy.put(skill, (Integer) spinner.getValue()));
		return Collections.unmodifiableMap(copy);
	}

	boolean isEditorVisible() { return rows.isVisible(); }
	void setEditorVisible(boolean visible)
	{
		rows.setVisible(visible);
		reveal.setText(visible ? "Hide manual levels" : "Enter manual levels");
		SettingsPanelLayout.refresh(this);
	}

	private static JPanel verticalPanel()
	{
		JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setOpaque(false);
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		return panel;
	}

	private static JButton button(String text)
	{
		JButton button = new JButton(text);
		button.setForeground(Color.WHITE);
		button.setBackground(new Color(55, 55, 55));
		button.setFocusPainted(true);
		button.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(new Color(75, 75, 75)),
			BorderFactory.createEmptyBorder(7, 12, 7, 12)));
		button.setAlignmentX(Component.LEFT_ALIGNMENT);
		return button;
	}
}

package com.efficientskilling;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.net.URI;
import java.net.URISyntaxException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Skill;
import net.runelite.api.Quest;

@Singleton
public class GuideService
{
	private static final String DATA_PATH = "/com/efficientskilling/training-methods.json";
	private final Gson gson;
	private volatile List<TrainingMethod> methods = Collections.emptyList();
	private volatile String reviewedAt;

	@Inject
	GuideService(Gson gson)
	{
		this.gson = gson;
	}

	GuideService(Gson gson, InputStream inputStream)
	{
		this.gson = gson;
		methods = readMethods(gson, inputStream);
	}

	synchronized void load()
	{
		if (!methods.isEmpty())
		{
			return;
		}
		methods = readMethods(gson, GuideService.class.getResourceAsStream(DATA_PATH));
	}

	/** Quests referenced by machine-readable route requirements. */
	public Set<Quest> getReferencedQuests()
	{
		Set<Quest> quests = new java.util.LinkedHashSet<>();
		for (TrainingMethod method : methods)
		{
			for (MethodDependency dependency : method.getDependencies())
			{
				if (dependency.getType() == MethodDependencyType.QUEST_COMPLETED)
				{
					quests.add(dependency.getQuest());
				}
			}
			for (String requirement : method.getRequirements())
			{
				Quest quest = QuestRequirementMatcher.match(requirement,
					java.util.Arrays.asList(Quest.values()));
				if (quest != null)
				{
					quests.add(quest);
				}
			}
		}
		return Collections.unmodifiableSet(quests);
	}

	List<TrainingMethod> getReviewedMethods()
	{
		return methods;
	}

	private List<TrainingMethod> readMethods(Gson gson, InputStream inputStream)
	{
		if (inputStream == null)
		{
			throw new IllegalStateException("Missing guide data " + DATA_PATH);
		}

		try (InputStream stream = inputStream;
			 InputStreamReader reader = new InputStreamReader(stream, StandardCharsets.UTF_8))
		{
			TrainingCatalogue catalogue = gson.fromJson(reader, TrainingCatalogue.class);
			if (catalogue == null || catalogue.getSchemaVersion() != 4)
			{
				throw new IllegalStateException("Unsupported or missing guide data schema version");
			}
			if (catalogue.getReviewedAt() == null || catalogue.getReviewedAt().trim().isEmpty())
			{
				throw new IllegalStateException("Guide data has no research review date");
			}
			reviewedAt = catalogue.getReviewedAt().trim();
			List<TrainingMethod> loaded = catalogue.getMethods();
			if (loaded == null || loaded.isEmpty())
			{
				throw new IllegalStateException("Guide data is empty");
			}
			for (int i = 0; i < loaded.size(); i++)
			{
				validate(loaded.get(i), i);
			}
			validateUnambiguous(loaded);
			return Collections.unmodifiableList(new ArrayList<>(loaded));
		}
		catch (IOException ex)
		{
			throw new IllegalStateException("Unable to read guide data", ex);
		}
	}

	private static void validateUnambiguous(List<TrainingMethod> loaded)
	{
		for (Skill skill : Skill.values())
		{
			for (AccountProfile account : AccountProfile.values())
			{
				for (GuideStrategy strategy : GuideStrategy.values())
				{
					for (int level = 1; level <= 98; level++)
					{
						int bestSpecificity = -1;
						int bestFromLevel = -1;
						TrainingMethod selected = null;
						TrainingMethod competing = null;
						for (TrainingMethod candidate : loaded)
						{
							if (!candidate.appliesTo(skill, level, account, strategy))
							{
								continue;
							}
							int specificity = candidate.getAccountSpecificity();
							if (specificity > bestSpecificity
								|| (specificity == bestSpecificity
								&& candidate.getFromLevel() > bestFromLevel))
							{
								bestSpecificity = specificity;
								bestFromLevel = candidate.getFromLevel();
								selected = candidate;
								competing = null;
							}
							else if (specificity == bestSpecificity
								&& candidate.getFromLevel() == bestFromLevel)
							{
								competing = candidate;
							}
						}
						if (competing != null)
						{
							throw new IllegalStateException("Ambiguous guide methods for "
								+ skill + " / " + account + " / " + strategy + " at level "
								+ level + ": " + selected.getName() + " and " + competing.getName());
						}
					}
				}
			}
		}
	}

	private static void validate(TrainingMethod method, int index)
	{
		if (method == null)
		{
			throw new IllegalStateException("Null guide method at index " + index);
		}
		try
		{
			method.getSkill();
		}
		catch (RuntimeException ex)
		{
			throw new IllegalStateException("Invalid skill at guide method index " + index, ex);
		}
		if (method.getFromLevel() < 1 || method.getToLevel() > 98
			|| method.getFromLevel() > method.getToLevel())
		{
			throw new IllegalStateException("Invalid level range at guide method index " + index);
		}
		if (method.getName() == null || method.getName().trim().isEmpty()
			|| method.getDescription() == null || method.getDescription().trim().isEmpty())
		{
			throw new IllegalStateException("Missing guide text at method index " + index);
		}
		if (!isValidHttpsUrl(method.getSource()))
		{
			throw new IllegalStateException("Invalid source at guide method index " + index);
		}
		Integer low = method.getXpPerHourLow();
		Integer high = method.getXpPerHourHigh();
		if ((low == null) != (high == null) || (low != null && (low <= 0 || high < low)))
		{
			throw new IllegalStateException("Invalid XP rate range at guide method index " + index);
		}
		validateItemFlows(method, index);
		validateAlternatives(method, index);
		validateAdditionalLinks(method, index);
		validateDependencies(method, index);
	}

	private static void validateDependencies(TrainingMethod method, int index)
	{
		Set<String> identities = new HashSet<>();
		for (MethodDependency dependency : method.getDependencies())
		{
			if (dependency == null || dependency.getType() == null || isBlank(dependency.getLabel()))
			{
				throw new IllegalStateException("Invalid dependency at method index " + index);
			}
			String identity;
			switch (dependency.getType())
			{
			case SKILL_LEVEL:
					Skill dependencySkill;
					try
					{
						dependencySkill = dependency.getSkill();
					}
					catch (RuntimeException ex)
					{
						throw new IllegalStateException("Invalid dependency skill at method index " + index, ex);
					}
					if (dependencySkill == null || dependency.getLevel() == null
						|| dependency.getLevel() < 1 || dependency.getLevel() > 99
						|| dependency.getId() != null || dependency.getQuest() != null
						|| dependency.getItem() != null
						|| (dependencySkill == method.getSkill()
							&& dependency.getLevel() > method.getFromLevel()))
					{
						throw new IllegalStateException("Invalid skill dependency at method index " + index);
					}
					identity = "SKILL_LEVEL:" + dependencySkill + ":" + dependency.getLevel();
					break;
				case QUEST_COMPLETED:
					Quest quest;
					try
					{
						quest = dependency.getQuest();
					}
					catch (RuntimeException ex)
					{
						throw new IllegalStateException("Invalid quest dependency at method index " + index, ex);
					}
					if (quest == null || dependency.getId() != null || dependency.getLevel() != null
						|| dependency.getSkill() != null)
					{
						throw new IllegalStateException("Invalid quest dependency at method index " + index);
					}
					identity = "QUEST_COMPLETED:" + quest;
					break;
				case ITEM_OWNED:
					RequirementItem item;
					try
					{
						item = dependency.getItem();
					}
					catch (RuntimeException ex)
					{
						throw new IllegalStateException("Invalid item dependency at method index " + index, ex);
					}
					if (item == null || dependency.getQuantity() < 1 || dependency.getId() != null
						|| dependency.getLevel() != null || dependency.getSkill() != null
						|| dependency.getQuest() != null)
					{
						throw new IllegalStateException("Invalid item dependency at method index " + index);
					}
					identity = "ITEM_OWNED:" + item;
					break;
				case UNLOCK:
				case ACQUISITION:
					if (!isValidDependencyId(dependency.getId()) || dependency.getLevel() != null
						|| dependency.getQuest() != null || dependency.getItem() != null)
					{
						throw new IllegalStateException("Invalid manual dependency at method index " + index);
					}
					try
					{
						if (dependency.getSkill() != null)
						{
							throw new IllegalStateException("Manual dependencies cannot declare a skill at method index " + index);
						}
					}
					catch (RuntimeException ex)
					{
						throw new IllegalStateException("Invalid manual dependency skill at method index " + index, ex);
					}
					identity = "MANUAL:" + dependency.getId();
					break;
				default:
					throw new IllegalStateException("Unsupported dependency type at method index " + index);
			}
			if (!identities.add(identity))
			{
				throw new IllegalStateException("Duplicate dependency at method index " + index);
			}
		}
	}

	private static boolean isValidDependencyId(String value)
	{
		return value != null && value.matches("[a-z0-9]+(?:-[a-z0-9]+)*");
	}

	private static void validateAdditionalLinks(TrainingMethod method, int index)
	{
		Set<String> labels = new HashSet<>();
		Set<String> urls = new HashSet<>();
		for (MethodLink link : method.getAdditionalLinks())
		{
			if (link == null || isBlank(link.getLabel()) || !isValidHttpsUrl(link.getUrl()))
			{
				throw new IllegalStateException("Invalid additional link at method index " + index);
			}
			String label = link.getLabel().trim().toLowerCase(Locale.ROOT);
			String url = link.getUrl().trim();
			if (!labels.add(label) || !urls.add(url) || url.equals(method.getSource()))
			{
				throw new IllegalStateException("Duplicate additional link at method index " + index);
			}
		}
	}

	private static boolean isValidHttpsUrl(String value)
	{
		if (isBlank(value))
		{
			return false;
		}
		try
		{
			URI uri = new URI(value.trim());
			return "https".equalsIgnoreCase(uri.getScheme())
				&& !isBlank(uri.getHost())
				&& uri.getUserInfo() == null;
		}
		catch (URISyntaxException ex)
		{
			return false;
		}
	}

	private static void validateAlternatives(TrainingMethod method, int index)
	{
		List<String> names = new ArrayList<>();
		for (TrainingAlternative alternative : method.getAlternatives())
		{
			if (alternative == null || isBlank(alternative.getName())
				|| alternative.getBenefits().isEmpty()
				|| alternative.getConsiderations().isEmpty())
			{
				throw new IllegalStateException("Incomplete training alternative at method index " + index);
			}
			if (names.contains(alternative.getName()))
			{
				throw new IllegalStateException("Duplicate training alternative at method index " + index);
			}
			names.add(alternative.getName());
			validateFacts(alternative.getRequirements(), index);
			validateFacts(alternative.getBenefits(), index);
			validateFacts(alternative.getConsiderations(), index);
		}
	}

	private static void validateFacts(List<SourcedFact> facts, int index)
	{
		for (SourcedFact fact : facts)
		{
			if (fact == null || isBlank(fact.getText())
				|| !isApprovedResearchSource(fact.getSource()))
			{
				throw new IllegalStateException("Invalid sourced alternative fact at method index " + index);
			}
		}
	}

	private static boolean isApprovedResearchSource(String source)
	{
		return source != null && (source.startsWith("https://oldschool.runescape.wiki/")
			|| source.startsWith("https://templeosrs.com/"));
	}

	private static boolean isBlank(String value)
	{
		return value == null || value.trim().isEmpty();
	}

	private static void validateItemFlows(TrainingMethod method, int index)
	{
		boolean hasFlows = !method.getInputsPerHour().isEmpty()
			|| !method.getOutputsPerHour().isEmpty();
		if (hasFlows != (method.getItemFlowXpPerHour() != null)
			|| (method.getItemFlowXpPerHour() != null && method.getItemFlowXpPerHour() <= 0))
		{
			throw new IllegalStateException("Item flows require a positive XP/hour basis at method index " + index);
		}
		if (hasFlows && !isValidHttpsUrl(method.getItemFlowSource()))
		{
			throw new IllegalStateException("Item flows require a direct source at method index " + index);
		}
		for (ItemFlow flow : method.getInputsPerHour())
		{
			validateItemFlow(flow, index);
		}
		for (ItemFlow flow : method.getOutputsPerHour())
		{
			validateItemFlow(flow, index);
		}
	}

	private static void validateItemFlow(ItemFlow flow, int index)
	{
		if (flow == null || flow.getItem() == null
			|| !Double.isFinite(flow.getQuantityPerHour()) || flow.getQuantityPerHour() <= 0)
		{
			throw new IllegalStateException("Invalid item flow at method index " + index);
		}
	}

	public Guide buildGuide(Skill skill, int currentLevel, int targetLevel,
		AccountProfile account, GuideStrategy strategy)
	{
		return buildGuide(skill, currentLevel, targetLevel, account, strategy,
			com.efficientskilling.planner.MethodExclusions.none());
	}

	public Guide buildGuide(Skill skill, int currentLevel, int targetLevel,
		AccountProfile account, GuideStrategy strategy,
		com.efficientskilling.planner.MethodExclusions exclusions)
	{
		if (currentLevel < 1 || targetLevel > 99 || currentLevel >= targetLevel)
		{
			return new Guide(Collections.emptyList(), currentLevel >= targetLevel ? null : currentLevel);
		}

		List<GuideStep> steps = new ArrayList<>();
		int level = currentLevel;
		while (level < targetLevel)
		{
			TrainingMethod method = selectMethod(skill, level, account, strategy, exclusions);
			if (method == null)
			{
				return new Guide(steps, level);
			}

			int endLevel = Math.min(targetLevel, method.getToLevel() + 1);
			endLevel = Math.min(endLevel,
				nextMethodBoundary(skill, level, account, strategy, method, endLevel, exclusions));
			steps.add(new GuideStep(level, endLevel, method));
			level = endLevel;
		}

		return new Guide(steps, null);
	}

	public boolean hasData(Skill skill)
	{
		return methods.stream().anyMatch(method -> method.getSkill() == skill);
	}

	public String getReviewedAt()
	{
		return reviewedAt;
	}

	private TrainingMethod selectMethod(Skill skill, int level, AccountProfile account, GuideStrategy strategy)
	{
		return selectMethod(skill, level, account, strategy,
			com.efficientskilling.planner.MethodExclusions.none());
	}

	private TrainingMethod selectMethod(Skill skill, int level, AccountProfile account,
		GuideStrategy strategy, com.efficientskilling.planner.MethodExclusions exclusions)
	{
		return methods.stream()
			.filter(method -> method.appliesTo(skill, level, account, strategy))
			.filter(method -> !exclusions.excludes(skill, method.getName()))
			.max(Comparator.comparingInt(TrainingMethod::getAccountSpecificity)
				.thenComparingInt(TrainingMethod::getFromLevel))
			.orElse(null);
	}

	private int nextMethodBoundary(Skill skill, int level, AccountProfile account,
		GuideStrategy strategy, TrainingMethod currentMethod, int fallback,
		com.efficientskilling.planner.MethodExclusions exclusions)
	{
		return methods.stream()
			.filter(method -> method.getSkill() == skill)
			.filter(method -> method.getFromLevel() > level && method.getFromLevel() < fallback)
			.filter(method -> method.appliesTo(skill, method.getFromLevel(), account, strategy))
			.filter(method -> !exclusions.excludes(skill, method.getName()))
			.filter(method -> selectMethod(skill, method.getFromLevel(), account, strategy, exclusions) != currentMethod)
			.mapToInt(TrainingMethod::getFromLevel)
			.min()
			.orElse(fallback);
	}
}

