	public PathToMaxWindow(Window owner, TimedTaskListener timedTaskListener,
		SkillIconManager skillIconManager, int initialFontScale, IntConsumer fontScaleListener,
		SettingsListener settingsListener)
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			throw new IllegalStateException("PathToMaxWindow must be constructed on the EDT");
		}
		this.timedTaskListener = Objects.requireNonNull(timedTaskListener, "timedTaskListener");
		this.fontScaleListener = Objects.requireNonNull(fontScaleListener, "fontScaleListener");
		this.settingsListener = Objects.requireNonNull(settingsListener, "settingsListener");
		this.skillStrategyEditor = new SkillStrategyEditorPanel(settingsListener::onSkillStrategiesChanged);
		this.manualStatsPanel = new ManualStatsPanel(settingsListener::onManualLevelsApplied);
		this.methodExclusionPanel = new MethodExclusionPanel(
			settingsListener::onMethodRestored, settingsListener::onClearMethodExclusions);
		this.skillsMethodExclusionPanel = new MethodExclusionPanel(
			settingsListener::onMethodRestored, settingsListener::onClearMethodExclusions, true);
		this.skillDetailMethodExclusionPanel = new MethodExclusionPanel(
			settingsListener::onMethodRestored, settingsListener::onClearMethodExclusions, true);
		fontScalePercent = Math.max(80, Math.min(150, initialFontScale));
		this.skillIconManager = skillIconManager;
		skillListScroll.getViewport().addComponentListener(new ComponentAdapter()
		{
			@Override
			public void componentResized(ComponentEvent event)
			{
				updateSkillGridColumns();
			}
		});
		dialog = createFrame();
		countdownTimer = new Timer(1000, event -> refreshCountdowns());
		dialog.setDefaultCloseOperation(WindowConstants.HIDE_ON_CLOSE);
		dialog.setMinimumSize(new Dimension(820, 560));
		dialog.setSize(980, 680);
		dialog.setLocationRelativeTo(owner);
		dialog.getContentPane().setBackground(ColorScheme.DARK_GRAY_COLOR);
		dialog.getContentPane().setLayout(new BorderLayout());
		dialog.getContentPane().add(buildHeader(), BorderLayout.NORTH);
		dialog.getContentPane().add(buildNavigation(), BorderLayout.WEST);
		dialog.getContentPane().add(buildContent(), BorderLayout.CENTER);
		dialog.addWindowListener(new WindowAdapter()
		{
			@Override
			public void windowClosed(WindowEvent event)
			{
				countdownTimer.stop();
				disposed = true;
			}

			@Override
			public void windowOpened(WindowEvent event)
			{
				updateCountdownTimer();
			}

			@Override
			public void windowClosing(WindowEvent event)
			{
				countdownTimer.stop();
				settingsListener.onWindowHidden();
			}
		});
		applyModel(PathToMaxViewModel.empty());
		setFontScale(fontScalePercent);
	}

