	private static void refreshIntrinsicHeights(Component component)
	{
		if (component instanceof java.awt.Container)
		{
			for (Component child : ((java.awt.Container) component).getComponents())
			{
				refreshIntrinsicHeights(child);
			}
		}
		if (component instanceof javax.swing.JComponent
			&& Boolean.TRUE.equals(((javax.swing.JComponent) component)
				.getClientProperty("pathToMax.intrinsicHeight")))
		{
			Dimension preferred = component.getPreferredSize();
			Object boundedWidth = ((javax.swing.JComponent) component)
				.getClientProperty("pathToMax.maxWidth");
			int maximumWidth = boundedWidth instanceof Integer
				? (Integer) boundedWidth : Integer.MAX_VALUE;
			((javax.swing.JComponent) component).setMaximumSize(
				new Dimension(maximumWidth, preferred.height));
		}
	}

