	private static String storageEvidenceSummary(PathToMaxViewModel.StorageSummary storage)
	{
		if (storage.isBankApplied() && storage.isSeedVaultApplied())
		{
			return "Both sources are included. Overlapping items are counted once.";
		}
		if (storage.isBankApplied())
		{
			return "Bank supplies are included. Open the Seed Vault this session to include its contents.";
		}
		if (storage.isSeedVaultApplied())
		{
			return "Seed Vault supplies are included. Open the Bank this session to include its contents.";
		}
		return "No storage is currently included. Open the Bank or Seed Vault to add current evidence.";
	}

	private void applyModel(PathToMaxViewModel model)
	{
		if (disposed)
		{
			return;
		}
		String detailToRestore = selectedSkillDetail;
		java.awt.Point detailScroll = skillDetailScroll.getViewport().getViewPosition();
		currentModel = model;
		accountValue.setText(model.getAccountType());
		strategyValue.setText(model.getStrategy());
		totalValue.setText(model.getTotalLevel() + " / " + model.getMaxTotalLevel());
		overviewTotalValue.setText(model.getTotalLevel() + " / " + model.getMaxTotalLevel());
		overviewMaxedValue.setText(model.getMaxedSkillCount() + " / " + model.getSkillPlans().size());
		overviewRemainingValue.setText(formatCompact(model.getRemainingExperienceAfterBank()));
		overviewReadyValue.setText(String.valueOf(model.getReadyTimedTaskCount(System.currentTimeMillis())));
		taskValue.setText(wrappedHtml(model.getCurrentTask(), 520));
		progress.setValue(model.getProgressPercent());
		progress.setString(model.getProgressPercent() + "% to max total");
		skillList.removeAll();
		skillDetail.removeAll();
		if (detailToRestore == null)
		{
			skillCards.show(skillContent, SKILL_LIST);
		}
		skillList.add(pageHeading("Skills", "Choose a skill to read its complete progression path."));
		if (!model.getSkillPlans().isEmpty())
		{
			skillGrid.removeAll();
			skillGrid.setOpaque(false);
			skillGrid.setAlignmentX(Component.LEFT_ALIGNMENT);
			skillGrid.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));
			for (PathToMaxViewModel.SkillPlanRow skill : model.getSkillPlans())
			{
				skillGrid.add(skillPlanCard(skill));
			}
			skillList.add(skillGrid);
			updateSkillGridColumns();
		}
		else if (model.getSkillLevels().isEmpty())
		{
			skillList.add(infoCard("NO STATS YET", "Account stats will populate this view after login or manual entry."));
		}
		else
		{
			model.getSkillLevels().forEach((skill, level) -> skillList.add(skillRow(skill, level)));
		}
		skillList.add(Box.createVerticalStrut(24));
		skillList.add(skillsMethodExclusionPanel);
		skillList.revalidate();
		skillList.repaint();
		skillDetail.revalidate();
		skillDetail.repaint();
		populateTimeline(model);
		populateOverviewSteps(model);
		populateTimedTasks(timedTaskList, model.getTimedTasks(), false);
		populateTimedTasks(overviewTasks, model.getTimedTasks(), true);
		populateOverviewSkillMap(model);
		populateOverviewAssumptions(model.getAssumptions());
		PathToMaxViewModel.StorageSummary storage = model.getStorageSummary();
		setEvidenceState(bankEvidenceState, storage.isBankApplied());
		setEvidenceState(seedVaultEvidenceState, storage.isSeedVaultApplied());
		bankStatus.setText(wrappedHtml(storageEvidenceSummary(storage), 720));
		bankStatus.setToolTipText(model.getBankStatus());
		bankStatus.setVisible(true);
		supplyList.removeAll();
		if (model.getSupplies().isEmpty())
		{
			String heading = model.getAccountType().contains("Ultimate Ironman")
				? "ULTIMATE IRONMAN STORAGE" : "NO STORAGE SUPPLIES APPLIED";
			supplyList.add(infoCard(heading, model.getBankStatus()));
		}
		else
		{
			for (PathToMaxViewModel.SupplyRow supply : model.getSupplies())
			{
				supplyList.add(supplyCard(supply));
				supplyList.add(Box.createVerticalStrut(8));
			}
		}
		supplyList.revalidate();
		supplyList.repaint();
		updateCountdownTimer();
		fontScaler.scale(dialog.getContentPane(), fontScalePercent);
		refreshIntrinsicHeights(dialog.getContentPane());
		updateOverviewGridColumns();
		updateOverviewMetricsLayout();
		updateSkillGridColumns();
		if (detailToRestore != null)
		{
			PathToMaxViewModel.SkillPlanRow restored = findSkillPlan(model, detailToRestore);
			if (restored != null)
			{
				showSkillDetail(restored, false);
				SwingUtilities.invokeLater(() -> skillDetailScroll.getViewport().setViewPosition(detailScroll));
			}
			else
			{
				selectedSkillDetail = null;
				skillCards.show(skillContent, SKILL_LIST);
			}
		}
	}

