	private void updateSkillGridColumns()
	{
		int availableWidth = skillListScroll.getViewport().getWidth() - 56;
		int preferredWidth = Math.round(190 * fontScalePercent / 100f);
		int gap = 12;
		int columns = Math.max(1, Math.min(5,
			(availableWidth + gap) / Math.max(1, preferredWidth + gap)));
		GridLayout layout = (GridLayout) skillGrid.getLayout();
		if (layout.getColumns() != columns)
		{
			layout.setColumns(columns);
			skillGrid.revalidate();
		}
		Dimension preferred = skillGrid.getPreferredSize();
		skillGrid.setMaximumSize(new Dimension(Integer.MAX_VALUE, preferred.height));
	}

	private ImageIcon skillIcon(String skillName, int size)
	{
		if (skillIconManager == null)
		{
			return null;
		}
		for (Skill skill : Skill.values())
		{
			if (skill.getName().equalsIgnoreCase(skillName))
			{
				String cacheKey = skill.name() + ":" + size;
				ImageIcon cached = skillIcons.get(cacheKey);
				if (cached != null)
				{
					return cached;
				}
				BufferedImage image = skillIconManager.getSkillImage(skill);
				ImageIcon icon = image == null ? null
					: new ImageIcon(ImageUtil.resizeImage(image, size, size));
				if (icon != null)
				{
					skillIcons.put(cacheKey, icon);
				}
				return icon;
			}
		}
		return null;
	}

	private void showSkillDetail(PathToMaxViewModel.SkillPlanRow skill)
	{
		showSkillDetail(skill, true);
	}

	private void showSkillDetail(PathToMaxViewModel.SkillPlanRow skill, boolean resetScroll)
	{
		selectedSkillDetail = skill.getSkill();
		skillDetail.removeAll();
		skillDetail.add(linkButton("<  All skills", () ->
		{
			selectedSkillDetail = null;
			skillCards.show(skillContent, SKILL_LIST);
		}));
		skillDetail.add(Box.createVerticalStrut(18));
		boolean hasStoredProjection = !skill.getConversions().isEmpty();
		String summaryDetail = hasStoredProjection
			? formatXp(skill.getBankedExperienceTenths()) + " currently usable stored XP | "
				+ formatXp(skill.getRemainingAfterBankTenths()) + " XP remains before future-level conversions"
			: String.format(java.util.Locale.ROOT, "Level %d | %,d XP remaining to level 99",
				skill.getLevel(), skill.getRemainingExperience());
		skillDetail.add(skillHero(skill, summaryDetail));
		skillDetail.add(Box.createVerticalStrut(18));
		if (!skill.getRequirements().isEmpty())
		{
			skillDetail.add(requirementsCard(skill.getRequirements()));
			skillDetail.add(Box.createVerticalStrut(22));
		}
		if (!skill.getStages().isEmpty())
		{
			skillDetail.add(sectionHeading("YOUR ROUTE", "A level-by-level path using your selected strategy."));
			skillDetail.add(Box.createVerticalStrut(12));
			for (PathToMaxViewModel.SkillStageRow stage : skill.getStages())
			{
				String detail = stage.getMethod() + (hasStoredProjection
					? " | " + stage.getStoredCoverage() : "");
				JPanel stageCard = stageCard(stage.getFromLevel(), stage.getToLevel(), detail);
				JPanel references = referenceButtons(stage.getReferences());
				if (references.getComponentCount() > 0)
				{
					stageCard.add(Box.createVerticalStrut(14));
					JLabel resources = new JLabel("LEARN THIS METHOD");
					resources.setForeground(MUTED);
					resources.setFont(resources.getFont().deriveFont(Font.BOLD, 12f));
					resources.setAlignmentX(Component.LEFT_ALIGNMENT);
					stageCard.add(resources);
					stageCard.add(Box.createVerticalStrut(5));
					stageCard.add(references);
				}
				stageCard.add(Box.createVerticalStrut(10));
				JButton exclude = actionButton("Avoid this method", () ->
					settingsListener.onMethodExcluded(parseSkill(skill.getSkill()), stage.getMethod()));
				exclude.getAccessibleContext().setAccessibleDescription(
					"Exclude " + stage.getMethod() + " from future " + skill.getSkill() + " plans");
				stageCard.add(exclude);
				skillDetail.add(stageCard);
				skillDetail.add(Box.createVerticalStrut(8));
			}
		}
		java.util.List<PathToMaxViewModel.ConversionRow> ignored = new java.util.ArrayList<>();
		for (PathToMaxViewModel.ConversionRow conversion : skill.getConversions())
		{
			if (conversion.getStatus() == PathToMaxViewModel.ConversionStatus.IGNORED)
			{
				ignored.add(conversion);
				continue;
			}
			String badge = conversion.getChoiceKind() == PathToMaxViewModel.ChoiceKind.IMPORTED
				? "BANKED XP CHOICE" : "PATH TO MAX DEFAULT";
			String detail = conversion.getQuantity() + " x " + conversion.getResource()
				+ " | " + conversion.getMethod() + " | "
				+ formatXp(conversion.getExperienceTenths()) + " XP";
			if (conversion.getStatus() == PathToMaxViewModel.ConversionStatus.UNAVAILABLE)
			{
				detail += " | Not calculated by Path to Max yet";
			}
			else if (conversion.getStatus() == PathToMaxViewModel.ConversionStatus.LEVEL_LOCKED)
			{
				detail += " | Banked for a future level";
			}
			skillDetail.add(infoCard(badge, detail));
			skillDetail.add(Box.createVerticalStrut(8));
		}
		if (!ignored.isEmpty())
		{
			StringBuilder detail = new StringBuilder();
			for (PathToMaxViewModel.ConversionRow conversion : ignored)
			{
				if (detail.length() > 0) detail.append(" | ");
				detail.append(conversion.getResource()).append(" (")
					.append(conversion.getQuantity()).append(")");
			}
			skillDetail.add(infoCard("IGNORED BY BANKED EXPERIENCE (" + ignored.size() + ")",
				detail.toString()));
		}
		Skill detailSkill = parseSkill(skill.getSkill());
		skillDetailMethodExclusionPanel.setExclusions(currentMethodExclusions.only(detailSkill));
		if (skillDetailMethodExclusionPanel.isVisible())
		{
			skillDetail.add(Box.createVerticalStrut(18));
			skillDetail.add(skillDetailMethodExclusionPanel);
		}
		fontScaler.scale(skillDetail, fontScalePercent);
		refreshIntrinsicHeights(skillDetail);
		skillDetail.revalidate();
		skillDetail.repaint();
		if (resetScroll)
		{
			skillDetailScroll.getViewport().setViewPosition(new java.awt.Point(0, 0));
		}
		skillCards.show(skillContent, SKILL_DETAIL);
	}

	private static JPanel referenceButtons(
		java.util.List<PathToMaxViewModel.ReferenceLink> references)
	{
		JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setOpaque(false);
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		for (PathToMaxViewModel.ReferenceLink reference : references)
		{
			if (!reference.isAvailable())
			{
				continue;
			}
			String label = reference.getLabel();
			JButton button = referenceLinkButton(label,
				() -> LinkBrowser.browse(reference.getUrl()));
			button.setToolTipText("Open " + label + " in your browser: " + reference.getUrl());
			button.getAccessibleContext().setAccessibleName("Open " + label);
			button.getAccessibleContext().setAccessibleDescription(
				"Opens the training method reference in your browser");
			if (panel.getComponentCount() > 0)
			{
				panel.add(Box.createVerticalStrut(8));
			}
			button.setAlignmentX(Component.LEFT_ALIGNMENT);
			panel.add(button);
		}
		return panel;
	}

	private static JButton referenceLinkButton(String text, Runnable action)
	{
