	private void populateOverviewSteps(PathToMaxViewModel model)
	{
		overviewNextActions.removeAll();
		if (model.getOverviewSteps().isEmpty())
		{
			overviewNextActions.add(infoCard("CURRENT FOCUS", model.getCurrentTask()));
		}
		else
		{
			int limit = Math.min(3, model.getOverviewSteps().size());
			for (int i = 0; i < limit; i++)
			{
				PathToMaxViewModel.OverviewStepRow step = model.getOverviewSteps().get(i);
				JPanel panel = infoCard(step.getPhase().toUpperCase(java.util.Locale.ROOT)
					+ " | " + step.getSkill().toUpperCase(java.util.Locale.ROOT),
					step.getTitle() + " - " + step.getDetail());
				PathToMaxViewModel.SkillPlanRow skill = findSkillPlan(model, step.getSkill());
				if (skill != null)
				{
					panel.add(Box.createVerticalStrut(10));
					panel.add(actionButton("Read more about " + skill.getSkill() + "  >", () ->
					{
						navigation.get("Skills").setSelected(true);
						cards.show(content, "Skills");
						showSkillDetail(skill);
					}));
				}
				overviewNextActions.add(panel);
				overviewNextActions.add(Box.createVerticalStrut(8));
			}
		}
		overviewNextActions.revalidate();
		overviewNextActions.repaint();
	}

	private void populateOverviewSkillMap(PathToMaxViewModel model)
	{
		overviewSkillMap.removeAll();
		overviewHasSkills = !model.getSkillPlans().isEmpty();
		if (model.getSkillPlans().isEmpty())
		{
			overviewSkillMap.add(detailLabel("Log in and generate a plan to build your full account overview."));
		}
		else
		{
			for (PathToMaxViewModel.SkillPlanRow skill : model.getSkillPlans())
			{
				overviewSkillMap.add(overviewSkillCard(skill));
			}
		}
		updateOverviewGridColumns();
		overviewSkillMap.revalidate();
		Dimension preferred = overviewSkillMap.getPreferredSize();
		overviewSkillMap.setMaximumSize(new Dimension(Integer.MAX_VALUE, preferred.height));
		overviewSkillMap.repaint();
	}

	private void updateOverviewGridColumns()
	{
		GridLayout layout = (GridLayout) overviewSkillMap.getLayout();
		int columns = 1;
		if (overviewHasSkills && overviewScroll != null)
		{
			int preferredCardWidth = Math.round(165 * fontScalePercent / 100f);
			int availableWidth = overviewScroll.getViewport().getWidth() - 56;
			int gap = 10;
			columns = Math.max(1, Math.min(4,
				(availableWidth + gap) / Math.max(1, preferredCardWidth + gap)));
		}
		if (layout.getColumns() != columns)
		{
			layout.setColumns(columns);
			overviewSkillMap.revalidate();
		}
		Dimension preferred = overviewSkillMap.getPreferredSize();
		overviewSkillMap.setMaximumSize(new Dimension(Integer.MAX_VALUE, preferred.height));
	}

	private void updateOverviewMetricsLayout()
	{
		GridLayout layout = (GridLayout) overviewMetrics.getLayout();
		int availableWidth = overviewScroll == null ? 0 : overviewScroll.getViewport().getWidth() - 56;
		int breakpoint = Math.round(760 * fontScalePercent / 100f);
		boolean stacked = availableWidth <= 0 || availableWidth < breakpoint;
		int rows = stacked ? 2 : 1;
		int columns = stacked ? 2 : 4;
		if (layout.getRows() != rows || layout.getColumns() != columns)
		{
			layout.setRows(rows);
			layout.setColumns(columns);
		}
		Dimension preferred = overviewMetrics.getPreferredSize();
		overviewMetrics.setMaximumSize(new Dimension(Integer.MAX_VALUE, preferred.height));
		overviewMetrics.revalidate();
	}

