	private void populateOverviewAssumptions(java.util.List<String> assumptions)
	{
		overviewAssumptions.removeAll();
		if (assumptions.isEmpty())
		{
			overviewAssumptions.add(detailLabel("No planning warnings or assumptions."));
		}
		else
		{
			java.util.List<String> warnings = new java.util.ArrayList<>();
			java.util.List<String> notes = new java.util.ArrayList<>();
			for (String assumption : assumptions)
			{
				String lower = assumption.toLowerCase(java.util.Locale.ROOT);
				if (lower.contains("disabled") || lower.contains("manual review")
					|| lower.contains("no reviewed") || lower.contains("must be opened")
					|| lower.contains("unknown")) warnings.add(assumption);
				else notes.add(assumption);
			}
			if (!warnings.isEmpty())
			{
				overviewAssumptions.add(planningNotesCard("ACTION REQUIRED", warnings));
				overviewAssumptions.add(Box.createVerticalStrut(10));
			}
			if (!notes.isEmpty()) overviewAssumptions.add(planningNotesCard("ASSUMPTIONS", notes));
		}
		overviewAssumptions.revalidate();
		overviewAssumptions.repaint();
	}

	private static JPanel planningNotesCard(String title, java.util.List<String> values)
	{
		JPanel card = card();
		card.add(caption(values.size() + " " + title));
		card.add(Box.createVerticalStrut(8));
		for (int index = 0; index < values.size(); index++)
		{
