	private static String formatXp(long tenths)
	{
		long whole = tenths / 10;
		return String.format(java.util.Locale.ROOT, "%,d%s", whole,
			tenths % 10 == 0 ? "" : "." + tenths % 10);
	}

	private static String formatCompact(long value)
	{
		if (value >= 1_000_000_000L)
		{
			return String.format(java.util.Locale.ROOT, "%.1fb", value / 1_000_000_000.0);
		}
		if (value >= 1_000_000L)
		{
			return String.format(java.util.Locale.ROOT, "%.1fm", value / 1_000_000.0);
		}
		if (value >= 1_000L)
		{
			return String.format(java.util.Locale.ROOT, "%.1fk", value / 1_000.0);
		}
		return Long.toString(value);
	}

	private void populateTimeline(PathToMaxViewModel model)
	{
		timelineList.removeAll();
		if (model.getTimelineSteps().isEmpty())
		{
			String message = model.getSkillPlans().isEmpty()
				? "Log in and generate a plan to build your whole-account worklist."
				: "All planned skills are level 99.";
			timelineList.add(infoCard("WORKLIST", message));
		}
		else
		{
			java.util.Map<String, java.util.List<PathToMaxViewModel.TimelineStepRow>> blocks =
				new java.util.LinkedHashMap<>();
			for (PathToMaxViewModel.TimelineStepRow step : model.getTimelineSteps())
			{
				blocks.computeIfAbsent(step.getPriorityBlockId(), ignored -> new java.util.ArrayList<>())
					.add(step);
			}
			for (java.util.List<PathToMaxViewModel.TimelineStepRow> block : blocks.values())
			{
				timelineList.add(timelineBlockCard(model, block));
				timelineList.add(Box.createVerticalStrut(12));
			}
			int maxed = model.getMaxedSkillCount();
			if (maxed > 0)
			{
				timelineList.add(infoCard("MAXED SKILLS (" + maxed + ")",
					"Already complete and omitted from the active worklist."));
			}
		}
		timelineList.revalidate();
		timelineList.repaint();
	}

