	private void populateTimedTasks(JPanel target,
		java.util.List<PathToMaxViewModel.TimedTaskRow> tasks, boolean compact)
	{
		target.removeAll();
		Map<String, JLabel> labels = compact ? overviewTaskStatusLabels : timedTaskStatusLabels;
		labels.clear();
		if (!compact)
		{
			timedTaskStates.clear();
		}
		java.util.List<PathToMaxViewModel.TimedTaskRow> displayed = new java.util.ArrayList<>(tasks);
		long now = System.currentTimeMillis();
		if (compact)
		{
			displayed.removeIf(task -> task.isPaused() || task.isComplete());
		}
		displayed.sort(java.util.Comparator
			.comparingInt((PathToMaxViewModel.TimedTaskRow task) -> timedTaskRank(task, now))
			.thenComparingLong(task -> task.getDueAtEpochMillis() == null
				? Long.MAX_VALUE : task.getDueAtEpochMillis()));
		if (displayed.isEmpty())
		{
			target.add(detailLabel(compact ? "Nothing needs attention right now."
				: "No timed tasks scheduled yet."));
		}
		else
		{
			int limit = compact ? Math.min(3, displayed.size()) : displayed.size();
			for (int i = 0; i < limit; i++)
			{
				PathToMaxViewModel.TimedTaskRow task = displayed.get(i);
				target.add(timedTaskCard(task, compact, labels));
				if (!compact)
				{
					timedTaskStates.put(task.getId(), timedTaskStateSignature(task, now));
				}
				target.add(Box.createVerticalStrut(8));
			}
		}
		target.revalidate();
		target.repaint();
	}

	private static int timedTaskRank(PathToMaxViewModel.TimedTaskRow task, long now)
	{
		if (task.isComplete()) return 3;
		if (task.isPaused()) return 2;
		String status = task.getDisplayStatus(now);
		return "Ready".equalsIgnoreCase(status) || "Needs attention".equalsIgnoreCase(status)
			? 0 : 1;
	}

	private JPanel timedTaskCard(PathToMaxViewModel.TimedTaskRow task, boolean compact,
		Map<String, JLabel> labels)
	{
		long now = System.currentTimeMillis();
		JPanel panel = infoCard(timedTaskCaption(task, now),
			task.getTitle() + " - " + task.getDetail());
		labels.put(task.getId(), (JLabel) panel.getComponent(0));
		if (!compact)
		{
			JPanel actions = verticalPanel();
			actions.setOpaque(false);
			actions.setAlignmentX(Component.LEFT_ALIGNMENT);
			if (task.isPaused() && task.supportsPause())
			{
				actions.add(actionButton("Resume",
					() -> timedTaskListener.onPauseChanged(task.getId(), false)));
			}
			else if (!task.isComplete())
			{
				if (task.canComplete(now))
				{
					actions.add(actionButton("Complete", () -> timedTaskListener.onComplete(task.getId())));
				}
				if (task.canRemindLater(now))
				{
					if (actions.getComponentCount() > 0) actions.add(Box.createVerticalStrut(7));
					actions.add(actionButton("Remind in " + snoozeMinutes.getValue() + " min",
						() -> timedTaskListener.onSnooze(task.getId())));
				}
				if (task.supportsPause())
				{
					if (actions.getComponentCount() > 0) actions.add(Box.createVerticalStrut(7));
					actions.add(actionButton("Pause reminders",
						() -> timedTaskListener.onPauseChanged(task.getId(), true)));
				}
			}
			if (actions.getComponentCount() > 0)
			{
				panel.add(Box.createVerticalStrut(12));
				panel.add(actions);
			}
		}
		Dimension preferred = panel.getPreferredSize();
		panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, preferred.height));
		return panel;
	}

