	private void refreshCountdowns()
	{
		long now = System.currentTimeMillis();
		overviewReadyValue.setText(String.valueOf(currentModel.getReadyTimedTaskCount(now)));
		boolean stateChanged = false;
		for (PathToMaxViewModel.TimedTaskRow task : currentModel.getTimedTasks())
		{
			String signature = timedTaskStateSignature(task, now);
			if (!signature.equals(timedTaskStates.get(task.getId())))
			{
				stateChanged = true;
				break;
			}
		}
		if (stateChanged)
		{
			populateTimedTasks(timedTaskList, currentModel.getTimedTasks(), false);
			populateTimedTasks(overviewTasks, currentModel.getTimedTasks(), true);
		}
		else
		{
			for (PathToMaxViewModel.TimedTaskRow task : currentModel.getTimedTasks())
			{
				String caption = timedTaskCaption(task, now);
				JLabel full = timedTaskStatusLabels.get(task.getId());
				JLabel compact = overviewTaskStatusLabels.get(task.getId());
				if (full != null) full.setText(caption);
				if (compact != null) compact.setText(caption);
			}
		}
		updateCountdownTimer();
	}

	private static String timedTaskCaption(PathToMaxViewModel.TimedTaskRow task, long now)
	{
		String status = task.getDisplayStatus(now);
		if (task.getDueAtEpochMillis() != null && !task.isPaused() && !task.isComplete()
			&& task.getDueAtEpochMillis() > now)
		{
			status += " | " + countdown(task.getDueAtEpochMillis(),
				"Ready".equalsIgnoreCase(status) || "Needs attention".equalsIgnoreCase(status)
					|| "Snoozed".equalsIgnoreCase(status));
		}
		return status.toUpperCase(java.util.Locale.ROOT);
	}

	private static String timedTaskStateSignature(PathToMaxViewModel.TimedTaskRow task, long now)
	{
		return task.getDisplayStatus(now) + ":" + task.isPaused() + ":" + task.isComplete()
			+ ":" + task.canComplete(now) + ":" + task.canRemindLater(now);
	}

	private void updateCountdownTimer()
	{
		boolean hasCountdown = currentModel.getTimedTasks().stream()
			.anyMatch(task -> task.getDueAtEpochMillis() != null && !task.isPaused()
				&& !task.isComplete() && task.getDueAtEpochMillis() > System.currentTimeMillis());
		if (dialog.isVisible() && hasCountdown)
		{
			countdownTimer.start();
		}
		else
		{
			countdownTimer.stop();
		}
	}

	public boolean isVisible()
	{
		return dialog.isVisible();
	}

	private static String countdown(long dueAtEpochMillis, boolean reminder)
	{
		long seconds = Math.max(0, (dueAtEpochMillis - System.currentTimeMillis() + 999) / 1000);
		if (seconds == 0)
		{
			return "Ready now";
		}
		long hours = seconds / 3600;
		long minutes = (seconds % 3600) / 60;
		long remainingSeconds = seconds % 60;
		String prefix = reminder ? "Reminder in " : "Due in ";
		return hours > 0 ? String.format(prefix + "%dh %02dm", hours, minutes)
			: String.format(prefix + "%dm %02ds", minutes, remainingSeconds);
	}

	public interface TimedTaskListener
	{
		TimedTaskListener NO_OP = new TimedTaskListener() { };

