		{
			metrics.add(supplyMetric("CREDITED", supply.formatApplied()));
			metrics.add(supplyMetric("NEEDED", supply.formatRequired()));
			metrics.add(supplyMetric("SHORTFALL", supply.formatMissing()));
		}
		panel.add(metrics);
		if (observedOnly)
		{
			panel.add(Box.createVerticalStrut(8));
			panel.add(detailLabel("Observed in the Seed Vault or bank; not yet valued in this plan."));
		}
