	private static JPanel supplyMetric(String label, String value)
	{
		JPanel metric = verticalPanel();
		metric.setOpaque(false);
		metric.add(caption(label));
		metric.add(Box.createVerticalStrut(4));
		JLabel amount = new JLabel(value);
		amount.setForeground(Color.WHITE);
		amount.setFont(amount.getFont().deriveFont(Font.BOLD, 15f));
		metric.add(amount);
		return metric;
	}

	private static JLabel caption(String text)
	{
		JLabel label = new JLabel(text);
		label.setForeground(ACCENT);
		label.setFont(label.getFont().deriveFont(Font.BOLD, 10f));
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	private static JLabel valueLabel()
	{
		JLabel label = new JLabel();
		label.setForeground(Color.WHITE);
		label.setFont(label.getFont().deriveFont(Font.BOLD, 13f));
		return label;
	}

	private static String wrappedHtml(String text, int width)
	{
		return "<html><div style='width:" + width + "px'>" + escapeHtml(text)
			+ "</div></html>";
	}

	private static String escapeHtml(String value)
	{
		return value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	private static JPanel verticalPanel()
	{
		JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		return panel;
	}

	private static JScrollPane scroll(JPanel page)
	{
		JScrollPane scroll = new JScrollPane(new ViewportWidthPanel(page));
		scroll.setBorder(null);
		scroll.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		return scroll;
	}

	private static final class ViewportWidthPanel extends JPanel implements javax.swing.Scrollable
	{
		private ViewportWidthPanel(JPanel contents)
		{
			super(new BorderLayout());
			setBackground(contents.getBackground());
			add(contents, BorderLayout.CENTER);
		}

		@Override
		public Dimension getPreferredScrollableViewportSize() { return getPreferredSize(); }

		@Override
		public int getScrollableUnitIncrement(java.awt.Rectangle visible, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(java.awt.Rectangle visible, int orientation, int direction)
		{
			return Math.max(16, visible.height - 32);
		}

		@Override
		public boolean getScrollableTracksViewportWidth() { return true; }

		@Override
		public boolean getScrollableTracksViewportHeight() { return false; }
	}

	private static JFrame createFrame()
	{
		JFrame frame = new JFrame("Path to Max");
		frame.setResizable(true);
		return frame;
	}

	private static void onEdt(Runnable action)
	{
		if (SwingUtilities.isEventDispatchThread())
		{
			action.run();
		}
		else
		{
			SwingUtilities.invokeLater(action);
		}
	}
}

package com.efficientskilling;

import java.awt.Component;
import java.awt.Font;
import java.util.Map;
import java.util.WeakHashMap;

/** Idempotent recursive font scaling which always scales from each component's original font. */
final class ComponentFontScaler
{
	private final Map<Component, Font> baseFonts = new WeakHashMap<>();

	void scale(Component component, int percent)
	{
		float factor = Math.max(80, Math.min(150, percent)) / 100f;
		Font font = component.getFont();
		if (font != null)
		{
			Font base = baseFonts.computeIfAbsent(component, ignored -> font);
			component.setFont(base.deriveFont(Math.max(9f, base.getSize2D() * factor)));
		}
		if (component instanceof java.awt.Container)
		{
			for (Component child : ((java.awt.Container) component).getComponents()) scale(child, percent);
		}
	}
}

package com.efficientskilling.timers;

import com.efficientskilling.planner.TimedTaskState;
import java.util.ArrayList;
