}

package com.efficientskilling.timers;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.inject.Inject;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Optional;
import net.runelite.client.RuneLite;
import lombok.extern.slf4j.Slf4j;

/**
 * Disk repository for per-account timed-task state. Callers must invoke this
 * repository away from the client thread.
 */
@Slf4j
public class TimedTaskStateRepository
{
	public static final int SCHEMA_VERSION = 1;
	private static final String DIRECTORY_NAME = "efficient-skilling";
	private final Gson gson;
	private final Path storageDirectory;

	@Inject
	public TimedTaskStateRepository(Gson gson)
	{
		this(gson, RuneLite.RUNELITE_DIR.toPath().resolve(DIRECTORY_NAME));
	}

	/** Constructor intended for tests and explicitly configured storage roots. */
	public TimedTaskStateRepository(Gson gson, Path storageDirectory)
	{
		this.gson = gson;
		this.storageDirectory = storageDirectory.toAbsolutePath().normalize();
	}

	public <T> Optional<T> load(String accountIdentity, Class<T> payloadType)
	{
		Path file = fileFor(accountIdentity);
		if (!Files.isRegularFile(file))
		{
			return Optional.empty();
		}

		try
		{
			Envelope envelope = gson.fromJson(new String(Files.readAllBytes(file), StandardCharsets.UTF_8), Envelope.class);
			if (envelope == null || envelope.schemaVersion != SCHEMA_VERSION || envelope.payload == null)
			{
				log.debug("Ignoring unsupported or incomplete timed-task state in {}", file);
				return Optional.empty();
			}
			return Optional.ofNullable(gson.fromJson(envelope.payload, payloadType));
		}
		catch (IOException | RuntimeException ex)
		{
			// Preserve the original file so a future version or the user can recover it.
			log.debug("Unable to read timed-task state from {}", file, ex);
			return Optional.empty();
		}
	}

	public <T> void save(String accountIdentity, T payload) throws IOException
	{
		Files.createDirectories(storageDirectory);
		Path destination = fileFor(accountIdentity);
		Path temporary = destination.resolveSibling(destination.getFileName() + ".tmp");
		Envelope envelope = new Envelope(SCHEMA_VERSION, gson.toJsonTree(payload));
		Files.write(temporary, gson.toJson(envelope).getBytes(StandardCharsets.UTF_8));
		try
		{
			Files.move(temporary, destination, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
		}
		catch (AtomicMoveNotSupportedException ex)
		{
			Files.move(temporary, destination, StandardCopyOption.REPLACE_EXISTING);
		}
	}

	Path fileFor(String accountIdentity)
	{
		String identity = accountIdentity == null ? "" : accountIdentity.trim().toLowerCase(java.util.Locale.ROOT);
		return storageDirectory.resolve("timed-tasks-" + sha256(identity) + ".json").normalize();
	}

	private static String sha256(String value)
	{
		try
		{
			byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
			StringBuilder result = new StringBuilder(digest.length * 2);
			for (byte part : digest)
			{
				result.append(String.format("%02x", part & 0xff));
			}
			return result.toString();
		}
		catch (NoSuchAlgorithmException ex)
		{
			throw new IllegalStateException("SHA-256 is required by the Java runtime", ex);
		}
	}

	private static final class Envelope
	{
		private int schemaVersion;
		private JsonElement payload;

		private Envelope(int schemaVersion, JsonElement payload)
		{
			this.schemaVersion = schemaVersion;
			this.payload = payload;
		}
	}
}

package com.efficientskilling;

import com.efficientskilling.planner.MethodExclusions;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Font;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.BiConsumer;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.api.Skill;
import net.runelite.client.ui.ColorScheme;

/** Persistent exclusion manager with an individual restore action for every avoided method. */
final class MethodExclusionPanel extends JPanel
{
	private static final Color ACCENT = new Color(255, 152, 31);
	private static final Color MUTED = new Color(170, 170, 170);
	private final BiConsumer<Skill, String> restoreListener;
	private final Runnable clearListener;
	private final boolean hideWhenEmpty;
	private final JPanel methods = verticalPanel();
	private final Map<Skill, Map<String, JButton>> restoreButtons = new EnumMap<>(Skill.class);

	MethodExclusionPanel(BiConsumer<Skill, String> restoreListener, Runnable clearListener)
	{
		this(restoreListener, clearListener, false);
	}

	MethodExclusionPanel(BiConsumer<Skill, String> restoreListener, Runnable clearListener,
		boolean hideWhenEmpty)
	{
		this.restoreListener = restoreListener;
		this.clearListener = clearListener;
		this.hideWhenEmpty = hideWhenEmpty;
		if (hideWhenEmpty) setVisible(false);
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
			BorderFactory.createEmptyBorder(16, 18, 16, 18)));
		setAlignmentX(Component.LEFT_ALIGNMENT);
		JLabel caption = new JLabel("AVOIDED METHODS");
		caption.setForeground(ACCENT);
		caption.setFont(caption.getFont().deriveFont(Font.BOLD));
		caption.setAlignmentX(Component.LEFT_ALIGNMENT);
		add(caption);
		add(Box.createVerticalStrut(6));
		JLabel explanation = new JLabel("<html><div style='width:620px'>Restore one method here if an exclusion leaves a skill without route coverage.</div></html>");
		explanation.setForeground(MUTED);
		explanation.setAlignmentX(Component.LEFT_ALIGNMENT);
		add(explanation);
		add(Box.createVerticalStrut(10));
		add(methods);
		SettingsPanelLayout.bind(this);
	}

	void setExclusions(MethodExclusions exclusions)
	{
		boolean emptyExclusions = exclusions == null || exclusions.isEmpty();
		setVisible(!hideWhenEmpty || !emptyExclusions);
		methods.removeAll();
		restoreButtons.clear();
		if (emptyExclusions)
		{
			JLabel empty = new JLabel("No methods are currently avoided.");
			empty.setForeground(MUTED);
			empty.setAlignmentX(Component.LEFT_ALIGNMENT);
			methods.add(empty);
		}
		else
		{
			exclusions.asMap().forEach((skill, names) -> names.forEach(name -> addMethod(skill, name)));
			methods.add(Box.createVerticalStrut(8));
			JButton clear = button("Restore all methods");
			clear.addActionListener(event -> clearListener.run());
			clear.getAccessibleContext().setAccessibleDescription("Remove every method exclusion");
			methods.add(clear);
		}
		methods.revalidate();
		methods.repaint();
		SettingsPanelLayout.refresh(this);
	}

	JButton restoreButton(Skill skill, String method)
	{
		return restoreButtons.getOrDefault(skill, java.util.Collections.emptyMap()).get(method);
	}

	private void addMethod(Skill skill, String method)
	{
		JPanel row = new JPanel(new BorderLayout(12, 0));
		row.setOpaque(false);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		JLabel label = new JLabel("<html><b>" + escape(skill.getName()) + "</b><br>" + escape(method) + "</html>");
		label.setForeground(Color.WHITE);
		row.add(label, BorderLayout.CENTER);
		JButton restore = button("Restore");
		restore.addActionListener(event -> restoreListener.accept(skill, method));
		restore.getAccessibleContext().setAccessibleName("Restore " + method + " for " + skill.getName());
		row.add(restore, BorderLayout.EAST);
		row.setMaximumSize(new java.awt.Dimension(920, Math.max(48, row.getPreferredSize().height)));
		methods.add(row);
		methods.add(Box.createVerticalStrut(5));
		restoreButtons.computeIfAbsent(skill, ignored -> new LinkedHashMap<>()).put(method, restore);
	}

	private static JPanel verticalPanel()
	{
		JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setOpaque(false);
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		return panel;
	}

	private static JButton button(String text)
	{
		JButton button = new JButton(text);
		button.setForeground(Color.WHITE);
		button.setBackground(new Color(55, 55, 55));
		button.setFocusPainted(true);
		button.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(new Color(75, 75, 75)),
			BorderFactory.createEmptyBorder(7, 12, 7, 12)));
		return button;
	}

	private static String escape(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

